{
  "name": "Benson's Personal Finance Pro",
  "description": "A comprehensive personal finance and budgeting application modeled after a robust Excel-VBA system, featuring automated tithing logic, classification-based ledgers, monthly summaries, and net worth tracking."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type AccountType = 'Checking' | 'Savings' | 'Credit' | 'Investment';

export interface Account {
  id: string;
  name: string;
  type: AccountType;
  balance: number;
  note?: string;
}

export interface Classification {
  id: string;
  name: string;
  color: string;
}

export interface Category {
  id: string;
  name: string;
  classificationId: string;
  balance: number;
  monthlyBudget: number;
}

export type TransactionType = 
  | 'Standard' 
  | 'Income' 
  | 'Interest' 
  | 'Category Transfer' 
  | 'Transfer to Savings' 
  | 'Transfer to Checking' 
  | 'Credit Payment' 
  | 'Transfer between Checking';

export interface Transaction {
  id: string;
  date: string;
  categoryId: string;
  accountId: string;
  amount: number;
  description: string;
  type: TransactionType;
  toCategoryId?: string;
  fromCategoryId?: string;
  toAccountId?: string;
}

export interface AppState {
  accounts: Account[];
  classifications: Classification[];
  categories: Category[];
  transactions: Transaction[];
}

export const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
  }).format(amount);
};

export const generateId = () => Math.random().toString(36).substr(2, 9);

export const getMonthYearKey = (date: Date | string) => {
  const d = new Date(date);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
};

export const getMonthLabel = (date: Date | string) => {
  return new Date(date).toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
};

import { useState, useCallback, useMemo } from 'react';
import { AppState, Transaction, TransactionType, Category, Account } from '../types';
import { INITIAL_DATA } from '../constants';
import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(INITIAL_DATA);

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id };
        newTransactions.push(tx);

        // Update Category Balance
        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        // Update Account Balance
        updatedAccounts = updatedAccounts.map(acc => {
          if (acc.id === tx.accountId) {
            return { ...acc, balance: acc.balance + tx.amount };
          }
          return acc;
        });
      };

      // 1. Core Transaction
      processSingle(txData);

      // 2. Special Logic: Income triggers Tithing (10%)
      if (txData.type === 'Income' || (txData.categoryId === 'cat-main-income' && txData.amount > 0)) {
        const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
        if (tithingCategory) {
          processSingle({
            ...txData,
            categoryId: tithingCategory.id,
            amount: txData.amount * 0.1,
            description: `Tithing from: ${txData.description}`,
            type: 'Standard'
          });
        }
      }

      // 3. Special Logic: Interest
      if (txData.type === 'Interest' && txData.toCategoryId) {
        // Interest is already recorded once. 
        // VBA records "Interest" category AND "toCategory".
        // We simulate that by adding another entry if toCategoryId exists
        processSingle({
          ...txData,
          categoryId: txData.toCategoryId,
          type: 'Standard'
        });
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string) => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'system',
          categoryId: catId || 'system',
          type: 'Standard'
        };
        newTransactions.push(tx);

        if (catId) {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId) {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      switch (type) {
        case 'Category Transfer':
          recordTx(fromAccountId, fromCategoryId, -amount, description);
          recordTx(toAccountId, toCategoryId, amount, description);
          break;
        case 'Transfer to Savings':
          recordTx(fromAccountId, undefined, -amount, description);
          recordTx(undefined, toCategoryId, amount, description);
          break;
        case 'Transfer to Checking':
          recordTx(toAccountId, toCategoryId, amount, description);
          recordTx(undefined, fromCategoryId, -amount, description);
          break;
        case 'Credit Payment':
          recordTx(fromAccountId, undefined, -amount, description);
          recordTx(toAccountId, undefined, amount, description);
          break;
        case 'Transfer between Checking':
          recordTx(fromAccountId, undefined, -amount, description);
          recordTx(toAccountId, undefined, amount, description);
          break;
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, isNewClassification: boolean) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];

      if (isNewClassification || !classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({
          id: classId,
          name: classificationName,
          color: 'bg-gray-100'
        });
      }

      const newCategory: Category = {
        id: `cat-${generateId()}`,
        name,
        classificationId: classId,
        balance: 0,
        monthlyBudget: 0
      };

      return {
        ...prev,
        classifications: newClassifications,
        categories: [...prev.categories, newCategory]
      };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory
  };
};

import React from 'react';
import { LayoutDashboard, ReceiptText, PieChart, Landmark, Settings, PlusCircle, ArrowRightLeft } from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Balance Statement', icon: LayoutDashboard },
    { id: 'ledgers', label: 'Ledgers', icon: ReceiptText },
    { id: 'summary', label: 'Summary', icon: PieChart },
    { id: 'networth', label: 'Net Worth', icon: Landmark },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 bg-slate-900 text-white flex flex-col shrink-0">
        <div className="p-6">
          <h1 className="text-xl font-bold tracking-tight flex items-center gap-2">
            <span className="w-8 h-8 bg-blue-500 rounded flex items-center justify-center">B</span>
            Finance Pro
          </h1>
          <p className="text-slate-400 text-xs mt-1">Personal Budget Manager</p>
        </div>

        <nav className="flex-1 px-4 py-4 space-y-1">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${
                activeTab === item.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' 
                  : 'text-slate-400 hover:text-white hover:bg-slate-800'
              }`}
            >
              <item.icon size={18} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-800 space-y-2">
          <button className="w-full flex items-center gap-2 text-xs text-slate-400 hover:text-white transition-colors">
            <Settings size={14} />
            Settings
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0">
          <h2 className="text-lg font-semibold text-slate-800">
            {menuItems.find(m => m.id === activeTab)?.label || 'Page'}
          </h2>
          <div className="flex items-center gap-4">
            <span className="text-xs text-slate-400">Date Last Updated: {new Date().toLocaleDateString()}</span>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-8">
          <div className="max-w-7xl mx-auto space-y-8">
            {children}
          </div>
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState } from 'react';
import { Plus, ArrowRightLeft, Calendar, DollarSign, Tag, Landmark, FileText } from 'lucide-react';
import { AppState, TransactionType } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ state, onAddTransaction, onExecuteTransfer }) => {
  const [activeMode, setActiveMode] = useState<'transact' | 'transfer'>('transact');
  const [formData, setFormData] = useState({
    categoryId: '',
    date: new Date().toISOString().split('T')[0],
    accountId: '',
    amount: '',
    description: '',
    type: 'Standard' as TransactionType,
    toCategoryId: '',
    toAccountId: '',
    fromCategoryId: '',
    fromAccountId: '',
    transferType: TRANSFER_TYPES[0]
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (activeMode === 'transact') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: parseFloat(formData.amount),
        description: formData.description,
        type: formData.type,
        toCategoryId: formData.toCategoryId
      });
    } else {
      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: parseFloat(formData.amount),
        description: formData.description,
        fromAccountId: formData.fromAccountId,
        toAccountId: formData.toAccountId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }
    // Reset basic fields
    setFormData(prev => ({ ...prev, amount: '', description: '' }));
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden h-fit">
      <div className="flex border-b border-slate-100">
        <button 
          onClick={() => setActiveMode('transact')}
          className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors ${activeMode === 'transact' ? 'text-blue-600 bg-blue-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
        >
          <Plus size={16} /> Transact
        </button>
        <button 
          onClick={() => setActiveMode('transfer')}
          className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors ${activeMode === 'transfer' ? 'text-blue-600 bg-blue-50/50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50'}`}
        >
          <ArrowRightLeft size={16} /> Transfers
        </button>
      </div>

      <form onSubmit={handleSubmit} className="p-6 space-y-4">
        {activeMode === 'transact' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Category</label>
                <div className="relative">
                  <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                  <select 
                    value={formData.categoryId} 
                    onChange={e => setFormData({...formData, categoryId: e.target.value})}
                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                    required
                  >
                    <option value="">Select Category</option>
                    {state.categories.map(cat => (
                      <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Date</label>
                <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                  <input 
                    type="date" 
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                    required
                  />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Account</label>
                <div className="relative">
                  <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                  <select 
                    value={formData.accountId} 
                    onChange={e => setFormData({...formData, accountId: e.target.value})}
                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                    required
                  >
                    <option value="">Select Account</option>
                    {state.accounts.map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Amount</label>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                  <input 
                    type="number" 
                    step="0.01"
                    placeholder="0.00"
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: e.target.value})}
                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                    required
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Description</label>
              <div className="relative">
                <FileText className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <input 
                  type="text" 
                  placeholder="What was this for?"
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  required
                />
              </div>
            </div>

            {formData.categoryId === state.categories.find(c => c.name === 'Interest')?.id && (
              <div className="pt-2">
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider text-orange-600">Apply Interest To Category</label>
                <select 
                  value={formData.toCategoryId} 
                  onChange={e => setFormData({...formData, toCategoryId: e.target.value})}
                  className="w-full px-4 py-2 bg-orange-50 border border-orange-200 rounded-lg text-sm focus:outline-none"
                >
                  <option value="">(Optional) Destination Category</option>
                  {state.categories.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))}
                </select>
              </div>
            )}
          </>
        ) : (
          <>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Transfer Type</label>
              <select 
                value={formData.transferType} 
                onChange={e => setFormData({...formData, transferType: e.target.value as any})}
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              >
                {TRANSFER_TYPES.map(type => (
                  <option key={type} value={type}>{type}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">From Account/Cat</label>
                <select 
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  value={formData.fromAccountId || formData.fromCategoryId}
                  onChange={e => {
                    const isAccount = state.accounts.some(a => a.id === e.target.value);
                    setFormData({
                      ...formData,
                      fromAccountId: isAccount ? e.target.value : '',
                      fromCategoryId: isAccount ? '' : e.target.value
                    });
                  }}
                >
                  <option value="">Select Source</option>
                  <optgroup label="Accounts">
                    {state.accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </optgroup>
                  <optgroup label="Categories">
                    {state.categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                  </optgroup>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">To Account/Cat</label>
                <select 
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  value={formData.toAccountId || formData.toCategoryId}
                  onChange={e => {
                    const isAccount = state.accounts.some(a => a.id === e.target.value);
                    setFormData({
                      ...formData,
                      toAccountId: isAccount ? e.target.value : '',
                      toCategoryId: isAccount ? '' : e.target.value
                    });
                  }}
                >
                  <option value="">Select Destination</option>
                  <optgroup label="Accounts">
                    {state.accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </optgroup>
                  <optgroup label="Categories">
                    {state.categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                  </optgroup>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Amount</label>
                <input 
                  type="number" 
                  step="0.01"
                  placeholder="0.00"
                  value={formData.amount}
                  onChange={e => setFormData({...formData, amount: e.target.value})}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Date</label>
                <input 
                  type="date" 
                  value={formData.date}
                  onChange={e => setFormData({...formData, date: e.target.value})}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1.5 uppercase tracking-wider">Description</label>
              <input 
                type="text" 
                placeholder="Transfer notes..."
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                required
              />
            </div>
          </>
        )}

        <button 
          type="submit"
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-lg text-sm shadow-md transition-all active:scale-95 mt-2"
        >
          {activeMode === 'transact' ? 'Submit Transaction' : 'Record Transfer'}
        </button>
      </form>
    </div>
  );
};

export default TransactionPanel;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer }) => {
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => 
        t.categoryId === cat.id && 
        getMonthYearKey(t.date) === currentMonth
      );

      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);

      return {
        ...cat,
        monthlyAdded: added,
        monthlySpent: spent
      };
    });
  }, [state, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const totals = useMemo(() => {
    const checking = state.accounts.filter(a => a.type === 'Checking').reduce((sum, a) => sum + a.balance, 0);
    const savings = state.accounts.filter(a => a.type === 'Savings').reduce((sum, a) => sum + a.balance, 0);
    const credit = state.accounts.filter(a => a.type === 'Credit').reduce((sum, a) => sum + a.balance, 0);
    const investments = state.accounts.filter(a => a.type === 'Investment').reduce((sum, a) => sum + a.balance, 0);

    return { checking, savings, credit, net: checking + savings + credit + investments };
  }, [state.accounts]);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Category List (Left & Center) */}
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left text-sm">
