interface LedgersProps {
  state: AppState;
}

const Ledgers: React.FC<LedgersProps> = ({ state }) => {
  const [activeClassId, setActiveClassId] = useState(state.classifications[0]?.id);
  const [searchTerm, setSearchTerm] = useState('');

  const activeTransactions = state.transactions.filter(tx => {
    const cat = state.categories.find(c => c.id === tx.categoryId);
    return cat?.classificationId === activeClassId && 
           (tx.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
            cat?.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      {/* Classification Tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
        {state.classifications.map(cls => (
          <button
            key={cls.id}
            onClick={() => setActiveClassId(cls.id)}
            className={`px-6 py-2 rounded-full text-xs font-bold transition-all whitespace-nowrap ${
              activeClassId === cls.id 
                ? `${cls.color} text-slate-800 border-2 border-slate-300 shadow-sm` 
                : 'bg-white text-slate-400 border border-slate-200 hover:border-slate-300'
            }`}
          >
            {cls.name}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex justify-between items-center">
          <h3 className="text-sm font-bold text-slate-700">Classification Activity</h3>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input 
              type="text" 
              placeholder="Search activity..."
              className="pl-9 pr-4 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-xs focus:outline-none focus:ring-1 focus:ring-blue-500"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
