                <th className="px-6 py-3 font-semibold text-slate-600">Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600">Date</th>
                <th className="px-4 py-3 font-semibold text-slate-600">Account</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Amount</th>
                <th className="px-6 py-3 font-semibold text-slate-600">Description</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {activeTransactions.length > 0 ? (
                activeTransactions.map(tx => {
                  const category = state.categories.find(c => c.id === tx.categoryId);
                  const account = state.accounts.find(a => a.id === tx.accountId);
                  return (
                    <tr key={tx.id} className="hover:bg-slate-50">
                      <td className="px-6 py-3 font-medium text-slate-700">{category?.name}</td>
                      <td className="px-4 py-3 text-slate-500">{new Date(tx.date).toLocaleDateString()}</td>
                      <td className="px-4 py-3 text-slate-500">{account?.name || 'N/A'}</td>
                      <td className={`px-4 py-3 text-right font-bold ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                        {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                      </td>
