import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, getMonthLabel } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  // Get last 6 months for columns
  const months = useMemo(() => {
    const result = [];
    const now = new Date();
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      result.push(getMonthYearKey(d));
    }
    return result;
  }, []);

  const data = useMemo(() => {
    const result: Record<string, Record<string, { added: number, spent: number }>> = {};

    state.categories.forEach(cat => {
      result[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        result[cat.id][m] = { added, spent };
      });
    });

    return result;
  }, [state, months]);

  return (
    <div className="space-y-8">
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center gap-2">
          <div className="w-1.5 h-6 bg-red-400 rounded-full"></div>
          <h3 className="font-bold text-slate-700">Expenses Summary (Last 6 Months)</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-10">Category</th>
                {months.map(m => (
                  <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right">{getMonthLabel(m)}</th>
                ))}
                <th className="px-6 py-3 text-slate-500 font-bold text-right bg-slate-50/50">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {state.categories.filter(c => c.classificationId !== 'class-income').map(cat => {
                const total = months.reduce((sum, m) => sum + (data[cat.id]?.[m]?.spent || 0), 0);
                return (
                  <tr key={cat.id} className="hover:bg-slate-50">
                    <td className="px-6 py-2 text-slate-700 font-medium sticky left-0 bg-white group-hover:bg-slate-50">{cat.name}</td>
                    {months.map(m => {
                      const val = data[cat.id]?.[m]?.spent || 0;
                      return (
                        <td key={m} className={`px-3 py-2 text-right ${val < 0 ? 'text-red-500' : 'text-slate-300'}`}>
                          {val === 0 ? '-' : Math.round(Math.abs(val))}
                        </td>
                      );
                    })}
                    <td className="px-6 py-2 text-right font-bold text-slate-800 bg-slate-50/30">
                      {Math.round(Math.abs(total))}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center gap-2">
          <div className="w-1.5 h-6 bg-blue-400 rounded-full"></div>
          <h3 className="font-bold text-slate-700">Income & Interest Summary</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-10">Income Stream</th>
                {months.map(m => (
                  <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right">{getMonthLabel(m)}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {state.categories.filter(c => c.classificationId === 'class-income').map(cat => (
                <tr key={cat.id} className="hover:bg-slate-50">
                  <td className="px-6 py-2 text-slate-700 font-medium sticky left-0 bg-white">{cat.name}</td>
                  {months.map(m => {
                    const val = data[cat.id]?.[m]?.added || 0;
                    return (
                      <td key={m} className={`px-3 py-2 text-right ${val > 0 ? 'text-blue-600 font-medium' : 'text-slate-300'}`}>
                        {val === 0 ? '-' : Math.round(val)}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Summary;

import React, { useMemo } from 'react';
