}

const NetWorth: React.FC<NetWorthProps> = ({ state }) => {
  // Simple simulation of historical net worth based on current state
  // In a real app, this would come from a snapshots table
  const chartData = useMemo(() => {
    const now = new Date();
    const result = [];
    let cumulative = state.accounts.reduce((sum, a) => sum + a.balance, 0);

    // Mocking some growth for visual appeal
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      result.push({
        month: getMonthLabel(d),
        value: cumulative - (i * 2500) // simulated growth backwards
      });
    }
    return result;
  }, [state.accounts]);

  return (
    <div className="space-y-8">
      {/* Chart */}
      <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
