              <th className="px-6 py-4 font-semibold text-slate-600">Account Name</th>
              <th className="px-6 py-4 font-semibold text-slate-600 text-right">Current Balance</th>
              <th className="px-6 py-4 font-semibold text-slate-600">Type</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {state.accounts.map(acc => (
              <tr key={acc.id} className="hover:bg-slate-50">
                <td className="px-6 py-4 text-slate-700 font-medium">{acc.name}</td>
                <td className={`px-6 py-4 text-right font-bold ${acc.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                  {formatCurrency(acc.balance)}
                </td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${
                    acc.type === 'Checking' ? 'bg-blue-100 text-blue-700' :
                    acc.type === 'Credit' ? 'bg-red-100 text-red-700' :
                    acc.type === 'Investment' ? 'bg-green-100 text-green-700' :
                    'bg-slate-100 text-slate-700'
                  }`}>
                    {acc.type}
                  </span>
                </td>
              </tr>
            ))}
            <tr className="bg-slate-50 font-bold text-lg">
              <td className="px-6 py-6 text-slate-800">Grand Total</td>
              <td className="px-6 py-6 text-right text-slate-900">
                {formatCurrency(state.accounts.reduce((sum, a) => sum + a.balance, 0))}
              </td>
              <td className="px-6 py-6"></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

