import React, { useMemo } from 'react';
// Added missing Landmark icon import
import { Landmark } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer }) => {
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => 
        t.categoryId === cat.id && 
        getMonthYearKey(t.date) === currentMonth
      );

      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);

      return {
        ...cat,
        monthlyAdded: added,
        monthlySpent: spent
      };
    });
  }, [state, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const totals = useMemo(() => {
    const checking = state.accounts.filter(a => a.type === 'Checking').reduce((sum, a) => sum + a.balance, 0);
    const savings = state.accounts.filter(a => a.type === 'Savings').reduce((sum, a) => sum + a.balance, 0);
    const credit = state.accounts.filter(a => a.type === 'Credit').reduce((sum, a) => sum + a.balance, 0);
    const investments = state.accounts.filter(a => a.type === 'Investment').reduce((sum, a) => sum + a.balance, 0);

    return { checking, savings, credit, net: checking + savings + credit + investments };
  }, [state.accounts]);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Category List (Left & Center) */}
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-semibold text-slate-600">Classification / Category</th>
                <th className="px-4 py-4 font-semibold text-slate-600 text-right">Balance</th>
                <th className="px-4 py-4 font-semibold text-slate-600 text-right">Monthly Budget</th>
                <th className="px-4 py-4 font-semibold text-slate-600 text-right">Input CM</th>
                <th className="px-4 py-4 font-semibold text-slate-600 text-right">Expenses CM</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {state.classifications.map(cls => (
                <React.Fragment key={cls.id}>
                  <tr className={`${cls.color} font-bold text-slate-800`}>
                    <td colSpan={5} className="px-6 py-2 uppercase tracking-wide text-xs">{cls.name}</td>
                  </tr>
                  {(groupedCategories[cls.id] || []).map(cat => (
                    <tr key={cat.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-3 pl-10 text-slate-600">{cat.name}</td>
                      <td className={`px-4 py-3 text-right font-medium ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                        {formatCurrency(cat.balance)}
                      </td>
                      <td className="px-4 py-3 text-right text-slate-500">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                      <td className="px-4 py-3 text-right text-blue-600">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                      <td className="px-4 py-3 text-right text-red-400">{cat.monthlySpent < 0 ? `(${formatCurrency(Math.abs(cat.monthlySpent))})` : '-'}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Transaction Entry & Account Summary (Right) */}
      <div className="space-y-8">
        <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />

        {/* Account Balances */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6 space-y-4">
          <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider flex items-center gap-2">
            <Landmark size={16} className="text-blue-500" />
            Account Balances
          </h3>
          <div className="space-y-3">
            {state.accounts.map(acc => (
              <div key={acc.id} className="flex justify-between items-center group">
                <div className="flex flex-col">
                  <span className="text-sm font-medium text-slate-700">{acc.name}</span>
                  <span className="text-[10px] text-slate-400 uppercase">{acc.type}</span>
                </div>
                <span className={`text-sm font-bold ${acc.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                  {formatCurrency(acc.balance)}
                </span>
              </div>
            ))}
          </div>
          <div className="pt-4 mt-4 border-t border-slate-100 grid grid-cols-2 gap-4">
            <div>
              <span className="text-[10px] text-slate-400 uppercase block">Total Net</span>
              <span className={`text-lg font-bold ${totals.net < 0 ? 'text-red-600' : 'text-slate-900'}`}>{formatCurrency(totals.net)}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

