import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(INITIAL_DATA);

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id };
        newTransactions.push(tx);

        // Update Category Balance
        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        // Update Account Balance (only if accountId is not 'none' or 'internal')
        if (tx.accountId !== 'none' && tx.accountId !== 'internal') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      // Special logic for "Update Budget (Allocation)"
      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({
          ...txData,
          accountId: 'internal'
        });
      } else {
        processSingle(txData);

        // Income triggers Tithing (10%)
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        if (txData.type === 'Income' || (selectedCat?.name === 'Main Income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string) => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: 'Standard'
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && accId !== 'internal') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      if (type === 'Update Budget (Allocation)') {
        recordTx(undefined, toCategoryId, amount, description);
      } else {
        switch (type) {
          case 'Category Transfer':
            recordTx(fromAccountId, fromCategoryId, -amount, description);
            recordTx(toAccountId, toCategoryId, amount, description);
            break;
          case 'Transfer to Savings':
            recordTx(fromAccountId, undefined, -amount, description);
            recordTx(undefined, toCategoryId, amount, description);
            break;
          case 'Transfer to Checking':
            recordTx(toAccountId, toCategoryId, amount, description);
            recordTx(undefined, fromCategoryId, -amount, description);
            break;
          default:
            recordTx(fromAccountId, undefined, -amount, description);
            recordTx(toAccountId, undefined, amount, description);
            break;
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];

      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({
          id: classId,
          name: classificationName,
          color: color || 'bg-gray-100'
        });
      }

      const newCategory: Category = {
        id: `cat-${generateId()}`,
        name,
        classificationId: classId,
        balance: 0,
        monthlyBudget: 0
      };

      return {
        ...prev,
        classifications: newClassifications,
        categories: [...prev.categories, newCategory]
      };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory
  };
};

import React, { useMemo, useState } from 'react';
import { Landmark, AlertCircle, Plus } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer, addCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => 
        t.categoryId === cat.id && 
        getMonthYearKey(t.date) === currentMonth
      );
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, monthlyAdded: added, monthlySpent: spent };
    });
  }, [state, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const totals = useMemo(() => {
    const checking = state.accounts.filter(a => a.type === 'Checking').reduce((sum, a) => sum + a.balance, 0);
    const credit = state.accounts.filter(a => a.type === 'Credit').reduce((sum, a) => sum + a.balance, 0);
    const budgetTotal = state.categories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      checkingAndCredit: checking + credit,
      budgetTotal,
      difference: (checking + credit) - budgetTotal
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <button 
              onClick={() => setShowAddCat(true)}
              className="flex items-center gap-1 text-blue-600 hover:text-blue-700 text-xs font-bold"
            >
              <Plus size={14} /> Add Category
            </button>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Spent</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {state.classifications.map(cls => (
                <React.Fragment key={cls.id}>
                  <tr className={`${cls.color} font-bold text-slate-800`}>
                    <td colSpan={5} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td>
                  </tr>
                  {(groupedCategories[cls.id] || []).map(cat => (
                    <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400">
                      <td className="px-6 py-2.5 pl-10 text-slate-600 font-medium">{cat.name}</td>
                      <td className={`px-4 py-2.5 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                        {formatCurrency(cat.balance)}
                      </td>
                      <td className="px-4 py-2.5 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                      <td className="px-4 py-2.5 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                      <td className="px-4 py-2.5 text-right text-red-400">{cat.monthlySpent < 0 ? `(${formatCurrency(Math.abs(cat.monthlySpent))})` : '-'}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="space-y-6">
        <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />

        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6 space-y-6">
          <div>
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Cash Position</h3>
            <div className="space-y-3">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Checking Total</span>
                <span className="font-bold text-slate-800">{formatCurrency(state.accounts.filter(a => a.type === 'Checking').reduce((s,a) => s+a.balance, 0))}</span>
              </div>
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Credit Total</span>
                <span className="font-bold text-red-500">({formatCurrency(Math.abs(state.accounts.filter(a => a.type === 'Credit').reduce((s,a) => s+a.balance, 0)))})</span>
              </div>
              <div className="pt-3 border-t border-slate-100 flex justify-between items-center text-sm">
                <span className="font-bold text-slate-700">Combined Liquid</span>
                <span className="font-bold text-slate-900">{formatCurrency(totals.checkingAndCredit)}</span>
              </div>
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Budgeted (All Cats)</span>
                <span className="font-bold text-blue-600">{formatCurrency(totals.budgetTotal)}</span>
              </div>
            </div>
          </div>

          <div className="p-4 bg-slate-900 rounded-lg shadow-inner">
            <div className="flex items-center gap-2 mb-1">
              <AlertCircle size={14} className="text-blue-400" />
              <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Update Budget Difference</span>
            </div>
            <div className={`text-2xl font-bold ${Math.abs(totals.difference) < 0.01 ? 'text-green-400' : 'text-blue-400'}`}>
              {formatCurrency(totals.difference)}
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
          <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Current Accounts</h3>
          <div className="space-y-3">
            {state.accounts.filter(a => ['Checking', 'Credit'].includes(a.type)).map(acc => (
              <div key={acc.id} className="flex justify-between items-center">
                <span className="text-xs font-medium text-slate-600">{acc.name}</span>
                <span className={`text-xs font-bold ${acc.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(acc.balance)}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {showAddCat && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-6">
              <h4 className="text-lg font-bold text-slate-800 mb-4">Add New Category</h4>
              <form onSubmit={handleAddCat} className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Category Name</label>
                  <input 
                    type="text" 
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                    value={newCat.name}
                    onChange={e => setNewCat({...newCat, name: e.target.value})}
                    placeholder="e.g. New Project"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Classification</label>
                  <select 
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                    value={newCat.className}
                    onChange={e => setNewCat({...newCat, className: e.target.value})}
                    required
                  >
                    <option value="">Select or Create New...</option>
                    {state.classifications.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                    <option value="NEW">Create New Classification</option>
                  </select>
                  {newCat.className === 'NEW' && (
                    <input 
                      type="text"
                      className="w-full px-4 py-2 mt-2 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                      placeholder="Classification Name"
                      onChange={e => setNewCat({...newCat, className: e.target.value})}
                    />
                  )}
                </div>
                <div className="flex gap-2 justify-end pt-4">
                  <button type="button" onClick={() => setShowAddCat(false)} className="px-4 py-2 text-sm font-bold text-slate-400">Cancel</button>
                  <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold shadow-lg">Create Category</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { AppState, Category, Transaction } from '../types';
import { formatCurrency } from '../utils';
import { Search, ChevronDown } from 'lucide-react';

interface LedgersProps {
  state: AppState;
}

const Ledgers: React.FC<LedgersProps> = ({ state }) => {
  const [activeClassId, setActiveClassId] = useState(state.classifications[0]?.id);
  const [searchTerm, setSearchTerm] = useState('');

  const categoriesInClass = useMemo(() => {
    return state.categories.filter(c => c.classificationId === activeClassId);
  }, [state.categories, activeClassId]);

  const transactionsByCategory = useMemo(() => {
    const map: Record<string, Transaction[]> = {};
    state.transactions.forEach(tx => {
      if (!map[tx.categoryId]) map[tx.categoryId] = [];
      map[tx.categoryId].push(tx);
    });
    return map;
  }, [state.transactions]);

  return (
    <div className="space-y-6">
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar no-scrollbar">
        {state.classifications.map(cls => (
          <button
            key={cls.id}
            onClick={() => setActiveClassId(cls.id)}
            className={`px-6 py-2 rounded-full text-[11px] font-bold transition-all whitespace-nowrap uppercase tracking-widest ${
              activeClassId === cls.id 
                ? `${cls.color} text-slate-800 border border-slate-300 shadow-sm` 
                : 'bg-white text-slate-400 border border-slate-200 hover:border-slate-300 shadow-sm'
            }`}
          >
            {cls.name}
          </button>
        ))}
      </div>

      <div className="space-y-8">
        {categoriesInClass.map(cat => {
          const txs = (transactionsByCategory[cat.id] || [])
            .filter(t => t.description.toLowerCase().includes(searchTerm.toLowerCase()))
            .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

          if (txs.length === 0 && searchTerm) return null;

          return (
            <div key={cat.id} className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                  <h3 className="font-bold text-slate-700">{cat.name}</h3>
                </div>
                <div className="text-xs text-slate-400 font-bold uppercase tracking-wider">
                  Balance: <span className={cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}>{formatCurrency(cat.balance)}</span>
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-white border-b border-slate-100">
                    <tr>
                      <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Date</th>
                      <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Account</th>
                      <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter text-right">Amount</th>
                      <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Description</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {txs.length > 0 ? (
                      txs.map(tx => {
                        const account = state.accounts.find(a => a.id === tx.accountId);
                        return (
                          <tr key={tx.id} className="hover:bg-slate-50/50">
                            <td className="px-6 py-3 text-slate-500 font-medium">{new Date(tx.date).toLocaleDateString()}</td>
                            <td className="px-4 py-3 text-slate-600 font-semibold">{account?.name || (tx.accountId === 'internal' ? 'Internal' : 'N/A')}</td>
                            <td className={`px-4 py-3 text-right font-bold ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                              {formatCurrency(tx.amount)}
                            </td>
                            <td className="px-6 py-3 text-slate-600">{tx.description}</td>
                          </tr>
                        );
                      })
                    ) : (
                      <tr>
                        <td colSpan={4} className="px-6 py-6 text-center text-slate-300 italic text-[11px]">No transactions recorded for this category.</td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Ledgers;

import React, { useState } from 'react';
import { Plus, ArrowRightLeft, Calendar, DollarSign, Tag, Landmark, FileText } from 'lucide-react';
import { AppState, TransactionType } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ state, onAddTransaction, onExecuteTransfer }) => {
  const [activeMode, setActiveMode] = useState<'transact' | 'transfer' | 'budget'>('transact');
  const [formData, setFormData] = useState({
    categoryId: '',
    date: new Date().toISOString().split('T')[0],
    accountId: '',
    amount: '',
    description: '',
    type: 'Standard' as TransactionType,
    toCategoryId: '',
    toAccountId: '',
    fromCategoryId: '',
    fromAccountId: '',
    transferType: TRANSFER_TYPES[0]
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (activeMode === 'transact') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: parseFloat(formData.amount),
        description: formData.description,
        type: formData.type,
      });
    } else if (activeMode === 'budget') {
      onAddTransaction({
        categoryId: formData.toCategoryId,
        date: formData.date,
        accountId: 'internal',
        amount: parseFloat(formData.amount),
        description: formData.description || 'Budget Allocation',
        type: 'Update Budget (Allocation)' as any,
      });
    } else {
      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: parseFloat(formData.amount),
        description: formData.description,
        fromAccountId: formData.fromAccountId,
        toAccountId: formData.toAccountId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }
    setFormData(prev => ({ ...prev, amount: '', description: '' }));
  };

  const inputStyles = "w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:outline-none transition-all";

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        <button onClick={() => setActiveMode('transact')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest ${activeMode === 'transact' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>Transact</button>
        <button onClick={() => setActiveMode('budget')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest ${activeMode === 'budget' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>Allocation</button>
        <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest ${activeMode === 'transfer' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>Transfer</button>
      </div>

      <form onSubmit={handleSubmit} className="p-5 space-y-4">
        {activeMode === 'budget' ? (
          <>
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
              <p className="text-[10px] text-blue-600 font-bold uppercase tracking-wider mb-1">Budget Allocation</p>
              <p className="text-[11px] text-blue-400">Moves internal funds into a category bucket without impacting bank balances.</p>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Apply to Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Destination</option>
                  {state.categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
              </div>
            </div>
          </>
        ) : activeMode === 'transact' ? (
          <div className="space-y-4">
             <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Category</option>
                  {state.categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
              </div>
            </div>
            <div>
