                        value={cat.monthlyBudget}
                        onChange={e => onUpdateBudget(cat.id, parseFloat(e.target.value) || 0)}
                      />
                    </td>
                    <td className="px-4 py-3 text-right text-blue-500 font-bold">{formatCurrency(cat.added)}</td>
                    <td className="px-4 py-3 text-right text-red-500 font-bold">({formatCurrency(Math.abs(cat.spent))})</td>
                  </tr>
                ))}
              </React.Fragment>
            ))}
          </tbody>
          <tfoot className="bg-slate-900 text-white font-bold">
            <tr>
              <td className="px-6 py-4 uppercase tracking-widest text-xs">Total Monthly Targets</td>
              <td className="px-4 py-4 text-right text-lg">{formatCurrency(totalBudgeted)}</td>
