import React, { useMemo, useState } from 'react';
import { Landmark, AlertCircle, Plus, Wallet, PiggyBank, Briefcase } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer, addCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, monthlyAdded: added, monthlySpent: spent };
    });
  }, [state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const totals = useMemo(() => {
    const liquidAccounts = state.accounts.filter(a => ['Checking', 'Credit'].includes(a.type));
    const liquidTotal = liquidAccounts.reduce((sum, a) => sum + a.balance, 0);
    const budgetTotal = state.categories.reduce((sum, cat) => sum + cat.balance, 0);
    return {
      liquidTotal,
      budgetTotal,
      difference: liquidTotal - budgetTotal
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings'].includes(c.id));
  const savingsClass = state.classifications.find(c => c.id === 'class-savings');
  const incomeClass = state.classifications.find(c => c.id === 'class-income');

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <button onClick={() => setShowAddCat(true)} className="flex items-center gap-1 text-blue-600 hover:text-blue-700 text-xs font-bold"><Plus size={14} /> Add Category</button>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Spent</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => (
                <React.Fragment key={cls.id}>
                  <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={5} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                  {(groupedCategories[cls.id] || []).map(cat => (
                    <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400">
                      <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                      <td className={`px-4 py-2 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(cat.balance)}</td>
                      <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                      <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                      <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? `(${formatCurrency(Math.abs(cat.monthlySpent))})` : '-'}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>

        {/* Savings & Income Visual Blocks */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
            <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
              <PiggyBank className="text-emerald-500" size={18} />
              <h4 className="font-bold text-slate-700 uppercase text-xs tracking-widest">Savings Breakdown</h4>
            </div>
            <div className="space-y-3">
              {(groupedCategories['class-savings'] || []).map(cat => (
                <div key={cat.id} className="flex justify-between items-center text-sm">
                  <span className="text-slate-500">{cat.name}</span>
                  <span className="font-bold text-slate-800">{formatCurrency(cat.balance)}</span>
                </div>
              ))}
              <div className="pt-3 border-t border-slate-100 flex justify-between font-bold text-slate-900">
                <span>Total Savings</span>
                <span>{formatCurrency(state.categories.filter(c => c.classificationId === 'class-savings').reduce((s,c) => s+c.balance, 0))}</span>
              </div>
            </div>
          </div>
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
            <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
              <Briefcase className="text-cyan-500" size={18} />
              <h4 className="font-bold text-slate-700 uppercase text-xs tracking-widest">Income Metrics</h4>
            </div>
            <div className="space-y-3">
              {(groupedCategories['class-income'] || []).map(cat => (
                <div key={cat.id} className="flex justify-between items-center text-sm">
                  <span className="text-slate-500">{cat.name}</span>
                  <span className="font-bold text-slate-800">{formatCurrency(cat.balance)}</span>
                </div>
              ))}
              <div className="pt-3 border-t border-slate-100 flex justify-between font-bold text-slate-900">
                <span>Total Income</span>
                <span>{formatCurrency(state.categories.filter(c => c.classificationId === 'class-income').reduce((s,c) => s+c.balance, 0))}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />
        <div className="bg-slate-900 rounded-xl shadow-xl p-6 text-white space-y-6">
          <div className="space-y-4">
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Liquid Reconciliation</h3>
            <div className="flex justify-between text-sm">
              <span className="text-slate-400">Total Account Balance</span>
              <span className="font-bold">{formatCurrency(totals.liquidTotal)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-slate-400">Total Categorized</span>
              <span className="font-bold text-blue-400">{formatCurrency(totals.budgetTotal)}</span>
            </div>
            <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
              <div>
                <span className="text-[10px] font-bold text-slate-500 uppercase block tracking-wider">Unallocated Funds</span>
                <span className={`text-2xl font-black ${Math.abs(totals.difference) < 0.01 ? 'text-green-400' : 'text-blue-400'}`}>
                  {formatCurrency(totals.difference)}
