import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, getMonthLabel } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  const months = useMemo(() => {
    const result = [];
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();

    // 1. Calculate preceding 6 months
    for (let i = 6; i >= 1; i--) {
      const d = new Date(currentYear, currentMonth - i, 1);
      result.push(getMonthYearKey(d));
    }

    // 2. Calculate months of current year up to now (or full year if desired)
    for (let i = 0; i <= currentMonth; i++) {
      const d = new Date(currentYear, i, 1);
      result.push(getMonthYearKey(d));
    }

    return result;
  }, []);

  const data = useMemo(() => {
    const result: Record<string, Record<string, { added: number, spent: number }>> = {};
    state.categories.forEach(cat => {
      result[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        result[cat.id][m] = { added, spent };
      });
    });
    return result;
  }, [state.categories, state.transactions, months]);

  return (
    <div className="space-y-8 pb-12">
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-6 bg-red-400 rounded-full"></div>
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">Annual Expenses Breakdown</h3>
          </div>
          <span className="text-[10px] font-bold text-slate-400">Current Year + Preceding 6 Months</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase tracking-tighter">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-20 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Category</th>
                {months.map(m => (
                  <th key={m} className={`px-3 py-3 font-bold text-right ${m.startsWith(new Date().getFullYear().toString()) ? 'text-blue-600' : 'text-slate-400'}`}>
                    {getMonthLabel(m)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {state.categories.filter(c => c.classificationId !== 'class-income').map(cat => (
                <tr key={cat.id} className="hover:bg-slate-50 group">
                  <td className="px-6 py-2 text-slate-700 font-bold sticky left-0 bg-white group-hover:bg-slate-50 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.05)] border-r border-slate-100">{cat.name}</td>
                  {months.map(m => {
                    const val = data[cat.id]?.[m]?.spent || 0;
                    return (
                      <td key={m} className={`px-3 py-2 text-right ${val < 0 ? 'text-red-500' : 'text-slate-200'}`}>
                        {val === 0 ? '-' : Math.round(Math.abs(val))}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center gap-2">
          <div className="w-1.5 h-6 bg-cyan-400 rounded-full"></div>
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">Annual Income Analysis</h3>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase tracking-tighter">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-20 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Source</th>
                {months.map(m => (
                  <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right">{getMonthLabel(m)}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {state.categories.filter(c => c.classificationId === 'class-income').map(cat => (
