import { useState, useCallback } from 'react';
import { AppState, Transaction, Category, InvestmentSnapshot } from '../types';
import { INITIAL_DATA } from '../constants';
import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(INITIAL_DATA);

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id, cleared: false };
        newTransactions.push(tx);

        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        if (tx.accountId !== 'none' && tx.accountId !== 'internal') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({ ...txData, accountId: 'internal' });
      } else {
        processSingle(txData);
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        // Tithing logic
        if (txData.type === 'Income' || (selectedCat?.classificationId === 'class-income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const deleteCategory = useCallback((catId: string) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.filter(c => c.id !== catId),
      // Optionally handle transactions here, but the user didn't specify.
      // We'll keep transactions but they'll just have a dangling categoryId.
    }));
  }, []);

  const toggleCleared = useCallback((txId: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === txId ? { ...t, cleared: !t.cleared } : t)
    }));
  }, []);

  const updateBudget = useCallback((catId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, monthlyBudget: amount } : c)
    }));
  }, []);

  const setEstIncome = useCallback((amount: number) => {
    setState(prev => ({ ...prev, estimatedMonthlyIncome: amount }));
  }, []);

  const addInvestmentSnapshot = useCallback((snapshot: InvestmentSnapshot) => {
    setState(prev => {
      const filtered = prev.investmentSnapshots.filter(s => !(s.monthKey === snapshot.monthKey && s.accountId === snapshot.accountId));
      return {
        ...prev,
        investmentSnapshots: [...filtered, snapshot]
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string) => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: 'Standard',
          cleared: false
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && accId !== 'internal') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      if (type === 'Update Budget (Allocation)') {
        recordTx(undefined, toCategoryId, amount, description);
      } else {
        switch (type) {
          case 'Category Transfer':
            recordTx(fromAccountId, fromCategoryId, -amount, description);
            recordTx(toAccountId, toCategoryId, amount, description);
            break;
          case 'Transfer to Savings':
            recordTx(fromAccountId, undefined, -amount, description);
            recordTx(undefined, toCategoryId, amount, description);
            break;
          case 'Transfer to Checking':
            recordTx(toAccountId, toCategoryId, amount, description);
            recordTx(undefined, fromCategoryId, -amount, description);
            break;
          default:
            recordTx(fromAccountId, undefined, -amount, description);
            recordTx(toAccountId, undefined, amount, description);
            break;
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];
      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({ id: classId, name: classificationName, color: color || 'bg-gray-100' });
      }
      const newCategory: Category = { id: `cat-${generateId()}`, name, classificationId: classId, balance: 0, monthlyBudget: 0 };
      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot
  };
};

import React, { useMemo, useState } from 'react';
import { Landmark, AlertCircle, Plus, Wallet, PiggyBank, Briefcase, Trash2 } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
  deleteCategory: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer, addCategory, deleteCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, monthlyAdded: added, monthlySpent: spent };
    });
  }, [state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const totals = useMemo(() => {
    const liquidAccounts = state.accounts.filter(a => ['Checking', 'Credit'].includes(a.type));
    const liquidTotal = liquidAccounts.reduce((sum, a) => sum + a.balance, 0);

    // Unallocated Funds = Liquid Cash - (All budgeted categories excluding income and savings holding)
    // As per user request: "income metrics should not be playing a factor into the total to categorize"
    const relevantCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
    const budgetTotal = relevantCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      liquidTotal,
      budgetTotal,
      difference: liquidTotal - budgetTotal
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const handleDelete = (id: string, name: string) => {
    if (window.confirm(`Are you sure you want to delete the category "${name}"? This action cannot be undone.`)) {
      deleteCategory(id);
    }
  };

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings'].includes(c.id));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <button onClick={() => setShowAddCat(true)} className="flex items-center gap-1 text-blue-600 hover:text-blue-700 text-xs font-bold"><Plus size={14} /> Add Category</button>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Spent</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => (
                <React.Fragment key={cls.id}>
                  <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={6} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                  {(groupedCategories[cls.id] || []).map(cat => (
                    <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400 group">
                      <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                      <td className={`px-4 py-2 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(cat.balance)}</td>
                      <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                      <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                      <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? `(${formatCurrency(Math.abs(cat.monthlySpent))})` : '-'}</td>
                      <td className="px-4 py-2 text-right">
                        <button 
                          onClick={() => handleDelete(cat.id, cat.name)}
                          className="text-slate-200 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>

        {/* Savings Breakdown */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
          <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
            <PiggyBank className="text-emerald-500" size={18} />
            <h4 className="font-bold text-slate-700 uppercase text-xs tracking-widest">Savings Positions</h4>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-3">
            {(groupedCategories['class-savings'] || []).map(cat => (
              <div key={cat.id} className="flex justify-between items-center text-sm group">
                <span className="text-slate-500">{cat.name}</span>
                <div className="flex items-center gap-2">
                  <span className="font-bold text-slate-800">{formatCurrency(cat.balance)}</span>
                  <button onClick={() => handleDelete(cat.id, cat.name)} className="text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>
                </div>
              </div>
            ))}
          </div>
          <div className="pt-3 mt-3 border-t border-slate-100 flex justify-between font-bold text-slate-900 text-sm">
            <span>Total Savings Allocation</span>
            <span>{formatCurrency(state.categories.filter(c => c.classificationId === 'class-savings').reduce((s,c) => s+c.balance, 0))}</span>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />
        <div className="bg-slate-900 rounded-xl shadow-xl p-6 text-white space-y-6">
          <div className="space-y-4">
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Budget Reconciliation</h3>
            <div className="flex justify-between text-sm">
              <span className="text-slate-400">Total Checking/Credit</span>
              <span className="font-bold">{formatCurrency(totals.liquidTotal)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-slate-400">Allocated (Budget)</span>
              <span className="font-bold text-blue-400">-{formatCurrency(totals.budgetTotal)}</span>
            </div>
            <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
              <div>
                <span className="text-[10px] font-bold text-slate-500 uppercase block tracking-wider">Remaining Unallocated</span>
                <span className={`text-2xl font-black ${Math.abs(totals.difference) < 0.01 ? 'text-green-400' : 'text-blue-400'}`}>
                  {formatCurrency(totals.difference)}
                </span>
              </div>
              <AlertCircle size={32} className={Math.abs(totals.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
            </div>
          </div>
        </div>
      </div>

      {showAddCat && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-6 transform transition-all scale-100">
            <h4 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><Plus size={20} className="text-blue-500" /> Define New Category</h4>
            <form onSubmit={handleAddCat} className="space-y-5">
              <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Name</label><input type="text" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" value={newCat.name} onChange={e => setNewCat({...newCat, name: e.target.value})} placeholder="e.g. New Project" required /></div>
              <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Group</label><select className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" value={newCat.className} onChange={e => setNewCat({...newCat, className: e.target.value})} required><option value="">Select Classification...</option>{state.classifications.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}<option value="NEW">Add New Classification</option></select>{newCat.className === 'NEW' && <input type="text" className="w-full px-4 py-2 mt-2 bg-slate-50 border border-slate-200 rounded-lg" placeholder="Classification Name" onChange={e => setNewCat({...newCat, className: e.target.value})} />}</div>
              <div className="flex gap-2 justify-end pt-4"><button type="button" onClick={() => setShowAddCat(false)} className="px-6 py-2 text-sm font-bold text-slate-400">Cancel</button><button type="submit" className="px-8 py-2 bg-slate-900 text-white rounded-lg text-sm font-bold shadow-xl">Save</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  const targetYear = 2025;
  const months = useMemo(() => {
    const res = [];
    for (let i = 0; i < 12; i++) {
      const d = new Date(targetYear, i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const monthLabels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number }>> = {};
    state.categories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent };
      });
    });
    return data;
  }, [state.categories, state.transactions, months]);

  const renderSection = (title: string, catList: any[], field: 'added' | 'spent' | 'both', colorClass: string) => {
    return (
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-8">
        <div className={`p-4 ${colorClass} border-b border-slate-200 flex items-center justify-between`}>
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">{title}</h3>
          <span className="text-[10px] font-bold text-slate-400">FY {targetYear}</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase tracking-tighter">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-20 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Category</th>
                {monthLabels.map((l, i) => <th key={i} className="px-3 py-3 text-slate-500 font-bold text-right">{l}</th>)}
                <th className="px-6 py-3 text-slate-900 font-bold text-right bg-slate-100">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {catList.map(cat => {
                let rowTotal = 0;
                return (
                  <tr key={cat.id} className="hover:bg-slate-50 group">
                    <td className="px-6 py-2 text-slate-700 font-bold sticky left-0 bg-white group-hover:bg-slate-50 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.05)] border-r border-slate-100">{cat.name}</td>
                    {months.map(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      let val = 0;
                      if (field === 'added') val = stats.added;
                      else if (field === 'spent') val = stats.spent;
                      else val = stats.added + stats.spent;

                      rowTotal += val;
                      const displayVal = Math.round(Math.abs(val));
                      const isNegative = val < 0;

                      return (
                        <td key={m} className={`px-3 py-2 text-right ${val === 0 ? 'text-slate-200' : isNegative ? 'text-red-500' : 'text-blue-600 font-medium'}`}>
                          {val === 0 ? '-' : displayVal}
                        </td>
                      );
                    })}
                    <td className="px-6 py-2 text-right font-black bg-slate-50 text-slate-900">
                      {Math.round(Math.abs(rowTotal))}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-slate-900 text-white font-bold">
              <tr>
                <td className="px-6 py-3">Total {title}</td>
                {months.map(m => {
                  let monthTotal = 0;
                  catList.forEach(cat => {
                    const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                    if (field === 'added') monthTotal += stats.added;
                    else if (field === 'spent') monthTotal += stats.spent;
                    else monthTotal += (stats.added + stats.spent);
                  });
                  return <td key={m} className="px-3 py-3 text-right">{Math.round(Math.abs(monthTotal))}</td>;
                })}
                <td className="px-6 py-3 text-right">
                  {Math.round(Math.abs(catList.reduce((acc, cat) => {
                    let catSum = 0;
                    months.forEach(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      if (field === 'added') catSum += stats.added;
                      else if (field === 'spent') catSum += stats.spent;
                      else catSum += (stats.added + stats.spent);
                    });
                    return acc + catSum;
                  }, 0)))}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    );
  };

  const incomeCategories = state.categories.filter(c => c.classificationId === 'class-income');
  const expenseCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
  const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');

  const resourceTotals = months.map(m => incomeCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0));
  const expenseTotals = months.map(m => (
    expenseCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.spent || 0), 0) +
    savingsCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0)
  ));

  return (
    <div className="space-y-12 pb-24">
      {renderSection("Income Summary", incomeCategories, 'added', 'bg-cyan-50')}
      {renderSection("Expenses Summary", expenseCategories, 'spent', 'bg-red-50')}
      {renderSection("Money Added Summary", [...expenseCategories, ...savingsCategories], 'added', 'bg-blue-50')}
      {renderSection("Summary Activity (Net)", [...expenseCategories, ...savingsCategories], 'both', 'bg-slate-50')}

      <div className="bg-slate-900 rounded-xl border border-slate-700 shadow-2xl overflow-hidden">
        <div className="p-4 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
          <h3 className="font-black text-white uppercase text-xs tracking-[0.2em]">Resources vs Expenses Comparison</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter text-slate-300">
            <thead className="border-b border-slate-800">
              <tr>
                <th className="px-6 py-4 font-bold sticky left-0 bg-slate-800 z-10">Metric</th>
                {monthLabels.map((l, i) => <th key={i} className="px-4 py-4 text-right">{l}</th>)}
                <th className="px-6 py-4 text-right bg-slate-800">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 font-bold">
              <tr>
                <td className="px-6 py-4 sticky left-0 bg-slate-900 z-10 text-cyan-400">Resources (Income)</td>
                {resourceTotals.map((val, i) => <td key={i} className="px-4 py-4 text-right">{Math.round(val)}</td>)}
                <td className="px-6 py-4 text-right bg-slate-800 text-cyan-400">{Math.round(resourceTotals.reduce((a,b)=>a+b, 0))}</td>
              </tr>
              <tr>
                <td className="px-6 py-4 sticky left-0 bg-slate-900 z-10 text-red-400">Expenses (Spend + Savings Added)</td>
                {expenseTotals.map((val, i) => <td key={i} className="px-4 py-4 text-right">({Math.round(Math.abs(val))})</td>)}
                <td className="px-6 py-4 text-right bg-slate-800 text-red-400">({Math.round(Math.abs(expenseTotals.reduce((a,b)=>a+b, 0)))})</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm">
                <td className="px-6 py-6 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest">Net Surplus/Deficit</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotals[i];
                  return <td key={i} className={`px-4 py-6 text-right ${net < 0 ? 'text-red-500' : 'text-green-400'}`}>{formatCurrency(net)}</td>
                })}
                <td className="px-6 py-6 text-right font-black bg-blue-600">
                  {formatCurrency(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotals.reduce((a,b)=>a+b, 0))}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Summary;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot 
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            executeTransfer={executeTransfer} 
            addCategory={addCategory}
            deleteCategory={deleteCategory}
          />
        );
      case 'acc-ledgers':
        return <AccountLedgers state={state} onToggleCleared={toggleCleared} />;
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return <NetWorth state={state} onAddSnapshot={addInvestmentSnapshot} />;
      default:
        return <Dashboard state={state} addTransaction={addTransaction} executeTransfer={executeTransfer} addCategory={addCategory} deleteCategory={deleteCategory} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {children}
      {renderContent()}
    </Layout>
  );
};

export default App;

