import React, { useMemo, useState } from 'react';
import { Landmark, AlertCircle, Plus, Wallet, PiggyBank, Briefcase, Trash2 } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
  deleteCategory: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer, addCategory, deleteCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, monthlyAdded: added, monthlySpent: spent };
    });
  }, [state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const totals = useMemo(() => {
    const liquidAccounts = state.accounts.filter(a => ['Checking', 'Credit'].includes(a.type));
    const liquidTotal = liquidAccounts.reduce((sum, a) => sum + a.balance, 0);

    // Unallocated Funds = Liquid Cash - (All budgeted categories excluding income and savings holding)
    // As per user request: "income metrics should not be playing a factor into the total to categorize"
    const relevantCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
    const budgetTotal = relevantCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      liquidTotal,
      budgetTotal,
      difference: liquidTotal - budgetTotal
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
