    const res: string[] = [];
    const year = new Date().getFullYear();
    for (let i = 0; i < 12; i++) res.push(getMonthYearKey(new Date(year, i, 1)));
    return res;
  }, []);

  const historyData = useMemo(() => {
    return monthsOfYear.map(m => {
      const liquidTotal = state.accounts.filter(a => ['Checking', 'Credit', 'Savings'].includes(a.type)).reduce((s, a) => s + a.balance, 0);
      const snapshotTotal = state.investmentSnapshots.filter(s => s.monthKey === m).reduce((s, a) => s + a.balance, 0);
      return { monthKey: m, label: getMonthLabel(m), value: liquidTotal + snapshotTotal };
    });
  }, [state.accounts, state.investmentSnapshots, monthsOfYear]);

  const handleSaveSnapshot = (e: React.FormEvent) => {
    e.preventDefault();
    // Fix: Explicitly cast Object.entries to ensure accId and val are not inferred as 'unknown'
    (Object.entries(editValues) as [string, string][]).forEach(([accId, val]) => {
      if (val) onAddSnapshot({ monthKey: selectedMonth, accountId: accId, balance: parseFloat(val) });
    });
    setEditValues({});
  };

  const investmentAccounts = state.accounts.filter(a => a.type === 'Investment');

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-6">Annual Net Worth Velocity</h3>
          <div className="h-48 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={historyData}>
                <defs>
                  <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8'}} tickFormatter={(v) => `$${v/1000}k`} />
                <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorNet)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-900 rounded-xl p-6 text-white">
          <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4">Manual Investment Update</h4>
          <form onSubmit={handleSaveSnapshot} className="space-y-4">
            <select 
              value={selectedMonth} 
              onChange={e => setSelectedMonth(e.target.value)}
              className="w-full bg-slate-800 border-none text-sm rounded-lg p-2 focus:ring-1 focus:ring-blue-500"
            >
              {monthsOfYear.map(m => <option key={m} value={m}>{getMonthLabel(m)}</option>)}
            </select>
            {investmentAccounts.map(acc => (
              <div key={acc.id} className="space-y-1">
                <label className="text-[9px] text-slate-500 uppercase">{acc.name}</label>
                <input 
                  type="number" 
                  step="0.01" 
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm"
                  placeholder={formatCurrency(acc.balance)}
                  value={editValues[acc.id] || ''}
                  onChange={e => setEditValues({...editValues, [acc.id]: e.target.value})}
                />
              </div>
            ))}
            <button type="submit" className="w-full bg-blue-600 py-3 rounded-lg text-xs font-bold uppercase tracking-widest hover:bg-blue-700 transition-all">Record Month End</button>
          </form>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-bold text-slate-500 sticky left-0 bg-slate-50 z-20">Account Category</th>
                {monthsOfYear.map(m => <th key={m} className="px-4 py-4 text-slate-500 text-right">{getMonthLabel(m)}</th>)}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {['Checking', 'Credit cards', 'Savings', 'Investments'].map(group => (
                <tr key={group} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-bold text-slate-800 sticky left-0 bg-white shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{group}</td>
                  {monthsOfYear.map((m, idx) => {
                    const total = group === 'Investments' 
                      ? state.investmentSnapshots.filter(s => s.monthKey === m).reduce((s,a) => s+a.balance, 0)
                      : state.accounts.filter(a => {
                          if(group === 'Checking') return a.type === 'Checking';
                          if(group === 'Credit cards') return a.type === 'Credit';
                          if(group === 'Savings') return a.type === 'Savings';
                          return false;
                        }).reduce((s,a) => s+a.balance, 0);

                    return <td key={m} className="px-4 py-4 text-right font-medium text-slate-600">{Math.round(total)}</td>
                  })}
                </tr>
              ))}
              <tr className="bg-slate-900 text-white">
                <td className="px-6 py-6 font-black tracking-widest sticky left-0 bg-slate-900">Grand Total Net Worth</td>
                {historyData.map(d => <td key={d.monthKey} className="px-4 py-6 text-right font-black text-xs">{formatCurrency(d.value)}</td>)}
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default NetWorth;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot 
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            executeTransfer={executeTransfer} 
            addCategory={addCategory}
            deleteCategory={deleteCategory}
          />
        );
      case 'acc-ledgers':
        return <AccountLedgers state={state} onToggleCleared={toggleCleared} />;
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return <NetWorth state={state} onAddSnapshot={addInvestmentSnapshot} />;
      default:
        return <Dashboard state={state} addTransaction={addTransaction} executeTransfer={executeTransfer} addCategory={addCategory} deleteCategory={deleteCategory} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {/* Removed undefined 'children' variable */}
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  const targetYear = 2025;
  const months = useMemo(() => {
    const res = [];
    for (let i = 0; i < 12; i++) {
      const d = new Date(targetYear, i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const monthLabels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number }>> = {};
    state.categories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent };
      });
    });
    return data;
  }, [state.categories, state.transactions, months]);

  const renderSection = (title: string, catList: any[], field: 'added' | 'spent' | 'net', colorClass: string, showCheckingTotal = false) => {
    return (
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-8">
        <div className={`p-4 ${colorClass} border-b border-slate-200 flex items-center justify-between`}>
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">{title}</h3>
          <span className="text-[10px] font-bold text-slate-400">FY {targetYear}</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase tracking-tighter">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-20 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Category</th>
                {monthLabels.map((l, i) => <th key={i} className="px-3 py-3 text-slate-500 font-bold text-right">{l}</th>)}
                <th className="px-6 py-3 text-slate-900 font-bold text-right bg-slate-100">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {catList.map(cat => {
                let rowTotal = 0;
                return (
                  <tr key={cat.id} className="hover:bg-slate-50 group">
                    <td className="px-6 py-2 text-slate-700 font-bold sticky left-0 bg-white group-hover:bg-slate-50 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.05)] border-r border-slate-100">{cat.name}</td>
                    {months.map(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      let val = 0;
                      if (field === 'added') val = stats.added;
                      else if (field === 'spent') val = stats.spent;
                      else val = stats.added + stats.spent;

                      rowTotal += val;
                      const displayVal = Math.round(Math.abs(val));
                      const isNegative = val < 0;

                      return (
                        <td key={m} className={`px-3 py-2 text-right ${val === 0 ? 'text-slate-200' : isNegative ? 'text-red-500' : 'text-blue-600 font-medium'}`}>
                          {val === 0 ? '-' : (isNegative ? `(${displayVal})` : displayVal)}
                        </td>
                      );
                    })}
                    <td className="px-6 py-2 text-right font-black bg-slate-50 text-slate-900">
                      {Math.round(Math.abs(rowTotal))}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-slate-900 text-white font-bold">
              <tr>
                <td className="px-6 py-3">{showCheckingTotal ? "Checking Total" : "Total"}</td>
                {months.map(m => {
                  let monthTotal = 0;
                  catList.forEach(cat => {
                    const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                    if (field === 'added') monthTotal += stats.added;
                    else if (field === 'spent') monthTotal += stats.spent;
                    else monthTotal += (stats.added + stats.spent);
                  });
                  return <td key={m} className="px-3 py-3 text-right">{Math.round(Math.abs(monthTotal))}</td>;
                })}
                <td className="px-6 py-3 text-right">
                  {Math.round(Math.abs(catList.reduce((acc, cat) => {
                    let catSum = 0;
                    months.forEach(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      if (field === 'added') catSum += stats.added;
                      else if (field === 'spent') catSum += stats.spent;
                      else catSum += (stats.added + stats.spent);
                    });
                    return acc + catSum;
                  }, 0)))}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    );
  };

  const incomeCategories = state.categories.filter(c => c.classificationId === 'class-income');
  const expenseCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
  const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');

  const resourceTotals = months.map(m => incomeCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0));
  const expenseTotalFlow = months.map(m => expenseCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.spent || 0), 0));

  return (
    <div className="space-y-12 pb-24">
      {/* 1. Income Table */}
      {renderSection("Income Summary", incomeCategories, 'added', 'bg-cyan-100')}

      {/* 2. Expenses Table (Spend only) */}
      {renderSection("Expenses Summary", expenseCategories, 'spent', 'bg-red-100')}

      {/* 3. Money Added Summary (Added only) */}
      {renderSection("Money Added Summary", [...expenseCategories], 'added', 'bg-blue-100', true)}

      {/* 4. Activity Net Change (Spent + Added) */}
      {renderSection("Summary Activity (Net Change)", expenseCategories, 'net', 'bg-slate-100')}

      {/* 5. Savings Breakdown */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
        <div className="space-y-0">
          {renderSection("Savings Expenses", savingsCategories, 'spent', 'bg-emerald-50')}
        </div>
        <div className="space-y-0">
          {renderSection("Savings Additions", savingsCategories, 'added', 'bg-emerald-50')}
        </div>
      </div>

      {/* 6. Comparison Table */}
      <div className="bg-slate-900 rounded-xl border border-slate-700 shadow-2xl overflow-hidden">
        <div className="p-4 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
          <h3 className="font-black text-white uppercase text-xs tracking-[0.2em]">Resources vs Expenses Comparison</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter text-slate-300">
            <thead className="border-b border-slate-800">
              <tr>
                <th className="px-6 py-4 font-bold sticky left-0 bg-slate-800 z-10">Metric</th>
                {monthLabels.map((l, i) => <th key={i} className="px-4 py-4 text-right">{l}</th>)}
                <th className="px-6 py-4 text-right bg-slate-800">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 font-bold">
              <tr>
                <td className="px-6 py-4 sticky left-0 bg-slate-900 z-10 text-cyan-400">Resources (Income Total)</td>
                {resourceTotals.map((val, i) => <td key={i} className="px-4 py-4 text-right">{Math.round(val)}</td>)}
                <td className="px-6 py-4 text-right bg-slate-800 text-cyan-400">{Math.round(resourceTotals.reduce((a,b)=>a+b, 0))}</td>
              </tr>
              <tr>
                <td className="px-6 py-4 sticky left-0 bg-slate-900 z-10 text-red-400">Expenses (Spend Total)</td>
                {expenseTotalFlow.map((val, i) => <td key={i} className="px-4 py-4 text-right">({Math.round(Math.abs(val))})</td>)}
                <td className="px-6 py-4 text-right bg-slate-800 text-red-400">({Math.round(Math.abs(expenseTotalFlow.reduce((a,b)=>a+b, 0)))})</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm">
                <td className="px-6 py-6 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest">Net Surplus/Deficit</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotalFlow[i];
                  return <td key={i} className={`px-4 py-6 text-right ${net < 0 ? 'text-red-500' : 'text-green-400'}`}>{formatCurrency(net)}</td>
                })}
                <td className="px-6 py-6 text-right font-black bg-blue-600">
                  {formatCurrency(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotalFlow.reduce((a,b)=>a+b, 0))}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

