export const useFinance = () => {
  const [state, setState] = useState<AppState>(() => {
    // CLONE the initial data
    const base = JSON.parse(JSON.stringify(INITIAL_DATA)) as AppState;

    // CALCULATE initial balances from seed transactions
    base.transactions.forEach(tx => {
      // Update Category
      const cat = base.categories.find(c => c.id === tx.categoryId);
      if (cat) cat.balance += tx.amount;

      // Update Account (if not internal)
      if (tx.accountId !== 'internal' && tx.accountId !== 'none') {
        const acc = base.accounts.find(a => a.id === tx.accountId);
        if (acc) acc.balance += tx.amount;
      }
    });

    return base;
  });

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id, cleared: false };
        newTransactions.push(tx);

        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        if (tx.accountId !== 'none' && tx.accountId !== 'internal') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({ ...txData, accountId: 'internal' });
      } else {
        processSingle(txData);
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        // Tithing logic: Automatically add 10% to Tithing category when income is recorded
        if (txData.type === 'Income' || (selectedCat?.classificationId === 'class-income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const deleteCategory = useCallback((catId: string) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.filter(c => c.id !== catId),
    }));
  }, []);

  const toggleCleared = useCallback((txId: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === txId ? { ...t, cleared: !t.cleared } : t)
    }));
  }, []);

  const updateBudget = useCallback((catId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, monthlyBudget: amount } : c)
    }));
  }, []);

  const setEstIncome = useCallback((amount: number) => {
    setState(prev => ({ ...prev, estimatedMonthlyIncome: amount }));
  }, []);

  const addInvestmentSnapshot = useCallback((snapshot: InvestmentSnapshot) => {
    setState(prev => {
      const filtered = prev.investmentSnapshots.filter(s => !(s.monthKey === snapshot.monthKey && s.accountId === snapshot.accountId));
      return {
        ...prev,
        investmentSnapshots: [...filtered, snapshot]
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string) => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: 'Standard',
          cleared: false
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && accId !== 'internal') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      if (type === 'Update Budget (Allocation)') {
        recordTx(undefined, toCategoryId, amount, description);
      } else {
        switch (type) {
          case 'Category Transfer':
            recordTx(fromAccountId, fromCategoryId, -amount, description);
            recordTx(toAccountId, toCategoryId, amount, description);
            break;
          case 'Transfer to Savings':
            recordTx(fromAccountId, undefined, -amount, description);
            recordTx(undefined, toCategoryId, amount, description);
            break;
          case 'Transfer to Checking':
            recordTx(toAccountId, toCategoryId, amount, description);
            recordTx(undefined, fromCategoryId, -amount, description);
            break;
          default:
            recordTx(fromAccountId, undefined, -amount, description);
            recordTx(toAccountId, undefined, amount, description);
            break;
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];
      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({ id: classId, name: classificationName, color: color || 'bg-gray-100' });
      }
      const newCategory: Category = { id: `cat-${generateId()}`, name, classificationId: classId, balance: 0, monthlyBudget: 0 };
      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot
  };
};

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  const targetYear = 2025;
  const months = useMemo(() => {
    const res = [];
    for (let i = 0; i < 12; i++) {
      const d = new Date(targetYear, i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const monthLabels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number }>> = {};
    state.categories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent };
      });
    });
    return data;
  }, [state.categories, state.transactions, months]);

  const renderSection = (title: string, catList: any[], field: 'added' | 'spent' | 'net', colorClass: string, showCheckingTotal = false) => {
    return (
      <div className="bg-white rounded border border-slate-300 shadow-sm overflow-hidden mb-8">
        <div className={`px-4 py-2 ${colorClass} border-b border-slate-300 flex items-center justify-between`}>
          <h3 className="font-bold text-slate-800 uppercase text-[11px] tracking-widest">{title}</h3>
          <span className="text-[10px] font-bold text-slate-400">20{targetYear.toString().slice(-2)}</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase border-collapse">
            <thead className="bg-slate-50 border-b border-slate-300">
              <tr>
                <th className="px-4 py-2 text-slate-500 font-bold border-r border-slate-200 sticky left-0 bg-slate-50 z-20">Category</th>
                {monthLabels.map((l, i) => (
                  <th key={i} className="px-2 py-2 text-slate-500 font-bold text-right border-r border-slate-200 last:border-r-0">
                    {l}{targetYear.toString().slice(-2)}
                  </th>
                ))}
                <th className="px-4 py-2 text-slate-900 font-bold text-right bg-slate-100 border-l border-slate-300">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {catList.map(cat => {
                let rowTotal = 0;
                return (
                  <tr key={cat.id} className="hover:bg-slate-50 group h-7">
                    <td className="px-4 py-1 text-slate-700 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{cat.name}</td>
                    {months.map(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      let val = 0;
                      if (field === 'added') val = stats.added;
                      else if (field === 'spent') val = stats.spent;
                      else val = stats.added + stats.spent;

                      rowTotal += val;
                      const displayVal = Math.round(Math.abs(val));
                      const isNegative = val < 0;

                      return (
                        <td key={m} className={`px-2 py-1 text-right border-r border-slate-200 last:border-r-0 ${val === 0 ? 'text-slate-200' : isNegative ? 'text-red-500' : 'text-slate-700'}`}>
                          {val === 0 ? '-' : (isNegative ? `(${displayVal.toLocaleString()})` : displayVal.toLocaleString())}
                        </td>
                      );
                    })}
                    <td className="px-4 py-1 text-right font-bold bg-slate-50 text-slate-900 border-l border-slate-300">
                      {Math.round(Math.abs(rowTotal)).toLocaleString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-slate-900 text-white font-bold h-8">
              <tr>
                <td className="px-4 py-1 uppercase tracking-widest text-[9px] sticky left-0 bg-slate-900">{showCheckingTotal ? "Checking Total" : "Total"}</td>
                {months.map(m => {
                  let monthTotal = 0;
                  catList.forEach(cat => {
                    const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                    if (field === 'added') monthTotal += stats.added;
                    else if (field === 'spent') monthTotal += stats.spent;
                    else monthTotal += (stats.added + stats.spent);
                  });
                  return <td key={m} className="px-2 py-1 text-right border-r border-slate-700 last:border-r-0">{Math.round(Math.abs(monthTotal)).toLocaleString()}</td>;
                })}
                <td className="px-4 py-1 text-right bg-slate-800">
                  {Math.round(Math.abs(catList.reduce((acc, cat) => {
                    let catSum = 0;
                    months.forEach(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      if (field === 'added') catSum += stats.added;
                      else if (field === 'spent') catSum += stats.spent;
                      else catSum += (stats.added + stats.spent);
                    });
                    return acc + catSum;
                  }, 0))).toLocaleString()}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    );
  };

  const incomeCategories = state.categories.filter(c => c.classificationId === 'class-income');
  const expenseCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
  const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');

  const resourceTotals = months.map(m => incomeCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0));
  const expenseTotalFlow = months.map(m => expenseCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.spent || 0), 0));

  return (
    <div className="space-y-6 pb-24">
      {/* 1. Income Summary */}
      {renderSection("Income Summary", incomeCategories, 'added', 'bg-cyan-50')}

      {/* 2. Expenses Summary */}
      {renderSection("Expenses Summary", expenseCategories, 'spent', 'bg-red-50')}

      {/* 3. Money Added Summary */}
      {renderSection("Money Added Summary", expenseCategories, 'added', 'bg-blue-50', true)}

      {/* 4. Activity Summary */}
      {renderSection("Summary Activity (Net)", expenseCategories, 'net', 'bg-slate-50')}

      {/* 5. Savings Summary - Stacked Full Width */}
      <div className="space-y-2">
        {renderSection("Savings Expenses", savingsCategories, 'spent', 'bg-emerald-50')}
        {renderSection("Savings Additions", savingsCategories, 'added', 'bg-emerald-50')}
      </div>

      {/* 6. Resources vs Expenses Comparison */}
      <div className="bg-slate-900 rounded border border-slate-700 shadow-2xl overflow-hidden mt-12">
        <div className="px-4 py-3 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
          <h3 className="font-black text-white uppercase text-[12px] tracking-widest">Resources vs Expenses Analysis</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter text-slate-300 border-collapse">
            <thead className="border-b border-slate-800 bg-slate-800/50">
              <tr>
                <th className="px-6 py-3 font-bold sticky left-0 bg-slate-800 z-10 border-r border-slate-700">Metric</th>
                {monthLabels.map((l, i) => <th key={i} className="px-3 py-3 text-right border-r border-slate-700 last:border-r-0">{l}25</th>)}
                <th className="px-6 py-3 text-right bg-slate-800 border-l border-slate-700">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 font-bold">
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-cyan-400 border-r border-slate-800">Resources (Income)</td>
                {resourceTotals.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">{Math.round(val).toLocaleString()}</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-cyan-400 border-l border-slate-700">{Math.round(resourceTotals.reduce((a,b)=>a+b, 0)).toLocaleString()}</td>
              </tr>
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-red-400 border-r border-slate-800">Expenses (Total Spend)</td>
                {expenseTotalFlow.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">({Math.round(Math.abs(val)).toLocaleString()})</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-red-400 border-l border-slate-700">({Math.round(Math.abs(expenseTotalFlow.reduce((a,b)=>a+b, 0))).toLocaleString()})</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm h-14">
                <td className="px-6 py-4 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest border-r border-slate-800 shadow-[4px_0_10px_rgba(0,0,0,0.2)]">Net Cash Flow</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotalFlow[i];
                  return <td key={i} className={`px-3 py-4 text-right border-r border-slate-800 last:border-r-0 ${net < 0 ? 'text-red-500 font-black' : 'text-green-400 font-black'}`}>{Math.round(net).toLocaleString()}</td>
                })}
                <td className="px-6 py-4 text-right font-black bg-blue-600 shadow-[-4px_0_10px_rgba(0,0,0,0.2)]">
                  {Math.round(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotalFlow.reduce((a,b)=>a+b, 0)).toLocaleString()}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Summary;

