            <tr>
              <td className="px-6 py-4 uppercase tracking-widest text-xs">Total Monthly Targets</td>
              <td className="px-4 py-4 text-right text-lg">{formatCurrency(totalBudgeted)}</td>
              <td colSpan={2}></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

