import React, { useMemo, useState } from 'react';
import { AlertCircle, Plus, Trash2 } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
  deleteCategory: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, executeTransfer, addCategory, deleteCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories.map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, monthlyAdded: added, monthlySpent: spent };
    });
  }, [state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const reconciliation = useMemo(() => {
    const capOne = state.accounts.find(a => a.id === 'acc-cap-checking')?.balance || 0;
    const dsChecking = state.accounts.find(a => a.id === 'acc-ds-6521')?.balance || 0;
    const dsCredit = state.accounts.find(a => a.id === 'acc-ds-8193')?.balance || 0;
    const visaCredit = state.accounts.find(a => a.id === 'acc-visa-4914')?.balance || 0;

    const debitBalance = capOne + dsChecking;
    const creditBalance = dsCredit + visaCredit;
    const net = debitBalance + creditBalance;

    // Allocated Budget: Sum of all category balances that are funded by these liquid accounts
    // Typically this excludes "Income" source categories and "Savings" if they are tracked in a separate Savings account
    const budgetCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
    const totalAllocated = budgetCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      capOne,
      dsChecking,
      dsCredit,
      visaCredit,
      debitBalance,
      creditBalance,
      net,
      totalAllocated,
      difference: net - totalAllocated
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const handleDelete = (id: string, name: string) => {
    if (window.confirm(`Are you sure you want to delete the category "${name}"? This action cannot be undone.`)) {
      deleteCategory(id);
    }
  };

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings'].includes(c.id));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <button onClick={() => setShowAddCat(true)} className="flex items-center gap-1 text-blue-600 hover:text-blue-700 text-xs font-bold"><Plus size={14} /> Add Category</button>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right">Spent</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => (
                <React.Fragment key={cls.id}>
                  <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={6} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                  {(groupedCategories[cls.id] || []).map(cat => (
