import { AppState } from './types';

// Helper to generate IDs
const gid = () => Math.random().toString(36).substr(2, 5);

const generateFullSeedData = () => {
  const txs: any[] = [];

  const add = (cat: string, date: string, amt: number, desc: string, acc: string = 'internal', type: string = 'Standard') => {
    // Shift dates from early 2025 to late 2025/2026 for the new view range
    const originalDate = new Date(date);
    // Add 11 months to shift Jan 2025 -> Dec 2025
    originalDate.setMonth(originalDate.getMonth() + 11);
    const shiftedDate = originalDate.toISOString().split('T')[0];

    txs.push({
      id: `seed-${gid()}`,
      date: shiftedDate,
      amount: amt,
      description: desc,
      accountId: acc,
      categoryId: cat,
      type: type as any,
      cleared: false
    });
  };

  // --- TITHING LEDGER ---
  add('cat-tithing', '2025-01-09', 0.88, 'Paycheck Benson');
  add('cat-tithing', '2025-01-09', 5.63, 'Paycheck Kealani');
  add('cat-tithing', '2025-01-23', 24.13, 'Paycheck Benson');
  add('cat-tithing', '2025-01-23', 50.71, 'Paycheck Kealani');
  add('cat-tithing', '2025-01-27', -291.98, 'Tithing', 'acc-ds-6521');
  add('cat-tithing', '2025-02-06', 43.91, 'Paycheck Kealani');
  add('cat-tithing', '2025-02-06', 39.68, 'Paycheck Benson');

  // --- FAST OFFERINGS LEDGER ---
  const foDates = [
    '2025-01-18', '2025-02-16'
  ];
  foDates.forEach(d => {
    add('cat-fast', d, 35.00, 'Update budget', 'internal', 'Update Budget (Allocation)');
    add('cat-fast', d, -35.00, 'Fast offering payment', 'acc-ds-6521');
  });

  // --- RENT LEDGER ---
  add('cat-rent', '2025-01-06', -1000.00, 'Rent (Venmo Kealani)', 'acc-cap-checking');
  add('cat-rent', '2025-01-11', 2000.00, 'Updating budget', 'internal', 'Update Budget (Allocation)');
  add('cat-rent', '2025-01-18', 600.00, 'Scholarship money', 'internal', 'Update Budget (Allocation)');

  // --- GAS LEDGER ---
  add('cat-gas', '2025-01-04', -48.32, 'Gas from Costco', 'acc-cap-checking');
  add('cat-gas', '2025-01-11', 64.28, 'Update budget', 'internal', 'Update Budget (Allocation)');
  add('cat-gas', '2025-01-20', -41.24, 'Gas - Costco', 'acc-cap-checking');

  // --- FOOD LEDGER ---
  add('cat-food', '2025-01-04', -217.57, 'Groceries Costco', 'acc-cap-checking');
  add('cat-food', '2025-01-11', 592.42, 'Update budget', 'internal', 'Update Budget (Allocation)');
  add('cat-food', '2025-01-15', -10.98, "Day's Market Groceries", 'acc-ds-8193');

  // --- INCOME ---
  add('cat-income', '2025-01-05', 5000, 'Monthly Salary', 'acc-ds-6521', 'Income');

  return txs;
};

