import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  // Range: Dec 2025 to Dec 2026 (13 months)
  const months = useMemo(() => {
    const res = [];
    const startDate = new Date(2025, 11, 1); // December 2025
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number }>> = {};
    state.categories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent };
      });
    });
    return data;
  }, [state.categories, state.transactions, months]);

  const renderSection = (title: string, catList: any[], field: 'added' | 'spent' | 'net', colorClass: string, showCheckingTotal = false) => {
    return (
      <div className="bg-white rounded border border-slate-300 shadow-sm overflow-hidden mb-8">
        <div className={`px-4 py-2 ${colorClass} border-b border-slate-300 flex items-center justify-between`}>
          <h3 className="font-bold text-slate-800 uppercase text-[11px] tracking-widest">{title}</h3>
          <span className="text-[10px] font-bold text-slate-400">DEC '25 - DEC '26</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase border-collapse">
            <thead className="bg-slate-50 border-b border-slate-300">
              <tr>
                <th className="px-4 py-2 text-slate-500 font-bold border-r border-slate-200 sticky left-0 bg-slate-50 z-20">Category</th>
                {months.map((m, i) => {
                  const d = new Date(m + "-01");
                  const label = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
                  return (
                    <th key={i} className="px-2 py-2 text-slate-500 font-bold text-right border-r border-slate-200 last:border-r-0">
                      {label}
                    </th>
                  );
                })}
                <th className="px-4 py-2 text-slate-900 font-bold text-right bg-slate-100 border-l border-slate-300">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {catList.map(cat => {
                let rowTotal = 0;
                return (
                  <tr key={cat.id} className="hover:bg-slate-50 group h-7">
                    <td className="px-4 py-1 text-slate-700 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{cat.name}</td>
                    {months.map(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      let val = 0;
                      if (field === 'added') val = stats.added;
                      else if (field === 'spent') val = stats.spent;
                      else val = stats.added + stats.spent;

                      rowTotal += val;
                      const displayVal = Math.round(Math.abs(val));
                      const isNegative = val < 0;

                      return (
                        <td key={m} className={`px-2 py-1 text-right border-r border-slate-200 last:border-r-0 ${val === 0 ? 'text-slate-200' : isNegative ? 'text-red-500' : 'text-slate-700'}`}>
                          {val === 0 ? '-' : (isNegative ? `(${displayVal.toLocaleString()})` : displayVal.toLocaleString())}
                        </td>
                      );
                    })}
                    <td className="px-4 py-1 text-right font-bold bg-slate-50 text-slate-900 border-l border-slate-300">
                      {Math.round(Math.abs(rowTotal)).toLocaleString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-slate-900 text-white font-bold h-8">
              <tr>
                <td className="px-4 py-1 uppercase tracking-widest text-[9px] sticky left-0 bg-slate-900">{showCheckingTotal ? "Checking Total" : "Total"}</td>
                {months.map(m => {
                  let monthTotal = 0;
                  catList.forEach(cat => {
                    const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                    if (field === 'added') monthTotal += stats.added;
                    else if (field === 'spent') monthTotal += stats.spent;
                    else monthTotal += (stats.added + stats.spent);
                  });
                  return <td key={m} className="px-2 py-1 text-right border-r border-slate-700 last:border-r-0">{Math.round(Math.abs(monthTotal)).toLocaleString()}</td>;
                })}
                <td className="px-4 py-1 text-right bg-slate-800">
                  {Math.round(Math.abs(catList.reduce((acc, cat) => {
                    let catSum = 0;
                    months.forEach(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      if (field === 'added') catSum += stats.added;
                      else if (field === 'spent') catSum += stats.spent;
                      else catSum += (stats.added + stats.spent);
                    });
                    return acc + catSum;
                  }, 0))).toLocaleString()}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    );
  };

  const incomeCategories = state.categories.filter(c => c.classificationId === 'class-income');
  const expenseCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
  const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');

  const resourceTotals = months.map(m => incomeCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0));
  const expenseTotalFlow = months.map(m => expenseCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.spent || 0), 0));

  return (
    <div className="space-y-6 pb-24">
      {/* 1. Income Summary */}
      {renderSection("Income Summary", incomeCategories, 'added', 'bg-cyan-50')}

      {/* 2. Expenses Summary */}
      {renderSection("Expenses Summary", expenseCategories, 'spent', 'bg-red-50')}

      {/* 3. Money Added Summary */}
      {renderSection("Money Added Summary", expenseCategories, 'added', 'bg-blue-50', true)}

      {/* 4. Activity Summary */}
      {renderSection("Summary Activity (Net)", expenseCategories, 'net', 'bg-slate-50')}

      {/* 5. Savings Summary - Stacked Full Width */}
      <div className="space-y-2">
        {renderSection("Savings Expenses", savingsCategories, 'spent', 'bg-emerald-50')}
        {renderSection("Savings Additions", savingsCategories, 'added', 'bg-emerald-50')}
      </div>

      {/* 6. Resources vs Expenses Comparison */}
      <div className="bg-slate-900 rounded border border-slate-700 shadow-2xl overflow-hidden mt-12">
        <div className="px-4 py-3 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
          <h3 className="font-black text-white uppercase text-[12px] tracking-widest">Resources vs Expenses Analysis</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter text-slate-300 border-collapse">
            <thead className="border-b border-slate-800 bg-slate-800/50">
              <tr>
                <th className="px-6 py-3 font-bold sticky left-0 bg-slate-800 z-10 border-r border-slate-700">Metric</th>
                {months.map((m, i) => {
                   const d = new Date(m + "-01");
                   return <th key={i} className="px-3 py-3 text-right border-r border-slate-700 last:border-r-0">{d.toLocaleDateString('en-US', {month: 'short', year:'2-digit'})}</th>;
                })}
                <th className="px-6 py-3 text-right bg-slate-800 border-l border-slate-700">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 font-bold">
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-cyan-400 border-r border-slate-800">Resources (Income)</td>
                {resourceTotals.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">{Math.round(val).toLocaleString()}</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-cyan-400 border-l border-slate-700">{Math.round(resourceTotals.reduce((a,b)=>a+b, 0)).toLocaleString()}</td>
              </tr>
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-red-400 border-r border-slate-800">Expenses (Total Spend)</td>
                {expenseTotalFlow.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">({Math.round(Math.abs(val)).toLocaleString()})</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-red-400 border-l border-slate-700">({Math.round(Math.abs(expenseTotalFlow.reduce((a,b)=>a+b, 0))).toLocaleString()})</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm h-14">
                <td className="px-6 py-4 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest border-r border-slate-800 shadow-[4px_0_10px_rgba(0,0,0,0.2)]">Net Cash Flow</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotalFlow[i];
                  return <td key={i} className={`px-3 py-4 text-right border-r border-slate-800 last:border-r-0 ${net < 0 ? 'text-red-500 font-black' : 'text-green-400 font-black'}`}>{Math.round(net).toLocaleString()}</td>
                })}
                <td className="px-6 py-4 text-right font-black bg-blue-600 shadow-[-4px_0_10px_rgba(0,0,0,0.2)]">
                  {Math.round(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotalFlow.reduce((a,b)=>a+b, 0)).toLocaleString()}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Summary;

import React, { useMemo, useState } from 'react';
import { AppState, Account, InvestmentSnapshot } from '../types';
import { formatCurrency, getMonthLabel, getMonthYearKey } from '../utils';
import { CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, XAxis, YAxis } from 'recharts';

interface NetWorthProps {
  state: AppState;
  onAddSnapshot: (s: InvestmentSnapshot) => void;
}

const NetWorth: React.FC<NetWorthProps> = ({ state, onAddSnapshot }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>("2025-12");
  const [editValues, setEditValues] = useState<Record<string, string>>({});

  // Range: Dec 2025 to Dec 2026
  const monthsOfYear = useMemo<string[]>(() => {
    const res: string[] = [];
    const startDate = new Date(2025, 11, 1);
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const historyData = useMemo(() => {
    return monthsOfYear.map(m => {
      const liquidTotal = state.accounts.filter(a => ['Checking', 'Credit', 'Savings'].includes(a.type)).reduce((s, a) => s + a.balance, 0);
      const snapshotTotal = state.investmentSnapshots.filter(s => s.monthKey === m).reduce((s, a) => s + a.balance, 0);
      return { monthKey: m, label: getMonthLabel(m + "-01"), value: liquidTotal + snapshotTotal };
    });
  }, [state.accounts, state.investmentSnapshots, monthsOfYear]);

  const handleSaveSnapshot = (e: React.FormEvent) => {
    e.preventDefault();
    (Object.entries(editValues) as [string, string][]).forEach(([accId, val]) => {
      if (val) onAddSnapshot({ monthKey: selectedMonth, accountId: accId, balance: parseFloat(val) });
    });
    setEditValues({});
  };

  const investmentAccounts = state.accounts.filter(a => a.type === 'Investment');

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-6">Annual Net Worth Velocity</h3>
          <div className="h-48 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={historyData}>
                <defs>
                  <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8'}} tickFormatter={(v) => `$${v/1000}k`} />
                <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorNet)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-900 rounded-xl p-6 text-white">
          <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4">Manual Investment Update</h4>
          <form onSubmit={handleSaveSnapshot} className="space-y-4">
            <select 
              value={selectedMonth} 
              onChange={e => setSelectedMonth(e.target.value)}
              className="w-full bg-slate-800 border-none text-sm rounded-lg p-2 focus:ring-1 focus:ring-blue-500"
            >
              {monthsOfYear.map(m => <option key={m} value={m}>{getMonthLabel(m + "-01")}</option>)}
            </select>
            {investmentAccounts.map(acc => (
              <div key={acc.id} className="space-y-1">
                <label className="text-[9px] text-slate-500 uppercase">{acc.name}</label>
                <input 
                  type="number" 
                  step="0.01" 
                  className="w-full bg-slate-800 border-none rounded-lg p-2 text-sm"
                  placeholder={formatCurrency(acc.balance)}
                  value={editValues[acc.id] || ''}
                  onChange={e => setEditValues({...editValues, [acc.id]: e.target.value})}
                />
              </div>
            ))}
            <button type="submit" className="w-full bg-blue-600 py-3 rounded-lg text-xs font-bold uppercase tracking-widest hover:bg-blue-700 transition-all">Record Month End</button>
          </form>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-bold text-slate-500 sticky left-0 bg-slate-50 z-20">Account Category</th>
                {monthsOfYear.map(m => <th key={m} className="px-4 py-4 text-slate-500 text-right">{getMonthLabel(m + "-01")}</th>)}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {['Checking', 'Credit cards', 'Savings', 'Investments'].map(group => (
                <tr key={group} className="hover:bg-slate-50">
                  <td className="px-6 py-4 font-bold text-slate-800 sticky left-0 bg-white shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{group}</td>
                  {monthsOfYear.map((m) => {
                    const total = group === 'Investments' 
                      ? state.investmentSnapshots.filter(s => s.monthKey === m).reduce((s,a) => s+a.balance, 0)
                      : state.accounts.filter(a => {
                          if(group === 'Checking') return a.type === 'Checking';
                          if(group === 'Credit cards') return a.type === 'Credit';
                          if(group === 'Savings') return a.type === 'Savings';
                          return false;
                        }).reduce((s,a) => s+a.balance, 0);

                    return <td key={m} className="px-4 py-4 text-right font-medium text-slate-600">{Math.round(total).toLocaleString()}</td>
                  })}
                </tr>
              ))}
              <tr className="bg-slate-900 text-white">
                <td className="px-6 py-6 font-black tracking-widest sticky left-0 bg-slate-900">Grand Total Net Worth</td>
                {historyData.map(d => <td key={d.monthKey} className="px-4 py-6 text-right font-black text-xs">{formatCurrency(d.value)}</td>)}
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default NetWorth;

import React, { useState } from 'react';
import { Plus, ArrowRightLeft, Calendar, DollarSign, Tag, Landmark, FileText } from 'lucide-react';
import { AppState, TransactionType } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ state, onAddTransaction, onExecuteTransfer }) => {
  const [activeMode, setActiveMode] = useState<'transact' | 'transfer' | 'budget'>('transact');
  const [formData, setFormData] = useState({
    categoryId: '',
    date: '2025-12-01',
    accountId: '',
    amount: '',
    description: '',
    type: 'Standard' as TransactionType,
    toCategoryId: '',
    toAccountId: '',
    fromCategoryId: '',
    fromAccountId: '',
    transferType: TRANSFER_TYPES[0]
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (activeMode === 'transact') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: parseFloat(formData.amount),
        description: formData.description,
        type: formData.type,
      });
    } else if (activeMode === 'budget') {
      onAddTransaction({
        categoryId: formData.toCategoryId,
        date: formData.date,
        accountId: 'internal',
        amount: parseFloat(formData.amount),
        description: formData.description || 'Budget Allocation',
        type: 'Update Budget (Allocation)' as any,
      });
    } else {
      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: parseFloat(formData.amount),
        description: formData.description,
        fromAccountId: formData.fromAccountId,
        toAccountId: formData.toAccountId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }
    setFormData(prev => ({ ...prev, amount: '', description: '' }));
  };

  const inputStyles = "w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:outline-none transition-all";

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        <button onClick={() => setActiveMode('transact')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest ${activeMode === 'transact' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>Transact</button>
        <button onClick={() => setActiveMode('budget')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest ${activeMode === 'budget' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>Allocation</button>
        <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest ${activeMode === 'transfer' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>Transfer</button>
      </div>

      <form onSubmit={handleSubmit} className="p-5 space-y-4">
        {activeMode === 'budget' ? (
          <>
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
              <p className="text-[10px] text-blue-600 font-bold uppercase tracking-wider mb-1">Budget Allocation</p>
              <p className="text-[11px] text-blue-400">Moves internal funds into a category bucket without impacting bank balances.</p>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Apply to Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Destination</option>
                  {state.categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
              </div>
            </div>
          </>
        ) : activeMode === 'transact' ? (
          <div className="space-y-4">
             <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Category</option>
                  {state.categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
              </div>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Account</label>
              <div className="relative">
                <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Account</option>
                  {state.accounts.filter(a => ['Checking', 'Credit', 'Savings'].includes(a.type)).map(acc => (
                    <option key={acc.id} value={acc.id}>{acc.name}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        ) : (
          <div>
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Transfer Type</label>
            <select value={formData.transferType} onChange={e => setFormData({...formData, transferType: e.target.value as any})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm mb-4">
              {TRANSFER_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
            </select>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Amount</label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className={inputStyles} placeholder="0.00" required />
            </div>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Date</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className={inputStyles} required />
            </div>
          </div>
        </div>

        <div>
          <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5">Description</label>
          <div className="relative">
            <FileText className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className={inputStyles} placeholder="Transaction details..." />
          </div>
        </div>

        <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3 rounded-lg text-xs uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-colors active:scale-95">
          Record {activeMode}
        </button>
      </form>
    </div>
  );
};

