  state: AppState;
  onToggleCleared: (id: string) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ state, onToggleCleared }) => {
  const targetAccountIds = [
    'acc-ds-8193', 
    'acc-visa-4914', 
    'acc-ds-6521', 
    'acc-cap-checking', 
    'internal', 
    'internal-deposit', 
    'internal-transfers'
  ];
  const [activeAccId, setActiveAccId] = useState(targetAccountIds[4]); // Default to 'internal' (Allocation) as per user screenshot context

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-deposit': { name: 'Deposit', types: ['Income'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal');
  const activeAccount = isVirtual 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'internal-deposit') return t.type === 'Income';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
