                })
              ) : (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-bold">No transactions found for this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

