import { useState, useCallback } from 'react';
import { AppState, Transaction, Category, InvestmentSnapshot } from '../types';
import { INITIAL_DATA } from '../constants';
import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(() => {
    const base = JSON.parse(JSON.stringify(INITIAL_DATA)) as AppState;
    base.transactions.forEach(tx => {
      const cat = base.categories.find(c => c.id === tx.categoryId);
      if (cat) cat.balance += tx.amount;
      if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
        const acc = base.accounts.find(a => a.id === tx.accountId);
        if (acc) acc.balance += tx.amount;
      }
    });
    return base;
  });

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id, cleared: false };
        newTransactions.push(tx);

        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({ ...txData, accountId: 'internal' });
      } else {
        processSingle(txData);
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        if (txData.type === 'Income' || (selectedCat?.classificationId === 'class-income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const deleteTransaction = useCallback((txId: string) => {
    setState(prev => {
      const txToDelete = prev.transactions.find(t => t.id === txId);
      if (!txToDelete) return prev;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === txToDelete.categoryId) {
          return { ...cat, balance: cat.balance - txToDelete.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === txToDelete.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - txToDelete.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const undoLastTransaction = useCallback(() => {
    setState(prev => {
      if (prev.transactions.length === 0) return prev;
      const lastTx = prev.transactions[prev.transactions.length - 1];
      const txId = lastTx.id;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === lastTx.categoryId) {
          return { ...cat, balance: cat.balance - lastTx.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === lastTx.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - lastTx.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const deleteCategory = useCallback((catId: string) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, deleted: true } : c),
    }));
  }, []);

  const toggleCleared = useCallback((txId: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === txId ? { ...t, cleared: !t.cleared } : t)
    }));
  }, []);

  const updateBudget = useCallback((catId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, monthlyBudget: amount } : c)
    }));
  }, []);

  const setEstIncome = useCallback((amount: number) => {
    setState(prev => ({ ...prev, estimatedMonthlyIncome: amount }));
  }, []);

  const addInvestmentSnapshot = useCallback((snapshot: InvestmentSnapshot) => {
    setState(prev => {
      const filtered = prev.investmentSnapshots.filter(s => !(s.monthKey === snapshot.monthKey && s.accountId === snapshot.accountId));
      return {
        ...prev,
        investmentSnapshots: [...filtered, snapshot]
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string, txType: any = 'Standard') => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: txType,
          cleared: false
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && !accId.startsWith('internal') && accId !== 'none') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      switch (type) {
        case 'Category Transfer':
          recordTx(fromAccountId, fromCategoryId, -amount, description, 'Category Transfer');
          recordTx(toAccountId, toCategoryId, amount, description, 'Category Transfer');
          break;
        case 'Transfer to Savings':
          recordTx(undefined, toCategoryId, amount, description, 'Transfer to Savings');
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer to Savings');
          break;
        case 'Transfer to Checking':
          recordTx(toAccountId, toCategoryId, amount, description, 'Transfer to Checking');
          recordTx(undefined, fromCategoryId, -amount, description, 'Transfer to Checking');
          break;
        case 'Credit Payment':
          recordTx(fromAccountId, undefined, -amount, description, 'Credit Payment');
          recordTx(toAccountId, undefined, amount, description, 'Credit Payment');
          break;
        case 'Transfer between Checking':
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer between Checking');
          recordTx(toAccountId, undefined, amount, description, 'Transfer between Checking');
          break;
        case 'Update Budget (Allocation)':
          recordTx(undefined, toCategoryId, amount, description, 'Update Budget (Allocation)');
          break;
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];
      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({ id: classId, name: classificationName, color: color || 'bg-gray-100' });
      }
      const newCategory: Category = { id: `cat-${generateId()}`, name, classificationId: classId, balance: 0, monthlyBudget: 0 };
      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot
  };
};

import React, { useMemo, useState } from 'react';
import { AlertCircle, Plus, Trash2, Undo2 } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  undoLastTransaction: () => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
  deleteCategory: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, undoLastTransaction, executeTransfer, addCategory, deleteCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories
      .filter(cat => !cat.deleted)
      .map(cat => {
        const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
        const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        return { ...cat, monthlyAdded: added, monthlySpent: spent };
      });
  }, [state.categories, state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const reconciliation = useMemo(() => {
    const capOne = state.accounts.find(a => a.id === 'acc-cap-checking')?.balance || 0;
    const dsChecking = state.accounts.find(a => a.id === 'acc-ds-6521')?.balance || 0;
    const dsCredit = state.accounts.find(a => a.id === 'acc-ds-8193')?.balance || 0;
    const visaCredit = state.accounts.find(a => a.id === 'acc-visa-4914')?.balance || 0;

    const debitBalance = capOne + dsChecking;
    const creditBalance = dsCredit + visaCredit;
    const net = debitBalance + creditBalance;

    const budgetCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
    const totalAllocated = budgetCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      capOne,
      dsChecking,
      dsCredit,
      visaCredit,
      debitBalance,
      creditBalance,
      net,
      totalAllocated,
      difference: net - totalAllocated
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const handleDelete = (id: string, name: string) => {
    if (window.confirm(`Are you sure you want to delete the category "${name}"? It will be hidden from this statement and transaction dropdowns, but its history will be kept.`)) {
      deleteCategory(id);
    }
  };

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings'].includes(c.id));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <div className="flex items-center gap-4">
               <button 
                  onClick={() => undoLastTransaction()} 
                  className="flex items-center gap-1.5 text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-slate-100"
                >
                  <Undo2 size={12} /> Undo Last
                </button>
                <button 
                  onClick={() => setShowAddCat(true)} 
                  className="flex items-center gap-1.5 text-blue-600 hover:text-blue-700 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-blue-50"
                >
                  <Plus size={12} /> Add Category
                </button>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Spent</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => {
                const cats = groupedCategories[cls.id] || [];
                if (cats.length === 0) return null;
                return (
                  <React.Fragment key={cls.id}>
                    <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={6} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                    {cats.map(cat => (
                      <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400 group">
                        <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                        <td className={`px-4 py-2 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(cat.balance)}</td>
                        <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                        <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                        <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? `(${formatCurrency(Math.abs(cat.monthlySpent))})` : '-'}</td>
                        <td className="px-4 py-2 text-right">
                          <button 
                            onClick={() => handleDelete(cat.id, cat.name)}
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-red-50"
                          >
                            <Trash2 size={14} />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="space-y-6">
        <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />

        <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
          <h3 className="text-[10px] text-slate-500 mb-2">Budget Reconciliation</h3>

          <div className="space-y-3">
            <div className="flex justify-between">
              <span>Capital One Checking</span>
              <span className="text-white">{formatCurrency(reconciliation.capOne)}</span>
            </div>

            <div className="flex justify-between">
              <span>Discover Checking</span>
              <span className="text-white">{formatCurrency(reconciliation.dsChecking)}</span>
            </div>

            <div className="flex justify-between">
              <span>Discover Credit</span>
