import React, { useState } from 'react';
import { AppState } from '../types';
import { formatCurrency } from '../utils';
import { CheckCircle, Circle, Trash2 } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ state, onToggleCleared, onDeleteTransaction }) => {
  const targetAccountIds = [
    'acc-ds-8193', 
    'acc-visa-4914', 
    'acc-ds-6521', 
    'acc-cap-checking', 
    'internal', 
    'internal-deposit', 
    'internal-transfers'
  ];
  const [activeAccId, setActiveAccId] = useState(targetAccountIds[0]); 

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-deposit': { name: 'Deposit', types: ['Income'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal');
  const activeAccount = isVirtual 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'internal-deposit') return t.type === 'Income';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const handleDelete = (txId: string) => {
    if (window.confirm("Are you sure you want to delete this transaction? This will reverse its financial impact across all ledgers.")) {
      onDeleteTransaction(txId);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-4 items-center pb-2">
        <div className="flex gap-2 overflow-x-auto custom-scrollbar no-scrollbar">
          {targetAccountIds.slice(0, 4).map(id => {
            const name = state.accounts.find(a => a.id === id)?.name;
            if (!name) return null;
            return (
              <button
                key={id}
                onClick={() => setActiveAccId(id)}
                className={`px-5 py-2 rounded-full text-[10px] font-bold transition-all whitespace-nowrap uppercase tracking-widest border border-slate-200 ${
                  activeAccId === id 
                    ? 'bg-slate-900 text-white shadow-lg border-slate-900' 
                    : 'bg-white text-slate-400 hover:border-slate-300'
                }`}
              >
                {name}
              </button>
            );
          })}
        </div>

        <div className="flex gap-6 items-center px-4 ml-2">
          {targetAccountIds.slice(4).map(id => {
            const name = virtualAccountMap[id]?.name;
            if (!name) return null;
            const isActive = activeAccId === id;
            return (
              <button
                key={id}
                onClick={() => setActiveAccId(id)}
                className={`text-[10px] font-black uppercase tracking-widest transition-all ${
                  isActive 
                    ? 'bg-slate-900 text-white px-5 py-2 rounded-full shadow-lg' 
                    : 'text-slate-400 hover:text-slate-900 px-2'
                }`}
              >
                {name}
              </button>
            );
          })}
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {isVirtual ? `Internal Budget ${activeAccount?.name}s` : `${activeAccount?.name} Activity`}
          </h3>
          {!isVirtual && (
            <div className="text-sm font-bold text-slate-900">
              Total Balance: {formatCurrency(activeAccount?.balance || 0)}
            </div>
          )}
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Category</th>
                <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Date</th>
                <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter text-right">Amount</th>
                <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Description</th>
                <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter text-center">Cleared</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map(tx => {
                  const cat = state.categories.find(c => c.id === tx.categoryId);
                  const isCredit = activeAccount?.type === 'Credit';
                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-6 py-3 text-slate-600 font-medium">
                        {cat?.name || 'Uncategorized'}
                        {cat?.deleted && <span className="ml-2 text-[8px] bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded uppercase font-black">Archived</span>}
                      </td>
                      <td className="px-4 py-3 text-slate-400">{new Date(tx.date).toLocaleDateString()}</td>
                      <td className={`px-4 py-3 text-right font-bold ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                        {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                      </td>
                      <td className="px-6 py-3 text-slate-600">{tx.description}</td>
                      <td className="px-6 py-3 text-center">
                        <button 
                          onClick={() => onToggleCleared(tx.id)}
                          disabled={!isCredit || isVirtual}
                          className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                            (!isCredit || isVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                            tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                          }`}
                        >
                          {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                        </button>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button 
                          onClick={() => handleDelete(tx.id)}
                          className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-bold">No transactions found for this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AccountLedgers;

export const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
  }).format(amount);
};

export const generateId = () => Math.random().toString(36).substr(2, 9);

/**
 * Robustly parses a YYYY-MM-DD string into a Date object that 
 * represents that day in the user's LOCAL timezone.
 */
export const parseLocalDate = (dateStr: string | Date): Date => {
  if (dateStr instanceof Date) return dateStr;
  const [year, month, day] = dateStr.split('-').map(Number);
  // Months are 0-indexed in JS Date constructor
  return new Date(year, month - 1, day);
};

export const getMonthYearKey = (date: Date | string) => {
  const d = parseLocalDate(date);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
};

export const getMonthLabel = (date: Date | string) => {
  return parseLocalDate(date).toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
};

export const formatDisplayDate = (date: string | Date) => {
  return parseLocalDate(date).toLocaleDateString('en-US', { 
    year: 'numeric', 
    month: 'numeric', 
    day: 'numeric' 
  });
};

import React, { useMemo, useState } from 'react';
import { AlertCircle, Plus, Trash2, Undo2 } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  undoLastTransaction: () => void;
  executeTransfer: (transfer: any) => void;
  addCategory: (name: string, className: string, color: string) => void;
  deleteCategory: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, undoLastTransaction, executeTransfer, addCategory, deleteCategory }) => {
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories
      .filter(cat => !cat.deleted)
      .map(cat => {
        const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
        const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        return { ...cat, monthlyAdded: added, monthlySpent: spent };
      });
  }, [state.categories, state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const reconciliation = useMemo(() => {
    const capOne = state.accounts.find(a => a.id === 'acc-cap-checking')?.balance || 0;
    const dsChecking = state.accounts.find(a => a.id === 'acc-ds-6521')?.balance || 0;
    const dsCredit = state.accounts.find(a => a.id === 'acc-ds-8193')?.balance || 0;
    const visaCredit = state.accounts.find(a => a.id === 'acc-visa-4914')?.balance || 0;

    const debitBalance = capOne + dsChecking;
    const creditBalance = dsCredit + visaCredit;
    const net = debitBalance + creditBalance;

    const budgetCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
    const totalAllocated = budgetCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      capOne,
      dsChecking,
      dsCredit,
      visaCredit,
      debitBalance,
      creditBalance,
      net,
      totalAllocated,
      difference: net - totalAllocated
    };
  }, [state.accounts, state.categories]);

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      addCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const handleDelete = (id: string, name: string) => {
    if (window.confirm(`Are you sure you want to delete the category "${name}"? It will be hidden from this statement and transaction dropdowns, but its history will be kept.`)) {
      deleteCategory(id);
    }
  };

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings'].includes(c.id));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <div className="flex items-center gap-4">
               <button 
                  onClick={() => undoLastTransaction()} 
                  className="flex items-center gap-1.5 text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-slate-100"
                >
                  <Undo2 size={12} /> Undo Last
                </button>
                <button 
                  onClick={() => setShowAddCat(true)} 
                  className="flex items-center gap-1.5 text-blue-600 hover:text-blue-700 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-blue-50"
                >
                  <Plus size={12} /> Add Category
                </button>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Spent</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => {
                const cats = groupedCategories[cls.id] || [];
                if (cats.length === 0) return null;
                return (
                  <React.Fragment key={cls.id}>
                    <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={6} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                    {cats.map(cat => (
                      <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400 group">
                        <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                        <td className={`px-4 py-2 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(cat.balance)}</td>
                        <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                        <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                        <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? `(${formatCurrency(Math.abs(cat.monthlySpent))})` : '-'}</td>
                        <td className="px-4 py-2 text-right">
                          <button 
                            onClick={() => handleDelete(cat.id, cat.name)}
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-red-50"
                          >
                            <Trash2 size={14} />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="space-y-6">
        <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />

        <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
          <h3 className="text-[10px] text-slate-500 mb-2">Budget Reconciliation</h3>

          <div className="space-y-3">
            <div className="flex justify-between">
              <span>Capital One Checking</span>
              <span className="text-white">{formatCurrency(reconciliation.capOne)}</span>
            </div>

            <div className="flex justify-between">
              <span>Discover Checking</span>
              <span className="text-white">{formatCurrency(reconciliation.dsChecking)}</span>
            </div>

            <div className="flex justify-between">
              <span>Discover Credit</span>
              <span className={reconciliation.dsCredit < 0 ? 'text-red-400' : 'text-white'}>
                {reconciliation.dsCredit < 0 ? `(${formatCurrency(Math.abs(reconciliation.dsCredit))})` : formatCurrency(reconciliation.dsCredit)}
              </span>
            </div>

            <div className="flex justify-between">
              <span>Chase Credit</span>
              <span className={reconciliation.visaCredit < 0 ? 'text-red-400' : 'text-white'}>
                {reconciliation.visaCredit < 0 ? `(${formatCurrency(Math.abs(reconciliation.visaCredit))})` : formatCurrency(reconciliation.visaCredit)}
              </span>
            </div>

            <div className="pt-2 border-t border-slate-800 flex justify-between text-blue-400">
              <span>Debit Balance</span>
              <span>{formatCurrency(reconciliation.debitBalance)}</span>
            </div>

            <div className="flex justify-between text-red-400">
              <span>Credit Balance</span>
              <span>({formatCurrency(Math.abs(reconciliation.creditBalance))})</span>
            </div>

            <div className="pt-2 border-t border-slate-800 flex justify-between text-white text-sm font-black">
              <span>Net</span>
              <span>{formatCurrency(reconciliation.net)}</span>
            </div>

            <div className="flex justify-between text-slate-500">
              <span>Allocated (Total Budget)</span>
              <span>-{formatCurrency(reconciliation.totalAllocated)}</span>
            </div>

            <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
              <div>
                <span className="text-[9px] text-slate-500 block mb-1">Difference (Update Budget)</span>
                <span className={`text-2xl font-black ${Math.abs(reconciliation.difference) < 0.01 ? 'text-green-400' : 'text-blue-500'}`}>
                  {formatCurrency(reconciliation.difference)}
                </span>
              </div>
              <AlertCircle size={28} className={Math.abs(reconciliation.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
            </div>
          </div>
        </div>
      </div>

      {showAddCat && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-6 transform transition-all scale-100">
            <h4 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><Plus size={20} className="text-blue-500" /> Define New Category</h4>
            <form onSubmit={handleAddCat} className="space-y-5">
              <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Name</label><input type="text" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" value={newCat.name} onChange={e => setNewCat({...newCat, name: e.target.value})} placeholder="e.g. New Project" required /></div>
              <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Group</label><select className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" value={newCat.className} onChange={e => setNewCat({...newCat, className: e.target.value})} required><option value="">Select Classification...</option>{state.classifications.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}<option value="NEW">Add New Classification</option></select>{newCat.className === 'NEW' && <input type="text" className="w-full px-4 py-2 mt-2 bg-slate-50 border border-slate-200 rounded-lg" placeholder="Classification Name" onChange={e => setNewCat({...newCat, className: e.target.value})} />}</div>
              <div className="flex gap-2 justify-end pt-4"><button type="button" onClick={() => setShowAddCat(false)} className="px-6 py-2 text-sm font-bold text-slate-400">Cancel</button><button type="submit" className="px-8 py-2 bg-slate-900 text-white rounded-lg text-sm font-bold shadow-xl">Save</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { AppState } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { CheckCircle, Circle, Trash2 } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ state, onToggleCleared, onDeleteTransaction }) => {
  const targetAccountIds = [
    'acc-ds-8193', 
    'acc-visa-4914', 
    'acc-ds-6521', 
    'acc-cap-checking', 
    'internal', 
    'internal-deposit', 
    'internal-transfers'
  ];
  const [activeAccId, setActiveAccId] = useState(targetAccountIds[0]); 

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-deposit': { name: 'Deposit', types: ['Income'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal');
  const activeAccount = isVirtual 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'internal') return t.type === 'Update Budget (Allocation)';
      if (activeAccId === 'internal-deposit') return t.type === 'Income';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const handleDelete = (txId: string) => {
    if (window.confirm("Are you sure you want to delete this transaction? This will reverse its financial impact across all ledgers.")) {
      onDeleteTransaction(txId);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-4 items-center pb-2">
        <div className="flex gap-2 overflow-x-auto custom-scrollbar no-scrollbar">
          {targetAccountIds.slice(0, 4).map(id => {
            const name = state.accounts.find(a => a.id === id)?.name;
            if (!name) return null;
            return (
              <button
                key={id}
                onClick={() => setActiveAccId(id)}
                className={`px-5 py-2 rounded-full text-[10px] font-bold transition-all whitespace-nowrap uppercase tracking-widest border border-slate-200 ${
                  activeAccId === id 
                    ? 'bg-slate-900 text-white shadow-lg border-slate-900' 
                    : 'bg-white text-slate-400 hover:border-slate-300'
                }`}
              >
                {name}
              </button>
            );
          })}
        </div>

        <div className="flex gap-6 items-center px-4 ml-2">
          {targetAccountIds.slice(4).map(id => {
            const name = virtualAccountMap[id]?.name;
            if (!name) return null;
            const isActive = activeAccId === id;
            return (
              <button
                key={id}
                onClick={() => setActiveAccId(id)}
                className={`text-[10px] font-black uppercase tracking-widest transition-all ${
                  isActive 
                    ? 'bg-slate-900 text-white px-5 py-2 rounded-full shadow-lg' 
                    : 'text-slate-400 hover:text-slate-900 px-2'
                }`}
              >
                {name}
              </button>
            );
          })}
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {isVirtual ? `Internal Budget ${activeAccount?.name}s` : `${activeAccount?.name} Activity`}
          </h3>
          {!isVirtual && (
            <div className="text-sm font-bold text-slate-900">
              Total Balance: {formatCurrency(activeAccount?.balance || 0)}
            </div>
          )}
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Category</th>
                <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Date</th>
                <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter text-right">Amount</th>
                <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Description</th>
                <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter text-center">Cleared</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map(tx => {
                  const cat = state.categories.find(c => c.id === tx.categoryId);
                  const isCredit = activeAccount?.type === 'Credit';
                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-6 py-3 text-slate-600 font-medium">
                        {cat?.name || 'Uncategorized'}
                        {cat?.deleted && <span className="ml-2 text-[8px] bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded uppercase font-black">Archived</span>}
                      </td>
                      <td className="px-4 py-3 text-slate-400">{formatDisplayDate(tx.date)}</td>
                      <td className={`px-4 py-3 text-right font-bold ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                        {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                      </td>
                      <td className="px-6 py-3 text-slate-600">{tx.description}</td>
                      <td className="px-6 py-3 text-center">
                        <button 
                          onClick={() => onToggleCleared(tx.id)}
                          disabled={!isCredit || isVirtual}
                          className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                            (!isCredit || isVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                            tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                          }`}
                        >
                          {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                        </button>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button 
                          onClick={() => handleDelete(tx.id)}
                          className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-bold">No transactions found for this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AccountLedgers;

import React, { useState, useMemo, useEffect } from 'react';
import { AppState, Transaction, Classification } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';

interface LedgersProps {
  state: AppState;
}

const Ledgers: React.FC<LedgersProps> = ({ state }) => {
  const [activeClassId, setActiveClassId] = useState(state.classifications[0]?.id);
  const [activeCategoryId, setActiveCategoryId] = useState<string | null>(null);

  const activeClass = useMemo(() => {
    return state.classifications.find(c => c.id === activeClassId);
  }, [state.classifications, activeClassId]);

  const categoriesInClass = useMemo(() => {
    return state.categories.filter(c => c.classificationId === activeClassId);
  }, [state.categories, activeClassId]);

  // Sync active category when class changes
  useEffect(() => {
    if (categoriesInClass.length > 0) {
      setActiveCategoryId(categoriesInClass[0].id);
    } else {
      setActiveCategoryId(null);
    }
  }, [categoriesInClass]);

  const activeCategory = useMemo(() => {
    return state.categories.find(c => c.id === activeCategoryId);
  }, [state.categories, activeCategoryId]);

  const filteredTransactions = useMemo(() => {
    if (!activeCategoryId) return [];
    return state.transactions
      .filter(tx => tx.categoryId === activeCategoryId)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [state.transactions, activeCategoryId]);

  return (
    <div className="space-y-6">
      {/* Classification Tabs (Top Tier) */}
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar no-scrollbar border-b border-slate-200">
        {state.classifications.map(cls => (
          <button
            key={cls.id}
            onClick={() => setActiveClassId(cls.id)}
            className={`px-6 py-2 rounded-t-lg text-[11px] font-bold transition-all whitespace-nowrap uppercase tracking-widest border-t border-l border-r ${
              activeClassId === cls.id 
                ? `${cls.color} text-slate-800 border-slate-300 -mb-[1px]` 
                : 'bg-slate-50 text-slate-400 border-transparent hover:bg-slate-100'
            }`}
          >
            {cls.name}
          </button>
        ))}
      </div>

      {/* Category Toggles (Second Tier) */}
      {categoriesInClass.length > 0 && (
        <div className="flex flex-wrap gap-3 py-2">
          {categoriesInClass.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveCategoryId(cat.id)}
              className={`px-5 py-1.5 rounded-md text-[11px] font-black transition-all uppercase tracking-wider border-2 ${
                activeCategoryId === cat.id
                  ? `${activeClass?.color || 'bg-blue-50'} border-slate-400 text-slate-900 shadow-sm`
                  : 'bg-white border-slate-200 text-slate-400 hover:border-slate-300 hover:text-slate-600'
              }`}
            >
              {cat.name}
              {cat.deleted && <span className="ml-2 text-[8px] opacity-40">(Archived)</span>}
            </button>
          ))}
        </div>
      )}

      {/* Single Ledger Display */}
      {activeCategory ? (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className={`px-6 py-4 ${activeClass?.color || 'bg-slate-50'} border-b border-slate-200 flex justify-between items-center`}>
            <div className="flex items-center gap-3">
              <div className="w-2.5 h-2.5 rounded-full bg-slate-800 shadow-sm opacity-50"></div>
              <h3 className="font-black text-slate-800 tracking-tight uppercase text-xs">
                {activeCategory.name}
                {activeCategory.deleted && <span className="ml-2 text-[10px] bg-slate-900 text-white px-2 py-0.5 rounded">Historical View Only</span>}
              </h3>
            </div>
            <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
              Current Balance: <span className={`text-sm ml-2 ${activeCategory.balance < 0 ? 'text-red-600 font-black' : 'text-slate-900 font-black'}`}>
                {formatCurrency(activeCategory.balance)}
              </span>
            </div>
          </div>

          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left text-xs border-collapse">
              <thead className="bg-white border-b border-slate-100">
                <tr>
                  <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-tighter w-32">Date</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-tighter w-48">Account</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-tighter text-right w-32">Amount</th>
                  <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-tighter">Description</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredTransactions.length > 0 ? (
                  filteredTransactions.map(tx => {
                    const account = state.accounts.find(a => a.id === tx.accountId);
                    return (
                      <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                        <td className="px-6 py-3.5 text-slate-500 font-medium">
                          {formatDisplayDate(tx.date)}
                        </td>
                        <td className="px-4 py-3.5 text-slate-600 font-semibold uppercase text-[10px] tracking-tight">
                          {account?.name || (tx.accountId === 'internal' ? 'Internal Allocation' : 'N/A')}
                        </td>
                        <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                          {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                        </td>
                        <td className="px-6 py-3.5 text-slate-600 group-hover:text-slate-900 transition-colors">
                          {tx.description}
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={4} className="px-6 py-16 text-center text-slate-300 italic text-[11px] uppercase tracking-widest">
                      No historical transactions found for {activeCategory.name}.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-xl border-2 border-dashed border-slate-200 p-12 text-center">
          <p className="text-slate-400 uppercase text-[10px] font-bold tracking-widest italic">Select a category to view ledger</p>
        </div>
      )}
    </div>
  );
};

export default Ledgers;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, parseLocalDate } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  // Range: Dec 2025 to Dec 2026 (13 months)
  const months = useMemo(() => {
    const res = [];
    const startDate = new Date(2025, 11, 1); // December 2025
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number }>> = {};
    state.categories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent };
      });
    });
    return data;
  }, [state.categories, state.transactions, months]);

  const renderSection = (title: string, catList: any[], field: 'added' | 'spent' | 'net', colorClass: string, showCheckingTotal = false) => {
    return (
      <div className="bg-white rounded border border-slate-300 shadow-sm overflow-hidden mb-8">
        <div className={`px-4 py-2 ${colorClass} border-b border-slate-300 flex items-center justify-between`}>
          <h3 className="font-bold text-slate-800 uppercase text-[11px] tracking-widest">{title}</h3>
          <span className="text-[10px] font-bold text-slate-400">DEC '25 - DEC '26</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase border-collapse">
            <thead className="bg-slate-50 border-b border-slate-300">
              <tr>
                <th className="px-4 py-2 text-slate-500 font-bold border-r border-slate-200 sticky left-0 bg-slate-50 z-20">Category</th>
                {months.map((m, i) => {
                  const d = parseLocalDate(m + "-01");
                  const label = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
                  return (
                    <th key={i} className="px-2 py-2 text-slate-500 font-bold text-right border-r border-slate-200 last:border-r-0">
                      {label}
                    </th>
                  );
                })}
                <th className="px-4 py-2 text-slate-900 font-bold text-right bg-slate-100 border-l border-slate-300">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {catList.map(cat => {
                let rowTotal = 0;
                return (
                  <tr key={cat.id} className="hover:bg-slate-50 group h-7">
                    <td className="px-4 py-1 text-slate-700 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">
                      {cat.name}
                      {cat.deleted && <span className="ml-1 opacity-40 lowercase">(arc)</span>}
                    </td>
                    {months.map(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      let val = 0;
                      if (field === 'added') val = stats.added;
                      else if (field === 'spent') val = stats.spent;
                      else val = stats.added + stats.spent;

                      rowTotal += val;
                      const displayVal = Math.round(Math.abs(val));
                      const isNegative = val < 0;

                      return (
                        <td key={m} className={`px-2 py-1 text-right border-r border-slate-200 last:border-r-0 ${val === 0 ? 'text-slate-200' : isNegative ? 'text-red-500' : 'text-slate-700'}`}>
                          {val === 0 ? '-' : (isNegative ? `(${displayVal.toLocaleString()})` : displayVal.toLocaleString())}
                        </td>
                      );
                    })}
                    <td className="px-4 py-1 text-right font-bold bg-slate-50 text-slate-900 border-l border-slate-300">
                      {Math.round(Math.abs(rowTotal)).toLocaleString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-slate-900 text-white font-bold h-8">
              <tr>
                <td className="px-4 py-1 uppercase tracking-widest text-[9px] sticky left-0 bg-slate-900">{showCheckingTotal ? "Checking Total" : "Total"}</td>
                {months.map(m => {
                  let monthTotal = 0;
                  catList.forEach(cat => {
                    const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                    if (field === 'added') monthTotal += stats.added;
                    else if (field === 'spent') monthTotal += stats.spent;
                    else monthTotal += (stats.added + stats.spent);
                  });
                  return <td key={m} className="px-2 py-1 text-right border-r border-slate-700 last:border-r-0">{Math.round(Math.abs(monthTotal)).toLocaleString()}</td>;
                })}
                <td className="px-4 py-1 text-right bg-slate-800">
                  {Math.round(Math.abs(catList.reduce((acc, cat) => {
                    let catSum = 0;
                    months.forEach(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0 };
                      if (field === 'added') catSum += stats.added;
                      else if (field === 'spent') catSum += stats.spent;
                      else catSum += (stats.added + stats.spent);
                    });
                    return acc + catSum;
                  }, 0))).toLocaleString()}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    );
  };

  const incomeCategories = state.categories.filter(c => c.classificationId === 'class-income');
  const expenseCategories = state.categories.filter(c => !['class-income', 'class-savings'].includes(c.classificationId));
  const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');

  const resourceTotals = months.map(m => incomeCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0));
  const expenseTotalFlow = months.map(m => expenseCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.spent || 0), 0));

  return (
    <div className="space-y-6 pb-24">
      {/* 1. Income Summary */}
      {renderSection("Income Summary", incomeCategories, 'added', 'bg-cyan-50')}

      {/* 2. Expenses Summary */}
      {renderSection("Expenses Summary", expenseCategories, 'spent', 'bg-red-50')}

      {/* 3. Money Added Summary */}
      {renderSection("Money Added Summary", expenseCategories, 'added', 'bg-blue-50', true)}

      {/* 4. Activity Summary */}
      {renderSection("Summary Activity (Net)", expenseCategories, 'net', 'bg-slate-50')}

      {/* 5. Savings Summary - Stacked Full Width */}
      <div className="space-y-2">
        {renderSection("Savings Expenses", savingsCategories, 'spent', 'bg-emerald-50')}
        {renderSection("Savings Additions", savingsCategories, 'added', 'bg-emerald-50')}
      </div>

      {/* 6. Resources vs Expenses Comparison */}
      <div className="bg-slate-900 rounded border border-slate-700 shadow-2xl overflow-hidden mt-12">
        <div className="px-4 py-3 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
          <h3 className="font-black text-white uppercase text-[12px] tracking-widest">Resources vs Expenses Analysis</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter text-slate-300 border-collapse">
            <thead className="border-b border-slate-800 bg-slate-800/50">
              <tr>
                <th className="px-6 py-3 font-bold sticky left-0 bg-slate-800 z-10 border-r border-slate-700">Metric</th>
                {months.map((m, i) => {
                   const d = parseLocalDate(m + "-01");
                   return <th key={i} className="px-3 py-3 text-right border-r border-slate-700 last:border-r-0">{d.toLocaleDateString('en-US', {month: 'short', year:'2-digit'})}</th>;
                })}
                <th className="px-6 py-3 text-right bg-slate-800 border-l border-slate-700">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 font-bold">
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-cyan-400 border-r border-slate-800">Resources (Income)</td>
                {resourceTotals.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">{Math.round(val).toLocaleString()}</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-cyan-400 border-l border-slate-700">{Math.round(resourceTotals.reduce((a,b)=>a+b, 0)).toLocaleString()}</td>
              </tr>
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-red-400 border-r border-slate-800">Expenses (Total Spend)</td>
                {expenseTotalFlow.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">({Math.round(Math.abs(val)).toLocaleString()})</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-red-400 border-l border-slate-700">({Math.round(Math.abs(expenseTotalFlow.reduce((a,b)=>a+b, 0))).toLocaleString()})</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm h-14">
                <td className="px-6 py-4 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest border-r border-slate-800 shadow-[4px_0_10px_rgba(0,0,0,0.2)]">Net Cash Flow</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotalFlow[i];
                  return <td key={i} className={`px-3 py-4 text-right border-r border-slate-800 last:border-r-0 ${net < 0 ? 'text-red-500 font-black' : 'text-green-400 font-black'}`}>{Math.round(net).toLocaleString()}</td>
                })}
                <td className="px-6 py-4 text-right font-black bg-blue-600 shadow-[-4px_0_10px_rgba(0,0,0,0.2)]">
                  {Math.round(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotalFlow.reduce((a,b)=>a+b, 0)).toLocaleString()}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
