                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-red-400 border-r border-slate-800">Expenses (Total Spend)</td>
                {expenseTotalFlow.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">{formatCurrency(val, true)}</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-red-400 border-l border-slate-700">{formatCurrency(expenseTotalFlow.reduce((a,b)=>a+b, 0), true)}</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm h-14">
                <td className="px-6 py-4 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest border-r border-slate-800 shadow-[4px_0_10px_rgba(0,0,0,0.2)]">Net Cash Flow</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotalFlow[i];
                  return <td key={i} className={`px-3 py-4 text-right border-r border-slate-800 last:border-r-0 ${net < 0 ? 'text-red-500 font-black' : 'text-green-400 font-black'}`}>{formatCurrency(net, true)}</td>
                })}
                <td className="px-6 py-4 text-right font-black bg-blue-600 shadow-[-4px_0_10px_rgba(0,0,0,0.2)]">
                  {formatCurrency(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotalFlow.reduce((a,b)=>a+b, 0), true)}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* 4. Money Added Summary - Re-positioned below analysis */}
      {renderSection("Money Added Summary", expenseCategories, 'added', 'bg-blue-50', true)}

      {/* 5. Activity Summary - Re-positioned below analysis */}
      {renderSection("Summary Activity (Net)", expenseCategories, 'net', 'bg-slate-50')}

      {/* 6. Savings Breakdown */}
      <div className="space-y-2">
        {renderSection("Savings Expenses", savingsCategories, 'spent', 'bg-emerald-50')}
        {renderSection("Savings Additions", savingsCategories, 'added', 'bg-emerald-50')}
      </div>

      {/* 7. Ending Savings Balance Table - Calculated running balances */}
      <div className="bg-white rounded border border-slate-300 shadow-sm overflow-hidden mb-8">
        <div className="px-4 py-2 bg-slate-900 text-white border-b border-slate-300 flex items-center justify-between">
          <h3 className="font-bold uppercase text-[11px] tracking-widest">Ending Savings Balance</h3>
          <span className="text-[10px] font-bold opacity-50">MONTH-OVER-MONTH BALANCE</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase border-collapse">
            <thead className="bg-slate-50 border-b border-slate-300">
              <tr>
                <th className="px-4 py-2 text-slate-500 font-bold border-r border-slate-200 sticky left-0 bg-slate-50 z-20">Category</th>
                {months.map((m, i) => {
                  const label = parseLocalDate(m + "-01").toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
                  return <th key={i} className="px-2 py-2 text-slate-500 font-bold text-right border-r border-slate-200 last:border-r-0">{label}</th>;
                })}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {savingsCategories.map(cat => {
                // Logic: Current Balance - Sum of all transactions occurring AFTER the target month
                const afterCurrentMonthTxSum = (monthKey: string) => {
                   const limit = parseLocalDate(monthKey + "-01");
                   limit.setMonth(limit.getMonth() + 1); // Point to start of NEXT month
                   return state.transactions
                    .filter(t => t.categoryId === cat.id && parseLocalDate(t.date) >= limit)
                    .reduce((sum, t) => sum + t.amount, 0);
                };

                return (
                  <tr key={cat.id} className="hover:bg-slate-50 h-7 group">
                    <td className="px-4 py-1 text-slate-700 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">
                      {cat.name}
                    </td>
                    {months.map(m => {
                      const balanceAtEnd = cat.balance - afterCurrentMonthTxSum(m);
                      return (
                        <td key={m} className={`px-2 py-1 text-right border-r border-slate-200 last:border-r-0 ${balanceAtEnd < 0 ? 'text-red-500' : 'text-slate-700'}`}>
                          {formatCurrency(balanceAtEnd, true)}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-emerald-900 text-white font-bold h-10">
              <tr>
                <td className="px-4 py-1 uppercase tracking-widest text-[9px] sticky left-0 bg-emerald-900">Total Savings Portfolio</td>
                {months.map(m => {
                  const totalAtEnd = savingsCategories.reduce((acc, cat) => {
                    const limit = parseLocalDate(m + "-01");
                    limit.setMonth(limit.getMonth() + 1);
                    const sumAfter = state.transactions
                      .filter(t => t.categoryId === cat.id && parseLocalDate(t.date) >= limit)
                      .reduce((s, t) => s + t.amount, 0);
                    return acc + (cat.balance - sumAfter);
                  }, 0);
                  return <td key={m} className="px-2 py-1 text-right border-r border-emerald-800 last:border-r-0">{formatCurrency(totalAtEnd, true)}</td>;
                })}
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Summary;

import React, { useState } from 'react';
import { Calendar, DollarSign, Tag, Landmark, FileText, ArrowRightLeft } from 'lucide-react';
import { AppState, TransactionType, Category } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ state, onAddTransaction, onExecuteTransfer }) => {
  const [activeMode, setActiveMode] = useState<'transact' | 'transfer' | 'budget'>('transact');
  const [formData, setFormData] = useState({
    categoryId: '',
    date: new Date().toISOString().split('T')[0],
    accountId: '',
    amount: '',
    description: '',
    type: 'Standard' as TransactionType,
    toCategoryId: '',
    toAccountId: '',
    fromCategoryId: '',
    fromAccountId: '',
    transferType: TRANSFER_TYPES[1] // Default to Category Transfer
  });

  const activeCategories = state.categories.filter(c => !c.deleted);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const amountNum = parseFloat(formData.amount);
    if (isNaN(amountNum) || amountNum <= 0) return;

    if (activeMode === 'transact') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: formData.type === 'Income' ? amountNum : -amountNum,
        description: formData.description,
        type: formData.type,
      });
    } else if (activeMode === 'budget') {
      onAddTransaction({
        categoryId: formData.toCategoryId,
        date: formData.date,
        accountId: 'internal',
        amount: amountNum,
        description: formData.description || 'Budget Allocation',
        type: 'Update Budget (Allocation)' as any,
      });
    } else {
      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: amountNum,
        description: formData.description,
        fromAccountId: formData.fromAccountId,
        toAccountId: formData.toAccountId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }
    setFormData(prev => ({ ...prev, amount: '', description: '' }));
  };

  const inputStyles = "w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:outline-none transition-all";
  const labelStyles = "block text-[10px] font-bold text-slate-400 uppercase mb-1.5";

  const virtualAccounts = [
    { id: 'internal', name: 'Allocation' },
    { id: 'internal-deposit', name: 'Deposit' },
    { id: 'internal-transfers', name: 'Transfers' }
  ];

  const showFromAccount = ['Category Transfer', 'Transfer to Savings', 'Credit Payment', 'Transfer between Checking'].includes(formData.transferType);
  const showToAccount = ['Category Transfer', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(formData.transferType);
  const showFromCategory = ['Category Transfer', 'Transfer to Checking'].includes(formData.transferType);
  const showToCategory = ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking'].includes(formData.transferType);

  const renderCategoryOptions = () => {
    return (
      <>
        <option value="">Select Category</option>
        {state.classifications.map(cls => {
          const catsInClass = activeCategories.filter(cat => cat.classificationId === cls.id);
          if (catsInClass.length === 0) return null;
          return (
            <optgroup key={cls.id} label={cls.name}>
              {catsInClass.map(cat => (
                <option key={cat.id} value={cat.id}>{cat.name}</option>
              ))}
            </optgroup>
          );
        })}
      </>
    );
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        <button onClick={() => setActiveMode('transact')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-colors ${activeMode === 'transact' ? 'bg-white text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transact</button>
        <button onClick={() => setActiveMode('budget')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-colors ${activeMode === 'budget' ? 'bg-white text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Allocation</button>
        <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-colors ${activeMode === 'transfer' ? 'bg-white text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transfer</button>
      </div>

      <form onSubmit={handleSubmit} className="p-5 space-y-4">
        {activeMode === 'budget' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
              <p className="text-[10px] text-blue-600 font-bold uppercase tracking-wider mb-1">Budget Allocation</p>
              <p className="text-[11px] text-blue-400 leading-tight">Increases category balance from internal funds (no bank impact).</p>
            </div>
            <div>
              <label className={labelStyles}>To Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions()}
                </select>
              </div>
            </div>
          </div>
        ) : activeMode === 'transact' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
             <div>
              <label className={labelStyles}>Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions()}
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>Account / Source</label>
              <div className="relative">
                <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Account</option>
                  <optgroup label="Bank Accounts">
                    {state.accounts.filter(a => ['Checking', 'Credit', 'Savings'].includes(a.type)).map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </optgroup>
                  <optgroup label="Internal Ledgers">
                    {virtualAccounts.map(vacc => (
                      <option key={vacc.id} value={vacc.id}>{vacc.name}</option>
                    ))}
                  </optgroup>
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>Transaction Type</label>
              <select 
                value={formData.type} 
                onChange={e => setFormData({...formData, type: e.target.value as any})} 
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold uppercase tracking-wider text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              >
                <option value="Standard">Expense (Withdrawal)</option>
                <option value="Income">Income (Deposit)</option>
              </select>
            </div>
          </div>
        ) : (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div>
              <label className={labelStyles}>Transfer Type</label>
              <div className="relative">
                <ArrowRightLeft className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select 
                  value={formData.transferType} 
                  onChange={e => setFormData({...formData, transferType: e.target.value as any})} 
                  className={inputStyles}
                >
                  {TRANSFER_TYPES.filter(t => t !== 'Update Budget (Allocation)').map(type => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromAccount && (
                <div>
                  <label className={labelStyles}>Account From</label>
                  <select value={formData.fromAccountId} onChange={e => setFormData({...formData, fromAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" required>
                    <option value="">Select From</option>
                    {state.accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </select>
                </div>
              )}
              {showToAccount && (
                <div>
                  <label className={labelStyles}>Account To</label>
                  <select value={formData.toAccountId} onChange={e => setFormData({...formData, toAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" required>
                    <option value="">Select To</option>
                    {state.accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </select>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromCategory && (
                <div>
                  <label className={labelStyles}>Category From</label>
                  <select value={formData.fromCategoryId} onChange={e => setFormData({...formData, fromCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" required>
                    {renderCategoryOptions()}
                  </select>
                </div>
              )}
              {showToCategory && (
                <div>
                  <label className={labelStyles}>Category To</label>
                  <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs" required>
                    {renderCategoryOptions()}
                  </select>
                </div>
              )}
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className={labelStyles}>Amount</label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className={inputStyles} placeholder="0.00" required />
            </div>
          </div>
          <div>
            <label className={labelStyles}>Date</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className={inputStyles} required />
            </div>
          </div>
        </div>

        <div>
          <label className={labelStyles}>Description</label>
          <div className="relative">
            <FileText className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className={inputStyles} placeholder="Transaction details..." />
          </div>
        </div>

        <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-xl text-xs uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-600 transition-all active:scale-95 flex items-center justify-center gap-2">
          {activeMode === 'transact' ? 'Submit Transaction' : activeMode === 'budget' ? 'Allocate Funds' : 'Process Transfer'}
        </button>
      </form>
    </div>
  );
};

export default TransactionPanel;

import React, { useMemo } from 'react';
import { AlertCircle, Undo2 } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  undoLastTransaction: () => void;
  executeTransfer: (transfer: any) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, addTransaction, undoLastTransaction, executeTransfer }) => {
  const currentMonth = getMonthYearKey(new Date());

  const categoryCalculations = useMemo(() => {
    return state.categories
      .filter(cat => !cat.deleted)
      .map(cat => {
        const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
        const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        return { ...cat, monthlyAdded: added, monthlySpent: spent };
      });
  }, [state.categories, state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const reconciliation = useMemo(() => {
    const capOne = state.accounts.find(a => a.id === 'acc-cap-checking')?.balance || 0;
    const dsChecking = state.accounts.find(a => a.id === 'acc-ds-6521')?.balance || 0;
    const dsCredit = state.accounts.find(a => a.id === 'acc-ds-8193')?.balance || 0;
    const visaCredit = state.accounts.find(a => a.id === 'acc-visa-4914')?.balance || 0;

    const debitBalance = capOne + dsChecking;
    const creditBalance = dsCredit + visaCredit;
    const net = debitBalance + creditBalance;

    const budgetCategories = state.categories.filter(c => !['class-income', 'class-savings', 'class-transfers'].includes(c.classificationId));
    const totalAllocated = budgetCategories.reduce((sum, cat) => sum + cat.balance, 0);

    const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');
    const totalSavings = savingsCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      capOne,
      dsChecking,
      dsCredit,
      visaCredit,
      debitBalance,
      creditBalance,
      net,
      totalAllocated,
      totalSavings,
      difference: net - totalAllocated
    };
  }, [state.accounts, state.categories]);

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings', 'class-transfers'].includes(c.id));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <div className="flex items-center gap-4">
               <button 
                  onClick={() => undoLastTransaction()} 
                  className="flex items-center gap-1.5 text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-slate-100"
                >
                  <Undo2 size={12} /> Undo Last
                </button>
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Spent</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => {
                const cats = groupedCategories[cls.id] || [];
                if (cats.length === 0) return null;
                return (
                  <React.Fragment key={cls.id}>
                    <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={5} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                    {cats.map(cat => (
                      <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400">
                        <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                        <td className={`px-4 py-2 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(cat.balance)}</td>
                        <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                        <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                        <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? formatCurrency(cat.monthlySpent) : '-'}</td>
                      </tr>
                    ))}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="lg:block">
        <div className="sticky top-8 space-y-6">
          <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />

          <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
            <h3 className="text-[10px] text-slate-500 mb-2">Budget Reconciliation</h3>

            <div className="space-y-3">
              <div className="flex justify-between">
                <span>Capital One Checking</span>
                <span className="text-white">{formatCurrency(reconciliation.capOne)}</span>
              </div>

              <div className="flex justify-between">
                <span>Discover Checking</span>
                <span className="text-white">{formatCurrency(reconciliation.dsChecking)}</span>
              </div>

              <div className="flex justify-between">
                <span>Discover Credit</span>
                <span className={reconciliation.dsCredit < 0 ? 'text-red-400' : 'text-white'}>
                  {formatCurrency(reconciliation.dsCredit)}
                </span>
              </div>

              <div className="flex justify-between">
                <span>Chase Credit</span>
                <span className={reconciliation.visaCredit < 0 ? 'text-red-400' : 'text-white'}>
                  {formatCurrency(reconciliation.visaCredit)}
                </span>
              </div>

              <div className="pt-2 border-t border-slate-800 flex justify-between text-blue-400">
                <span>Debit Balance</span>
                <span>{formatCurrency(reconciliation.debitBalance)}</span>
              </div>

              <div className="flex justify-between text-red-400">
                <span>Credit Balance</span>
                <span>{formatCurrency(reconciliation.creditBalance)}</span>
              </div>

              <div className="pt-2 border-t border-slate-800 flex justify-between text-white text-sm font-black">
                <span>Net</span>
                <span>{formatCurrency(reconciliation.net)}</span>
              </div>

              <div className="flex justify-between text-slate-500">
                <span>Allocated (Total Budget)</span>
                <span>{formatCurrency(-reconciliation.totalAllocated)}</span>
              </div>

              <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                <div>
                  <span className="text-[9px] text-slate-500 block mb-1">Difference (Update Budget)</span>
                  <span className={`text-2xl font-black ${Math.abs(reconciliation.difference) < 0.01 ? 'text-green-400' : 'text-blue-500'}`}>
                    {formatCurrency(reconciliation.difference)}
                  </span>
                </div>
                <AlertCircle size={28} className={Math.abs(reconciliation.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
              </div>

              <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                <span className="text-[11px] font-black text-white uppercase tracking-widest">Total Savings</span>
                <span className="text-sm font-black text-emerald-400">{formatCurrency(reconciliation.totalSavings)}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import { Target, TrendingUp, TrendingDown, Plus, Trash2 } from 'lucide-react';

interface BudgetManagerProps {
  state: AppState;
  onUpdateBudget: (id: string, val: number) => void;
  onUpdateEstIncome: (val: number) => void;
  onAddCategory: (name: string, className: string, color: string) => void;
  onDeleteCategory: (id: string) => void;
}

const BudgetManager: React.FC<BudgetManagerProps> = ({ 
  state, 
  onUpdateBudget, 
  onUpdateEstIncome, 
  onAddCategory, 
  onDeleteCategory 
}) => {
  const currentMonth = getMonthYearKey(new Date());
  const [showAddCat, setShowAddCat] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });

  const budgetStats = state.categories
    .filter(cat => !cat.deleted && cat.id !== 'cat-credit-payment' && cat.name !== 'Credit Payment')
    .map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, added, spent };
    });

  const filteredClassifications = state.classifications.filter(cls => !['class-income', 'class-transfers'].includes(cls.id));

  const totalBudgeted = state.categories
    .filter(c => !c.deleted && !['class-income', 'class-transfers'].includes(c.classificationId))
    .reduce((sum, c) => sum + c.monthlyBudget, 0);

  const diff = state.estimatedMonthlyIncome - totalBudgeted;

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      onAddCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const handleDelete = (id: string, name: string) => {
    if (window.confirm(`Are you sure you want to delete the category "${name}"? It will be hidden from statements and transaction forms, but its history will be kept.`)) {
      onDeleteCategory(id);
    }
  };

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-100 text-blue-600 rounded-lg"><Target size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Est. Monthly Income</p>
            <input 
              type="number" 
              className="text-xl font-bold text-slate-800 bg-transparent focus:outline-none w-full"
              value={state.estimatedMonthlyIncome}
              onChange={e => onUpdateEstIncome(parseFloat(e.target.value) || 0)}
            />
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-green-100 text-green-600 rounded-lg"><TrendingUp size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total Budgeted</p>
            <p className="text-xl font-bold text-slate-800">{formatCurrency(totalBudgeted, true)}</p>
          </div>
        </div>
        <div className={`bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4 border-l-4 ${diff < 0 ? 'border-l-red-500' : 'border-l-green-500'}`}>
          <div className={`p-3 rounded-lg ${diff < 0 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}><TrendingDown size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Remaining to Allocate</p>
            <p className={`text-xl font-bold ${diff < 0 ? 'text-red-500' : 'text-slate-800'}`}>{formatCurrency(diff, true)}</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">Manage Categories</h3>
          <button 
            onClick={() => setShowAddCat(true)} 
            className="flex items-center gap-1.5 text-blue-600 hover:text-blue-700 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-blue-50"
          >
            <Plus size={12} /> Add Category
          </button>
        </div>
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest">Category</th>
              <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Target Budget</th>
              <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Added (CM)</th>
              <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Spent (CM)</th>
              <th className="px-4 py-4"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredClassifications.map(cls => (
              <React.Fragment key={cls.id}>
                <tr className={`${cls.color} font-bold`}>
                  <td colSpan={5} className="px-6 py-2 text-[9px] uppercase tracking-widest text-slate-600">{cls.name}</td>
                </tr>
                {budgetStats.filter(c => c.classificationId === cls.id).map(cat => (
                  <tr key={cat.id} className="hover:bg-slate-50/50 group">
                    <td className="px-6 py-3 font-medium text-slate-700">{cat.name}</td>
                    <td className="px-4 py-3 text-right">
                      <input 
                        type="number" 
                        className="w-24 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-right font-bold text-slate-900 focus:outline-none focus:ring-1 focus:ring-blue-500"
                        value={cat.monthlyBudget}
                        onChange={e => onUpdateBudget(cat.id, parseFloat(e.target.value) || 0)}
                      />
                    </td>
                    <td className="px-4 py-3 text-right text-blue-500 font-bold">{formatCurrency(cat.added, true)}</td>
                    <td className={`px-4 py-3 text-right font-bold ${cat.spent < 0 ? 'text-red-500' : 'text-slate-500'}`}>
                      {cat.spent === 0 ? '-' : formatCurrency(cat.spent, true)}
                    </td>
                    <td className="px-4 py-3 text-right">
                      <button 
                        onClick={() => handleDelete(cat.id, cat.name)}
                        className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-red-50"
                      >
                        <Trash2 size={14} />
                      </button>
                    </td>
                  </tr>
                ))}
              </React.Fragment>
            ))}
          </tbody>
          <tfoot className="bg-slate-900 text-white font-bold">
            <tr>
              <td className="px-6 py-4 uppercase tracking-widest text-xs">Total Monthly Targets</td>
              <td className="px-4 py-4 text-right text-lg">{formatCurrency(totalBudgeted, true)}</td>
              <td colSpan={3}></td>
            </tr>
          </tfoot>
        </table>
      </div>

      {showAddCat && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-6 transform transition-all scale-100">
            <h4 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><Plus size={20} className="text-blue-500" /> Define New Category</h4>
            <form onSubmit={handleAddCat} className="space-y-5">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Name</label>
                <input type="text" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:outline-none" value={newCat.name} onChange={e => setNewCat({...newCat, name: e.target.value})} placeholder="e.g. Vacation Fund" required />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Group</label>
                <select className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:outline-none" value={newCat.className} onChange={e => setNewCat({...newCat, className: e.target.value})} required>
                  <option value="">Select Classification...</option>
                  {state.classifications.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                  <option value="NEW">Add New Classification</option>
                </select>
                {newCat.className === 'NEW' && (
                  <input type="text" className="w-full px-4 py-2 mt-2 bg-slate-50 border border-slate-200 rounded-lg" placeholder="Classification Name" onChange={e => setNewCat({...newCat, className: e.target.value})} />
                )}
              </div>
              <div className="flex gap-2 justify-end pt-4">
                <button type="button" onClick={() => setShowAddCat(false)} className="px-6 py-2 text-sm font-bold text-slate-400 hover:text-slate-600 transition-colors">Cancel</button>
                <button type="submit" className="px-8 py-2 bg-slate-900 text-white rounded-lg text-sm font-bold shadow-xl hover:bg-blue-600 transition-all">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default BudgetManager;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot 
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction}
            executeTransfer={executeTransfer} 
          />
        );
      case 'acc-ledgers':
        return (
          <AccountLedgers 
            state={state} 
            onToggleCleared={toggleCleared} 
            onDeleteTransaction={deleteTransaction}
          />
        );
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return <NetWorth state={state} onAddSnapshot={addInvestmentSnapshot} />;
      default:
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction} 
            executeTransfer={executeTransfer} 
          />
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { Calendar, DollarSign, Tag, Landmark, FileText, ArrowRightLeft } from 'lucide-react';
import { AppState, TransactionType } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ state, onAddTransaction, onExecuteTransfer }) => {
  const [activeMode, setActiveMode] = useState<'transact' | 'transfer' | 'budget'>('transact');
  const [formData, setFormData] = useState({
    categoryId: '',
    date: new Date().toISOString().split('T')[0],
    accountId: '',
    amount: '',
    description: '',
    type: 'Standard' as TransactionType,
    toCategoryId: '',
    toAccountId: '',
    fromCategoryId: '',
    fromAccountId: '',
    transferType: TRANSFER_TYPES[1] // Default to Category Transfer
  });

  const activeCategories = state.categories.filter(c => !c.deleted);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const amountNum = parseFloat(formData.amount);
    if (isNaN(amountNum) || amountNum <= 0) return;

    if (activeMode === 'transact') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: formData.type === 'Income' ? amountNum : -amountNum,
        description: formData.description,
        type: formData.type,
      });
    } else if (activeMode === 'budget') {
      onAddTransaction({
        categoryId: formData.toCategoryId,
        date: formData.date,
        accountId: 'internal',
        amount: amountNum,
        description: formData.description || 'Budget Allocation',
        type: 'Update Budget (Allocation)' as any,
      });
    } else {
      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: amountNum,
        description: formData.description,
        fromAccountId: formData.fromAccountId,
        toAccountId: formData.toAccountId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }
    setFormData(prev => ({ ...prev, amount: '', description: '' }));
  };

  const inputStyles = "w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:outline-none transition-all";
  const labelStyles = "block text-[10px] font-bold text-slate-400 uppercase mb-1.5";

  const virtualAccounts = [
    { id: 'internal', name: 'Allocation' },
    { id: 'internal-deposit', name: 'Deposit' },
    { id: 'internal-transfers', name: 'Transfers' }
  ];

  const showFromAccount = ['Category Transfer', 'Transfer to Savings', 'Credit Payment', 'Transfer between Checking'].includes(formData.transferType);
  const showToAccount = ['Category Transfer', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(formData.transferType);
  const showFromCategory = ['Category Transfer', 'Transfer to Checking'].includes(formData.transferType);
  const showToCategory = ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking'].includes(formData.transferType);

  const renderCategoryOptions = (placeholder: string = "Select Category") => {
    return (
      <>
        <option value="">{placeholder}</option>
        {state.classifications.map(cls => {
          const catsInClass = activeCategories.filter(cat => cat.classificationId === cls.id);
          if (catsInClass.length === 0) return null;
          return (
            <optgroup key={cls.id} label={cls.name}>
              {catsInClass.map(cat => (
                <option key={cat.id} value={cat.id}>{cat.name}</option>
              ))}
            </optgroup>
          );
        })}
      </>
    );
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        <button onClick={() => setActiveMode('transact')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-colors ${activeMode === 'transact' ? 'bg-white text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transact</button>
        <button onClick={() => setActiveMode('budget')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-colors ${activeMode === 'budget' ? 'bg-white text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Allocation</button>
        <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-colors ${activeMode === 'transfer' ? 'bg-white text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transfer</button>
      </div>

      <form onSubmit={handleSubmit} className="p-5 space-y-4">
        {activeMode === 'budget' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
              <p className="text-[10px] text-blue-600 font-bold uppercase tracking-wider mb-1">Budget Allocation</p>
              <p className="text-[11px] text-blue-400 leading-tight">Increases category balance from internal funds (no bank impact).</p>
            </div>
            <div>
              <label className={labelStyles}>To Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions("Select To Category")}
                </select>
              </div>
            </div>
          </div>
        ) : activeMode === 'transact' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
             <div>
              <label className={labelStyles}>Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions()}
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>Account / Source</label>
              <div className="relative">
                <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Account</option>
                  <optgroup label="Bank Accounts">
                    {state.accounts.filter(a => ['Checking', 'Credit', 'Savings'].includes(a.type)).map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </optgroup>
                  <optgroup label="Internal Ledgers">
                    {virtualAccounts.map(vacc => (
                      <option key={vacc.id} value={vacc.id}>{vacc.name}</option>
                    ))}
                  </optgroup>
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>Transaction Type</label>
              <select 
                value={formData.type} 
                onChange={e => setFormData({...formData, type: e.target.value as any})} 
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold uppercase tracking-wider text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              >
                <option value="Standard">Expense (Withdrawal)</option>
                <option value="Income">Income (Deposit)</option>
              </select>
            </div>
          </div>
        ) : (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div>
              <label className={labelStyles}>Transfer Type</label>
              <div className="relative">
                <ArrowRightLeft className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select 
                  value={formData.transferType} 
                  onChange={e => setFormData({...formData, transferType: e.target.value as any})} 
                  className={inputStyles}
                >
                  {TRANSFER_TYPES.filter(t => t !== 'Update Budget (Allocation)').map(type => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromAccount && (
                <div>
                  <label className={labelStyles}>Account From</label>
                  <select value={formData.fromAccountId} onChange={e => setFormData({...formData, fromAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    <option value="">From Acc</option>
                    <optgroup label="Accounts">
                      {state.accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </optgroup>
                  </select>
                </div>
              )}
              {showToAccount && (
                <div>
                  <label className={labelStyles}>Account To</label>
                  <select value={formData.toAccountId} onChange={e => setFormData({...formData, toAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    <option value="">To Acc</option>
                    <optgroup label="Accounts">
                      {state.accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </optgroup>
                  </select>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromCategory && (
                <div>
                  <label className={labelStyles}>Category From</label>
                  <select value={formData.fromCategoryId} onChange={e => setFormData({...formData, fromCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    {renderCategoryOptions("From Cat")}
