                  <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    {renderCategoryOptions("To Cat")}
                  </select>
                </div>
              )}
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className={labelStyles}>Amount</label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className={inputStyles} placeholder="0.00" required />
            </div>
          </div>
          <div>
            <label className={labelStyles}>Date</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className={inputStyles} required />
            </div>
          </div>
        </div>

        <div>
          <label className={labelStyles}>Description</label>
          <div className="relative">
            <FileText className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input type="text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className={inputStyles} placeholder="Transaction details..." />
          </div>
        </div>

        <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-xl text-xs uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-600 transition-all active:scale-95 flex items-center justify-center gap-2">
          {activeMode === 'transact' ? 'Submit Transaction' : activeMode === 'budget' ? 'Allocate Funds' : 'Process Transfer'}
        </button>
      </form>
    </div>
  );
};

