import React, { useState } from 'react';
import { Calendar, DollarSign, Tag, Landmark, FileText, ArrowRightLeft, AlertCircle } from 'lucide-react';
import { AppState, TransactionType } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ state, onAddTransaction, onExecuteTransfer }) => {
  const [activeMode, setActiveMode] = useState<'income' | 'expense' | 'allocation' | 'transfer'>('income');
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    categoryId: '',
    date: new Date().toISOString().split('T')[0],
    accountId: '',
    amount: '',
    description: '',
    type: 'Standard' as TransactionType,
    toCategoryId: '',
    toAccountId: '',
    fromCategoryId: '',
    fromAccountId: '',
    transferType: TRANSFER_TYPES[1] // Default to Category Transfer
  });

  const activeCategories = state.categories.filter(c => !c.deleted);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    const amountNum = parseFloat(formData.amount);

    if (isNaN(amountNum) || amountNum <= 0) {
      setError("Please enter a positive amount.");
      return;
    }

    if (activeMode === 'income') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: amountNum,
        description: formData.description,
        type: 'Income',
      });
    } else if (activeMode === 'expense') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: -amountNum,
        description: formData.description,
        type: 'Standard',
      });
    } else if (activeMode === 'allocation') {
      onAddTransaction({
        categoryId: formData.toCategoryId,
        date: formData.date,
        accountId: 'internal',
        amount: amountNum,
        description: formData.description || 'Internal Allocation',
        type: 'Update Budget (Allocation)' as any,
      });
    } else {
      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: amountNum,
        description: formData.description,
        fromAccountId: formData.fromAccountId,
        toAccountId: formData.toAccountId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }

    // Reset fields except date and persistent selections
    setFormData(prev => ({ ...prev, amount: '', description: '', categoryId: '', toCategoryId: '', fromCategoryId: '' }));
  };

  const inputStyles = "w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:outline-none transition-all";
  const labelStyles = "block text-[10px] font-bold text-slate-400 uppercase mb-1.5";

  const virtualAccounts = [
    { id: 'internal', name: 'Allocation' },
    { id: 'internal-deposit', name: 'Deposit' },
    { id: 'internal-transfers', name: 'Transfers' }
  ];

  const showFromAccount = ['Category Transfer', 'Transfer to Savings', 'Credit Payment', 'Transfer between Checking'].includes(formData.transferType);
