  };

  const getFilteredAccounts = (direction: 'from' | 'to') => {
    const accs = state.accounts;
    if (isSavingsPage) {
      if (activeMode === 'expense') return accs.filter(a => a.type === 'Savings');
      return accs.filter(a => a.type === 'Savings' || (direction === 'to' && formData.transferType === 'Transfer to Checking' && a.type === 'Checking'));
    }

    switch (formData.transferType) {
      case 'Transfer to Savings':
        return direction === 'from' ? accs.filter(a => a.type === 'Checking') : accs.filter(a => a.type === 'Savings');
      case 'Credit Payment':
        return direction === 'from' ? accs.filter(a => a.type === 'Checking') : accs.filter(a => a.type === 'Credit');
      case 'Transfer between Checking':
        return accs.filter(a => a.type === 'Checking');
      default:
        return accs;
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        {allowedModes.includes('income') && (
          <button onClick={() => setActiveMode('income')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'income' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Income</button>
        )}
        {allowedModes.includes('expense') && (
          <button onClick={() => setActiveMode('expense')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'expense' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Expense</button>
        )}
        {allowedModes.includes('allocation') && (
          <button onClick={() => setActiveMode('allocation')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'allocation' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Allocation</button>
        )}
        {allowedModes.includes('transfer') && (
          <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'transfer' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transfer</button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="p-5 space-y-4">
        {error && (
          <div className="p-3 bg-red-50 border border-red-100 rounded-lg flex items-center gap-2 text-red-600 text-[10px] font-bold uppercase animate-in fade-in slide-in-from-top-1">
            <AlertCircle size={14} />
            {error}
          </div>
        )}

        {activeMode === 'income' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
             <div>
              <label className={labelStyles}>Income Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions('income', "Select Income Type")}
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>Deposit Account</label>
              <div className="relative">
                <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Account</option>
                  {state.accounts.filter(a => ['Checking', 'Savings'].includes(a.type)).map(acc => (
                    <option key={acc.id} value={acc.id}>{acc.name}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        ) : activeMode === 'expense' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
             <div>
              <label className={labelStyles}>{isSavingsPage ? 'Savings Category' : 'Expense Category'}</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions('expense', isSavingsPage ? "Select Savings Fund" : "Select Expense Category")}
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>{isSavingsPage ? 'Savings Source' : 'Account / Source'}</label>
              <div className="relative">
                <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Account</option>
                  <optgroup label={isSavingsPage ? "Savings Accounts" : "Bank Accounts"}>
                    {getFilteredAccounts('from').map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </optgroup>
                  {!isSavingsPage && (
                    <optgroup label="Internal Ledgers">
                      {virtualAccounts.filter(va => va.id !== 'internal-transfers').map(vacc => (
                        <option key={vacc.id} value={vacc.id}>{vacc.name}</option>
                      ))}
                    </optgroup>
                  )}
                </select>
              </div>
            </div>
          </div>
        ) : activeMode === 'allocation' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
              <p className="text-[10px] text-blue-600 font-bold uppercase tracking-wider mb-1">Budget Allocation</p>
              <p className="text-[11px] text-blue-400 leading-tight">Add funds to a category budget without bank activity.</p>
            </div>
            <div>
              <label className={labelStyles}>Target Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions('expense', "Select Target Category")}
                </select>
              </div>
            </div>
          </div>
        ) : (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div>
              <label className={labelStyles}>Transfer Type</label>
              <div className="relative">
                <ArrowRightLeft className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select 
                  value={formData.transferType} 
                  onChange={e => setFormData({...formData, transferType: e.target.value as any, fromAccountId: '', toAccountId: '', fromCategoryId: '', toCategoryId: ''})} 
                  className={inputStyles}
                >
                  {TRANSFER_TYPES.filter(t => {
                    if (t === 'Update Budget (Allocation)') return false;
                    if (isSavingsPage) {
                       return ['Category Transfer', 'Transfer to Checking'].includes(t);
                    } else {
                       return t !== 'Transfer to Checking';
                    }
                  }).map(type => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromAccount && (
                <div>
                  <label className={labelStyles}>Account From</label>
                  <select value={formData.fromAccountId} onChange={e => setFormData({...formData, fromAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    <option value="">Select Source</option>
                    {getFilteredAccounts('from').map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </select>
                </div>
              )}
              {showToAccount && (
                <div>
                  <label className={labelStyles}>Account To</label>
                  <select value={formData.toAccountId} onChange={e => setFormData({...formData, toAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    <option value="">Select Destination</option>
                    {getFilteredAccounts('to').map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </select>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromCategory && (
                <div>
                  <label className={labelStyles}>Category From</label>
                  <select value={formData.fromCategoryId} onChange={e => setFormData({...formData, fromCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    {renderCategoryOptions(isSavingsPage ? 'expense' : 'all', "From Cat")}
                  </select>
                </div>
              )}
              {showToCategory && (
                <div>
                  <label className={labelStyles}>Category To</label>
                  <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    {renderCategoryOptions((isSavingsPage && formData.transferType !== 'Transfer to Checking') ? 'expense' : 'all', "To Cat")}
                  </select>
                </div>
              )}
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className={labelStyles}>Amount</label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className={inputStyles} placeholder="0.00" required />
            </div>
          </div>
          <div>
            <label className={labelStyles}>Date</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className={inputStyles} required />
            </div>
          </div>
        </div>

        <div>
          <label className={labelStyles}>Description {activeMode === 'allocation' && '(Optional)'}</label>
          <div className="relative">
            <FileText className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input 
              type="text" 
              value={formData.description} 
              onChange={e => setFormData({...formData, description: e.target.value})} 
              className={inputStyles} 
              placeholder={activeMode === 'allocation' ? 'Internal Allocation' : 'Transaction details...'} 
            />
          </div>
        </div>

        <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-xl text-[10px] uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-600 transition-all active:scale-95 flex items-center justify-center gap-2">
          {activeMode === 'income' ? 'Record Income' : activeMode === 'expense' ? 'Record Expense' : activeMode === 'allocation' ? 'Allocate Funds' : 'Process Transfer'}
        </button>
      </form>
    </div>
  );
};

export default TransactionPanel;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, parseLocalDate } from '../utils';
import { AlertCircle, PiggyBank, History } from 'lucide-react';
import TransactionPanel from './TransactionPanel';

interface SavingsProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
}

const Savings: React.FC<SavingsProps> = ({ state, addTransaction, executeTransfer }) => {
  const savingsCategories = useMemo(() => 
    state.categories.filter(c => c.classificationId === 'class-savings' && !c.deleted), 
    [state.categories]
  );

  const savingsAccounts = useMemo(() => 
    state.accounts.filter(a => a.type === 'Savings'), 
    [state.accounts]
  );

  const reconciliation = useMemo(() => {
    const totalBankBalance = savingsAccounts.reduce((sum, acc) => sum + acc.balance, 0);
    const totalAllocated = savingsCategories.reduce((sum, cat) => sum + cat.balance, 0);
    return {
      accounts: savingsAccounts,
      totalBank: totalBankBalance,
      totalAllocated: totalAllocated,
      difference: totalBankBalance - totalAllocated
    };
  }, [savingsAccounts, savingsCategories]);

  // Historical Summary Logic
  const months = useMemo(() => {
    const res = [];
    const startDate = new Date(2025, 11, 1);
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number, net: number }>> = {};
    savingsCategories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent, net: added + spent };
      });
    });
    return data;
  }, [savingsCategories, state.transactions, months]);

  const renderHistoricalTable = (title: string, field: 'added' | 'spent', bgColor: string) => (
    <div className={`bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-6`}>
      <div className={`px-6 py-4 ${bgColor} border-b border-slate-200 flex justify-between items-center`}>
        <h4 className="font-bold text-slate-700 uppercase text-[10px] tracking-widest">{title}</h4>
      </div>
      <div className="overflow-x-auto custom-scrollbar">
        <table className="w-full text-left text-[10px] uppercase border-collapse">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-10 border-r border-slate-200">Category</th>
              {months.map(m => (
                <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right border-r border-slate-100 last:border-r-0">
                  {parseLocalDate(m + "-01").toLocaleDateString('en-US', { month: 'short', year: '2-digit' })}
                </th>
              ))}
              <th className="px-6 py-3 text-slate-900 font-bold text-right bg-slate-100 border-l border-slate-200">Total</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {savingsCategories.map(cat => {
              let rowTotal = 0;
              return (
                <tr key={cat.id} className="hover:bg-slate-50/50 group h-8">
                  <td className="px-6 py-2 text-slate-600 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{cat.name}</td>
                  {months.map(m => {
                    const val = calculations[cat.id]?.[m]?.[field] || 0;
                    rowTotal += val;
                    return (
                      <td key={m} className={`px-3 py-2 text-right border-r border-slate-50 last:border-r-0 ${val === 0 ? 'text-slate-200' : val < 0 ? 'text-red-500' : 'text-slate-700'}`}>
                        {val === 0 ? '-' : formatCurrency(val, true)}
                      </td>
                    );
                  })}
                  <td className="px-6 py-2 text-right font-bold bg-slate-50 text-slate-900 border-l border-slate-200">
                    {formatCurrency(rowTotal, true)}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="px-6 py-4 bg-emerald-50 border-b border-emerald-100 flex justify-between items-center">
              <h3 className="font-bold text-emerald-800 uppercase text-xs tracking-widest flex items-center gap-2">
                <PiggyBank size={16} /> Savings Fund Balances
              </h3>
            </div>
            <table className="w-full text-left text-sm">
              <thead className="bg-white border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Category</th>
                  <th className="px-6 py-4 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Balance</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {savingsCategories.map(cat => (
                  <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-emerald-400">
                    <td className="px-6 py-3 text-slate-600 font-medium">{cat.name}</td>
                    <td className={`px-6 py-3 text-right font-bold ${cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{formatCurrency(cat.balance)}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-emerald-900 text-white">
                <tr>
                  <td className="px-6 py-4 font-bold uppercase text-[10px] tracking-widest">Total Allocated Savings</td>
                  <td className="px-6 py-4 text-right text-lg font-black">{formatCurrency(reconciliation.totalAllocated)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        <div className="lg:block">
          <div className="sticky top-8 space-y-6">
            <TransactionPanel 
              state={state} 
              onAddTransaction={addTransaction} 
              onExecuteTransfer={executeTransfer} 
              allowedModes={['expense', 'allocation', 'transfer']}
              filterClassificationId="class-savings"
            />

            <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
              <h3 className="text-[10px] text-slate-500 mb-2">Savings Reconciliation</h3>
              <div className="space-y-3">
                {reconciliation.accounts.map(acc => (
                  <div key={acc.id} className="flex justify-between">
                    <span>{acc.name}</span>
                    <span className="text-white">{formatCurrency(acc.balance)}</span>
                  </div>
                ))}

                <div className="pt-2 border-t border-slate-800 flex justify-between text-emerald-400">
                  <span>Total Liquid Savings</span>
                  <span>{formatCurrency(reconciliation.totalBank)}</span>
                </div>

                <div className="flex justify-between text-slate-500">
                  <span>Total Allocated</span>
                  <span>{formatCurrency(-reconciliation.totalAllocated)}</span>
                </div>

                <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                  <div>
                    <span className="text-[9px] text-slate-500 block mb-1">Difference (Update Budget)</span>
                    <span className={`text-2xl font-black ${Math.abs(reconciliation.difference) < 0.01 ? 'text-green-400' : 'text-blue-500'}`}>
                      {formatCurrency(reconciliation.difference)}
                    </span>
                  </div>
                  <AlertCircle size={28} className={Math.abs(reconciliation.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex items-center gap-3 border-b border-slate-200 pb-2">
           <History size={18} className="text-slate-400" />
           <h3 className="font-black text-slate-800 uppercase tracking-[0.2em] text-xs">Historical Performance</h3>
        </div>

        {renderHistoricalTable("Savings Additions (Monthly Inflow)", 'added', 'bg-emerald-50/50')}
        {renderHistoricalTable("Savings Expenses (Monthly Outflow)", 'spent', 'bg-red-50/30')}

        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-900 text-white border-b border-slate-300 flex items-center justify-between">
            <h4 className="font-bold uppercase text-[10px] tracking-widest">Ending Savings Balance History</h4>
          </div>
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left text-[10px] uppercase border-collapse">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 text-slate-500 font-bold sticky left-0 bg-slate-50 z-20 border-r border-slate-200">Category</th>
                  {months.map(m => (
                    <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right border-r border-slate-100 last:border-r-0">
                      {parseLocalDate(m + "-01").toLocaleDateString('en-US', { month: 'short', year: '2-digit' })}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {savingsCategories.map(cat => {
                  return (
                    <tr key={cat.id} className="hover:bg-slate-50/50 group h-8">
                      <td className="px-6 py-2 text-slate-600 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{cat.name}</td>
                      {months.map(m => {
                        const limit = parseLocalDate(m + "-01");
                        limit.setMonth(limit.getMonth() + 1);
                        const sumAfter = state.transactions
                          .filter(t => t.categoryId === cat.id && parseLocalDate(t.date) >= limit)
                          .reduce((s, t) => s + t.amount, 0);
                        const balanceAtEnd = cat.balance - sumAfter;
                        return (
                          <td key={m} className={`px-3 py-2 text-right border-r border-slate-50 last:border-r-0 ${balanceAtEnd < 0 ? 'text-red-500' : 'text-slate-700'}`}>
                            {formatCurrency(balanceAtEnd, true)}
                          </td>
                        );
                      })}
                    </tr>
                  );
                })}
              </tbody>
              <tfoot className="bg-emerald-900 text-white font-black h-10">
                <tr>
                  <td className="px-6 py-2 uppercase tracking-widest text-[9px] sticky left-0 bg-emerald-900 z-20">Portfolio Value</td>
                  {months.map(m => {
                    const totalAtEnd = savingsCategories.reduce((acc, cat) => {
                      const limit = parseLocalDate(m + "-01");
                      limit.setMonth(limit.getMonth() + 1);
                      const sumAfter = state.transactions
                        .filter(t => t.categoryId === cat.id && parseLocalDate(t.date) >= limit)
                        .reduce((s, t) => s + t.amount, 0);
                      return acc + (cat.balance - sumAfter);
                    }, 0);
                    return <td key={m} className="px-3 py-2 text-right border-r border-emerald-800 last:border-r-0">{formatCurrency(totalAtEnd, true)}</td>;
                  })}
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Savings;

import React, { useState, useEffect } from 'react';
import { Calendar, DollarSign, Tag, Landmark, FileText, ArrowRightLeft, AlertCircle } from 'lucide-react';
import { AppState, TransactionType } from '../types';
import { TRANSFER_TYPES } from '../constants';

interface TransactionPanelProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
  allowedModes?: ('income' | 'expense' | 'allocation' | 'transfer')[];
  filterClassificationId?: string;
}

const TransactionPanel: React.FC<TransactionPanelProps> = ({ 
  state, 
  onAddTransaction, 
  onExecuteTransfer,
  allowedModes = ['income', 'expense', 'allocation', 'transfer'],
  filterClassificationId
}) => {
  const isSavingsPage = filterClassificationId === 'class-savings';
