    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        {allowedModes.includes('income') && (
          <button onClick={() => setActiveMode('income')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'income' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Income</button>
        )}
        {allowedModes.includes('expense') && (
          <button onClick={() => setActiveMode('expense')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'expense' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Expense</button>
        )}
        {allowedModes.includes('allocation') && (
          <button onClick={() => setActiveMode('allocation')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'allocation' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Allocation</button>
        )}
        {allowedModes.includes('transfer') && (
          <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'transfer' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transfer</button>
