    const amountNum = parseFloat(formData.amount);

    if (isNaN(amountNum) || amountNum <= 0) {
      setError("Please enter a positive amount.");
      return;
    }

    if (activeMode === 'income') {
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: formData.accountId,
        amount: amountNum,
        description: formData.description,
        type: 'Income',
      });
    } else if (activeMode === 'expense') {
      let accId = formData.accountId;
      // On Savings page, source is always Savings
      if (isSavingsPage && !accId) {
        accId = state.accounts.find(a => a.type === 'Savings' && a.id !== 'acc-cd')?.id || '';
      }
      onAddTransaction({
        categoryId: formData.categoryId,
        date: formData.date,
        accountId: accId,
        amount: -amountNum,
        description: formData.description,
        type: 'Standard',
      });
    } else if (activeMode === 'allocation') {
      onAddTransaction({
        categoryId: formData.toCategoryId,
        date: formData.date,
        accountId: 'internal',
        amount: amountNum,
        description: formData.description || 'Internal Allocation',
        type: 'Update Budget (Allocation)' as any,
      });
    } else {
      let effectiveToAccId = formData.toAccountId;
      let effectiveFromAccId = formData.fromAccountId;

      // Handle Dashboard 'Transfer to Savings'
      if (!isSavingsPage && formData.transferType === 'Transfer to Savings') {
        effectiveToAccId = state.accounts.find(a => a.type === 'Savings' && a.id !== 'acc-cd')?.id || '';
      }

      // Handle Savings Page Hidden Fields: source is always liquid savings
      if (isSavingsPage) {
        const liquidSavings = state.accounts.find(a => a.type === 'Savings' && a.id !== 'acc-cd')?.id || '';
        effectiveFromAccId = liquidSavings;

        if (formData.transferType === 'Category Transfer') {
          effectiveToAccId = liquidSavings;
        } else if (formData.transferType === 'Transfer to Checking' && !effectiveToAccId) {
          // If they didn't pick one despite it being visible, fallback to first checking
          effectiveToAccId = state.accounts.find(a => a.type === 'Checking')?.id || '';
        }
      }

      onExecuteTransfer({
        type: formData.transferType,
        date: formData.date,
        amount: amountNum,
        description: formData.description,
        fromAccountId: effectiveFromAccId,
        toAccountId: effectiveToAccId,
        fromCategoryId: formData.fromCategoryId,
        toCategoryId: formData.toCategoryId
      });
    }

    // Reset fields except date and persistent selections
    setFormData(prev => ({ ...prev, amount: '', description: '', categoryId: '', toCategoryId: '', fromCategoryId: '' }));
  };

  const inputStyles = "w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:outline-none transition-all";
  const labelStyles = "block text-[10px] font-bold text-slate-400 uppercase mb-1.5";

  // Visibility logic: hide account selectors on Savings page transfers EXCEPT for 'Account To' on 'Transfer to Checking'
  const showFromAccount = isSavingsPage 
    ? false 
    : ['Transfer to Savings', 'Credit Payment', 'Transfer between Checking'].includes(formData.transferType);

  const showToAccount = isSavingsPage
    ? formData.transferType === 'Transfer to Checking'
    : ['Credit Payment', 'Transfer between Checking'].includes(formData.transferType);

  const showFromCategory = isSavingsPage
    ? ['Category Transfer', 'Transfer to Checking'].includes(formData.transferType)
    : ['Category Transfer'].includes(formData.transferType);

  const showToCategory = isSavingsPage
    ? ['Category Transfer', 'Transfer to Checking'].includes(formData.transferType)
    : ['Category Transfer'].includes(formData.transferType);

  const renderCategoryOptions = (filter: 'income' | 'expense' | 'all' = 'all', placeholder: string = "Select Category") => {
    return (
      <>
        <option value="">{placeholder}</option>
        {state.classifications.map(cls => {
          // Rule: Exclude savings categories from Balance Statement (Expense/Allocation/Transfer)
          if (!isSavingsPage && cls.id === 'class-savings') {
            return null;
          }

          // Rule: Exclude income from transfers and primary entries unless explicitly looking for income
          const isIncomeClass = cls.id === 'class-income';
          if (!isIncomeClass && !isSavingsPage && activeMode === 'transfer' && cls.id === 'class-income') return null;

          // Rule: If on Savings page, focus strictly on Savings classification
          if (isSavingsPage && cls.id !== 'class-savings' && filter !== 'income') {
             // Exception: when looking for a target category for a transfer from savings to checking, allow all categories
             if (filter !== 'all') return null;
          }

          if (filter === 'expense' && isIncomeClass) return null;
          if (filter === 'income' && !isIncomeClass) return null;
          if (cls.id === 'class-transfers') return null;

          const catsInClass = activeCategories.filter(cat => cat.classificationId === cls.id);
          if (catsInClass.length === 0) return null;
          return (
            <optgroup key={cls.id} label={cls.name}>
              {catsInClass.map(cat => (
                <option key={cat.id} value={cat.id}>{cat.name}</option>
              ))}
            </optgroup>
          );
        })}
      </>
    );
  };

  const getFilteredAccounts = (direction: 'from' | 'to') => {
    const accs = state.accounts;
    if (isSavingsPage) {
      const pureSavings = accs.filter(a => a.type === 'Savings' && a.id !== 'acc-cd');
      if (activeMode === 'expense') return pureSavings;
      if (activeMode === 'transfer') {
        if (direction === 'from') return pureSavings;
        if (direction === 'to') {
          if (formData.transferType === 'Transfer to Checking') return accs.filter(a => a.type === 'Checking');
          return pureSavings;
        }
      }
      return pureSavings;
    }

    if (activeMode === 'income') return accs.filter(a => ['Checking', 'Savings'].includes(a.type) && a.id !== 'acc-cd');
    if (activeMode === 'expense') return accs.filter(a => ['Checking', 'Credit', 'Savings'].includes(a.type) && a.id !== 'acc-cd');

    switch (formData.transferType) {
      case 'Transfer to Savings':
        return direction === 'from' ? accs.filter(a => a.type === 'Checking') : accs.filter(a => a.type === 'Savings');
      case 'Credit Payment':
        return direction === 'from' ? accs.filter(a => a.type === 'Checking') : accs.filter(a => a.type === 'Credit');
      case 'Transfer between Checking':
        return accs.filter(a => a.type === 'Checking');
      default:
        return accs;
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="flex bg-slate-50 border-b border-slate-200">
        {allowedModes.includes('income') && (
          <button onClick={() => setActiveMode('income')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'income' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Income</button>
        )}
        {allowedModes.includes('expense') && (
          <button onClick={() => setActiveMode('expense')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'expense' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Expense</button>
        )}
        {allowedModes.includes('allocation') && (
          <button onClick={() => setActiveMode('allocation')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'allocation' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Allocation</button>
        )}
        {allowedModes.includes('transfer') && (
          <button onClick={() => setActiveMode('transfer')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest transition-colors ${activeMode === 'transfer' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>Transfer</button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="p-5 space-y-4">
        {error && (
          <div className="p-3 bg-red-50 border border-red-100 rounded-lg flex items-center gap-2 text-red-600 text-[10px] font-bold uppercase animate-in fade-in slide-in-from-top-1">
            <AlertCircle size={14} />
            {error}
          </div>
        )}

        {activeMode === 'income' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
             <div>
              <label className={labelStyles}>Income Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions('income', "Select Income Type")}
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyles}>Deposit Account</label>
              <div className="relative">
                <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                  <option value="">Select Account</option>
                  {getFilteredAccounts('to').map(acc => (
                    <option key={acc.id} value={acc.id}>{acc.name}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        ) : activeMode === 'expense' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
             <div>
              <label className={labelStyles}>{isSavingsPage ? 'Savings Category' : 'Expense Category'}</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.categoryId} onChange={e => setFormData({...formData, categoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions('expense', isSavingsPage ? "Select Savings Fund" : "Select Expense Category")}
                </select>
              </div>
            </div>
            {!isSavingsPage && (
              <div>
                <label className={labelStyles}>Account / Source</label>
                <div className="relative">
                  <Landmark className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                  <select value={formData.accountId} onChange={e => setFormData({...formData, accountId: e.target.value})} className={inputStyles} required>
                    <option value="">Select Account</option>
                    <optgroup label="Bank Accounts">
                      {getFilteredAccounts('from').map(acc => (
                        <option key={acc.id} value={acc.id}>{acc.name}</option>
                      ))}
                    </optgroup>
                  </select>
                </div>
              </div>
            )}
          </div>
        ) : activeMode === 'allocation' ? (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg">
              <p className="text-[10px] text-blue-600 font-bold uppercase tracking-wider mb-1">Budget Allocation</p>
              <p className="text-[11px] text-blue-400 leading-tight">Add funds to a category budget without bank activity.</p>
            </div>
            <div>
              <label className={labelStyles}>Target Category</label>
              <div className="relative">
                <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className={inputStyles} required>
                  {renderCategoryOptions('expense', "Select Target Category")}
                </select>
              </div>
            </div>
          </div>
        ) : (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
            <div>
              <label className={labelStyles}>Transfer Type</label>
              <div className="relative">
                <ArrowRightLeft className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <select 
                  value={formData.transferType} 
                  onChange={e => setFormData({...formData, transferType: e.target.value as any, fromAccountId: '', toAccountId: '', fromCategoryId: '', toCategoryId: ''})} 
                  className={inputStyles}
                >
                  {TRANSFER_TYPES.filter(t => {
                    if (t === 'Update Budget (Allocation)') return false;
                    if (isSavingsPage) {
                       return ['Category Transfer', 'Transfer to Checking'].includes(t);
                    } else {
                       return t !== 'Transfer to Checking';
                    }
                  }).map(type => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromAccount && (
                <div>
                  <label className={labelStyles}>Account From</label>
                  <select value={formData.fromAccountId} onChange={e => setFormData({...formData, fromAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    <option value="">Select Source</option>
                    {getFilteredAccounts('from').map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </select>
                </div>
              )}
              {showToAccount && (
                <div>
                  <label className={labelStyles}>Account To</label>
                  <select value={formData.toAccountId} onChange={e => setFormData({...formData, toAccountId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    <option value="">Select Destination</option>
                    {getFilteredAccounts('to').map(acc => (
                      <option key={acc.id} value={acc.id}>{acc.name}</option>
                    ))}
                  </select>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              {showFromCategory && (
                <div>
                  <label className={labelStyles}>Category From</label>
                  <select value={formData.fromCategoryId} onChange={e => setFormData({...formData, fromCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    {renderCategoryOptions(isSavingsPage ? 'expense' : 'all', "From Cat")}
                  </select>
                </div>
              )}
              {showToCategory && (
                <div>
                  <label className={labelStyles}>Category To</label>
                  <select value={formData.toCategoryId} onChange={e => setFormData({...formData, toCategoryId: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[11px] font-bold uppercase tracking-tight text-slate-600" required>
                    {renderCategoryOptions((isSavingsPage && formData.transferType !== 'Transfer to Checking') ? 'expense' : 'all', "To Cat")}
                  </select>
                </div>
              )}
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className={labelStyles}>Amount</label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className={inputStyles} placeholder="0.00" required />
            </div>
          </div>
          <div>
            <label className={labelStyles}>Date</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className={inputStyles} required />
            </div>
          </div>
        </div>

        <div>
          <label className={labelStyles}>Description {activeMode === 'allocation' && '(Optional)'}</label>
          <div className="relative">
            <FileText className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input 
              type="text" 
              value={formData.description} 
              onChange={e => setFormData({...formData, description: e.target.value})} 
              className={inputStyles} 
              placeholder={activeMode === 'allocation' ? 'Internal Allocation' : 'Transaction details...'} 
            />
          </div>
        </div>

        <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-xl text-[10px] uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-600 transition-all active:scale-95 flex items-center justify-center gap-2">
          {activeMode === 'income' ? 'Record Income' : activeMode === 'expense' ? 'Record Expense' : activeMode === 'allocation' ? 'Allocate Funds' : 'Process Transfer'}
        </button>
      </form>
    </div>
  );
};

export default TransactionPanel;

import { useState, useCallback } from 'react';
import { AppState, Transaction, Category, InvestmentSnapshot } from '../types';
import { INITIAL_DATA } from '../constants';
import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(() => {
    const base = JSON.parse(JSON.stringify(INITIAL_DATA)) as AppState;
    base.transactions.forEach(tx => {
      const cat = base.categories.find(c => c.id === tx.categoryId);
      if (cat) cat.balance += tx.amount;
      if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
        const acc = base.accounts.find(a => a.id === tx.accountId);
        if (acc) acc.balance += tx.amount;
      }
    });
    return base;
  });

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id, cleared: false };
        newTransactions.push(tx);

        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({ ...txData, accountId: 'internal' });
      } else {
        processSingle(txData);
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        if (txData.type === 'Income' || (selectedCat?.classificationId === 'class-income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const deleteTransaction = useCallback((txId: string) => {
    setState(prev => {
      const txToDelete = prev.transactions.find(t => t.id === txId);
      if (!txToDelete) return prev;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === txToDelete.categoryId) {
          return { ...cat, balance: cat.balance - txToDelete.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === txToDelete.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - txToDelete.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const undoLastTransaction = useCallback(() => {
    setState(prev => {
      if (prev.transactions.length === 0) return prev;
      const lastTx = prev.transactions[prev.transactions.length - 1];
      const txId = lastTx.id;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === lastTx.categoryId) {
          return { ...cat, balance: cat.balance - lastTx.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === lastTx.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - lastTx.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const deleteCategory = useCallback((catId: string) => {
    setState(prev => {
      const hasTransactions = prev.transactions.some(t => t.categoryId === catId);
      if (hasTransactions) {
        // Soft delete: keep for historical ledger/summary records
        return {
          ...prev,
          categories: prev.categories.map(c => c.id === catId ? { ...c, deleted: true } : c),
        };
      } else {
        // Hard delete: no data depends on this category
        return {
          ...prev,
          categories: prev.categories.filter(c => c.id !== catId),
        };
      }
    });
  }, []);

  const toggleCleared = useCallback((txId: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === txId ? { ...t, cleared: !t.cleared } : t)
    }));
  }, []);

  const updateBudget = useCallback((catId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, monthlyBudget: amount } : c)
    }));
  }, []);

  const setEstIncome = useCallback((amount: number) => {
    setState(prev => ({ ...prev, estimatedMonthlyIncome: amount }));
  }, []);

  const addInvestmentSnapshot = useCallback((snapshot: InvestmentSnapshot) => {
    setState(prev => {
      const filtered = prev.investmentSnapshots.filter(s => !(s.monthKey === snapshot.monthKey && s.accountId === snapshot.accountId));
      return {
        ...prev,
        investmentSnapshots: [...filtered, snapshot]
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string, txType: any = 'Standard') => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: txType,
          cleared: false,
          // Store transfer details for ledgers
          fromAccountId,
          toAccountId,
          fromCategoryId,
          toCategoryId
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && !accId.startsWith('internal') && accId !== 'none') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      switch (type) {
        case 'Category Transfer':
          recordTx(fromAccountId, fromCategoryId, -amount, description, 'Category Transfer');
          recordTx(toAccountId, toCategoryId, amount, description, 'Category Transfer');
          break;
        case 'Transfer to Savings':
          recordTx(undefined, toCategoryId, amount, description, 'Transfer to Savings');
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer to Savings');
          break;
        case 'Transfer to Checking':
          recordTx(toAccountId, toCategoryId, amount, description, 'Transfer to Checking');
          recordTx(undefined, fromCategoryId, -amount, description, 'Transfer to Checking');
          break;
        case 'Credit Payment':
          recordTx(fromAccountId, undefined, -amount, description, 'Credit Payment');
          recordTx(toAccountId, undefined, amount, description, 'Credit Payment');
          break;
        case 'Transfer between Checking':
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer between Checking');
          recordTx(toAccountId, undefined, amount, description, 'Transfer between Checking');
          break;
        case 'Update Budget (Allocation)':
          recordTx(undefined, toCategoryId, amount, description, 'Update Budget (Allocation)');
          break;
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];
      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({ id: classId, name: classificationName, color: color || 'bg-gray-100' });
      }
      const newCategory: Category = { id: `cat-${generateId()}`, name, classificationId: classId, balance: 0, monthlyBudget: 0 };
      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot
  };
};

import React, { useState } from 'react';
import { AppState, Transaction } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { CheckCircle, Circle, Trash2, X, AlertTriangle, Layers, ArrowRight } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ state, onToggleCleared, onDeleteTransaction }) => {
  // Removed internal-deposit as it was redundant
  const targetAccountIds = [
    'all',
    'acc-ds-8193', 
    'acc-visa-4914', 
    'acc-ds-6521', 
    'acc-cap-checking', 
    'internal', 
    'internal-transfers'
  ];
  const [activeAccId, setActiveAccId] = useState(targetAccountIds[0]); 
  const [deleteTxConfirm, setDeleteTxConfirm] = useState<Transaction | null>(null);

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'all': { name: 'All Activity' },
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal') || activeAccId === 'all';
  const isTransferView = activeAccId === 'internal-transfers';

  const activeAccount = virtualAccountMap[activeAccId] 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'all') return true;
      if (activeAccId === 'internal') return t.type === 'Update Budget (Allocation)';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const confirmDelete = () => {
    if (deleteTxConfirm) {
      onDeleteTransaction(deleteTxConfirm.id);
      setDeleteTxConfirm(null);
    }
  };

  const getAccountName = (id?: string) => {
    if (!id) return '-';
    if (id === 'internal') return 'Internal';
    if (id === 'none') return '-';
    return state.accounts.find(a => a.id === id)?.name || id;
  };

  const getCategoryName = (id?: string) => {
    if (!id) return '-';
    if (id === 'none') return '-';
    return state.categories.find(c => c.id === id)?.name || id;
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-4 items-center pb-2">
        <div className="flex gap-2 overflow-x-auto custom-scrollbar no-scrollbar">
          {/* Composite / Main Accounts */}
          {targetAccountIds.slice(0, 5).map(id => {
            const name = id === 'all' ? 'All Activity' : state.accounts.find(a => a.id === id)?.name;
            if (!name) return null;
            return (
              <button
                key={id}
                onClick={() => setActiveAccId(id)}
                className={`px-5 py-2 rounded-full text-[10px] font-bold transition-all whitespace-nowrap uppercase tracking-widest border border-slate-200 flex items-center gap-2 ${
                  activeAccId === id 
                    ? 'bg-slate-900 text-white shadow-lg border-slate-900' 
                    : 'bg-white text-slate-400 hover:border-slate-300'
                }`}
              >
                {id === 'all' && <Layers size={12} />}
                {name}
              </button>
            );
          })}
        </div>

        <div className="flex gap-6 items-center px-4 ml-2">
          {/* Internal / Classification Ledgers */}
          {targetAccountIds.slice(5).map(id => {
            const name = virtualAccountMap[id]?.name;
            if (!name) return null;
            const isActive = activeAccId === id;
            return (
              <button
                key={id}
                onClick={() => setActiveAccId(id)}
                className={`text-[10px] font-black uppercase tracking-widest transition-all ${
                  isActive 
                    ? 'bg-slate-900 text-white px-5 py-2 rounded-full shadow-lg' 
                    : 'text-slate-400 hover:text-slate-900 px-2'
                }`}
              >
                {name}
              </button>
            );
          })}
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {activeAccId === 'all' ? 'Full Composite Ledger' : isVirtual ? `Internal Budget ${activeAccount?.name} Activity` : `${activeAccount?.name} Activity`}
          </h3>
          {(!isVirtual && activeAccId !== 'all') && (
            <div className="text-sm font-bold text-slate-900">
              Total Balance: {formatCurrency(activeAccount?.balance || 0)}
            </div>
          )}
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-xs border-collapse">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                {isTransferView ? (
                  <>
                    <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter w-24">Date</th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Category From</th>
                    <th className="px-2 py-3 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Category To</th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Account From</th>
                    <th className="px-2 py-3 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Account To</th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter text-right">Amount</th>
                  </>
                ) : (
                  <>
                    <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Category</th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter w-24">Date</th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter">Account</th>
                    <th className="px-4 py-3 font-bold text-slate-400 uppercase tracking-tighter text-right">Amount</th>
                    <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter">Description</th>
                    <th className="px-6 py-3 font-bold text-slate-400 uppercase tracking-tighter text-center">Cleared</th>
                  </>
                )}
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map((tx, idx) => {
                  const cat = state.categories.find(c => c.id === tx.categoryId);
                  const acc = state.accounts.find(a => a.id === tx.accountId);
                  const accName = acc ? acc.name : (tx.accountId === 'internal' ? 'Allocation' : tx.accountId);
                  const isCredit = acc?.type === 'Credit';
                  const isTxVirtual = tx.accountId.startsWith('internal');

                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      {isTransferView ? (
                        <>
                          <td className="px-6 py-3 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3 text-slate-600 font-medium">{getCategoryName(tx.fromCategoryId)}</td>
                          <td className="px-2 py-3 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3 text-slate-600 font-medium">{getCategoryName(tx.toCategoryId)}</td>
                          <td className="px-4 py-3">
                            <span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.fromAccountId)}</span>
                          </td>
                          <td className="px-2 py-3 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3">
                            <span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.toAccountId)}</span>
                          </td>
                          <td className={`px-4 py-3 text-right font-black ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {formatCurrency(tx.amount)}
                          </td>
                        </>
                      ) : (
                        <>
                          <td className="px-6 py-3 text-slate-600 font-medium">
                            {cat?.name || 'Uncategorized'}
                            {cat?.deleted && <span className="ml-2 text-[8px] bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded uppercase font-black">Archived</span>}
                          </td>
                          <td className="px-4 py-3 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3">
                            <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase tracking-tight ${
                              isTxVirtual ? 'bg-slate-100 text-slate-400' : 
                              acc?.type === 'Credit' ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'
                            }`}>
                              {accName}
                            </span>
                          </td>
                          <td className={`px-4 py-3 text-right font-black ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                          </td>
                          <td className="px-6 py-3 text-slate-600 truncate max-w-[200px]">{tx.description}</td>
                          <td className="px-6 py-3 text-center">
                            <button 
                              onClick={() => onToggleCleared(tx.id)}
                              disabled={!isCredit || isTxVirtual}
                              className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                                (!isCredit || isTxVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                                tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                              }`}
                            >
                              {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                            </button>
                          </td>
                        </>
                      )}
                      <td className="px-4 py-3 text-right">
                        <button 
                          onClick={() => setDeleteTxConfirm(tx)}
                          className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={isTransferView ? 9 : 7} className="px-6 py-12 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-bold">No transactions found for this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {deleteTxConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <AlertTriangle size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight">
                Delete Transaction?
              </h4>
              <div className="p-4 bg-slate-50 rounded-xl space-y-2 text-left">
                <div className="flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase">
                  <span>{formatDisplayDate(deleteTxConfirm.date)}</span>
                  <span className={deleteTxConfirm.amount < 0 ? 'text-red-500' : 'text-blue-600'}>
                    {formatCurrency(deleteTxConfirm.amount)}
                  </span>
                </div>
                <p className="text-xs font-semibold text-slate-700 truncate">{deleteTxConfirm.description || 'No description'}</p>
                <div className="flex justify-between items-center">
                  <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">
                    Category: {state.categories.find(c => c.id === deleteTxConfirm.categoryId)?.name || 'N/A'}
                  </p>
                  <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">
                    Account: {state.accounts.find(a => a.id === deleteTxConfirm.accountId)?.name || 'Allocation'}
                  </p>
                </div>
              </div>
              <p className="text-[11px] text-slate-500 uppercase tracking-widest font-bold leading-relaxed">
                This will reverse the financial impact across all category and account ledgers.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteTxConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
            <button 
              onClick={() => setDeleteTxConfirm(null)}
              className="absolute top-4 right-4 p-1 text-slate-300 hover:text-slate-600 transition-colors"
            >
              <X size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountLedgers;

