      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot
  };
};
