    const savingsCategories = state.categories.filter(c => c.classificationId === 'class-savings');
    const totalSavings = savingsCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      capOne,
      dsChecking,
      dsCredit,
      visaCredit,
      debitBalance,
      creditBalance,
      net,
      totalAllocated,
      totalSavings,
      difference: net - totalAllocated
    };
  }, [state.accounts, state.categories]);

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings', 'class-transfers'].includes(c.id));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <div className="flex items-center gap-2">
               <button 
                  onClick={() => setIsEditMode(!isEditMode)} 
                  className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest transition-all px-4 py-1.5 rounded-full ${
                    isEditMode 
                      ? 'bg-blue-600 text-white shadow-lg' 
                      : 'text-slate-400 hover:text-slate-900 hover:bg-slate-100'
                  }`}
                >
