               {!isEditMode && (
                 <button 
                    onClick={() => undoLastTransaction()} 
                    className="flex items-center gap-1.5 text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-slate-100"
                  >
                    <Undo2 size={12} /> Undo Last
                  </button>
               )}
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider w-32">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Spent</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => {
                const cats = groupedCategories[cls.id] || [];
                if (cats.length === 0) return null;
                return (
                  <React.Fragment key={cls.id}>
                    <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={5} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                    {cats.map(cat => (
                      <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400">
                        <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                        <td className="px-4 py-2 text-right font-bold">
                          {isEditMode ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={cat.balance}
                              onChange={(e) => setCategoryBalance(cat.id, parseFloat(e.target.value) || 0)}
                              className="w-full px-2 py-1 bg-blue-50 border border-blue-200 rounded text-right text-xs focus:ring-1 focus:ring-blue-500 focus:outline-none"
                            />
                          ) : (
                            <span className={cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}>
                              {formatCurrency(cat.balance)}
                            </span>
                          )}
                        </td>
                        <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                        <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                        <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? formatCurrency(cat.monthlySpent) : '-'}</td>
                      </tr>
                    ))}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="lg:block">
        <div className="sticky top-8 space-y-6">
          {!isEditMode ? (
            <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />
          ) : (
            <div className="bg-white rounded-xl border-2 border-dashed border-blue-100 p-8 text-center space-y-3 animate-in fade-in duration-300">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-blue-50 text-blue-500 mb-2">
                <Edit3 size={24} />
              </div>
              <h4 className="text-xs font-black text-slate-800 uppercase tracking-widest">Edit Mode Active</h4>
              <p className="text-[10px] text-slate-400 leading-relaxed uppercase font-bold">
                You are manually adjusting balances. Transactions are disabled until you click "Done".
              </p>
              <button 
                onClick={() => setIsEditMode(false)}
                className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg hover:bg-blue-700 transition-all"
              >
                Exit Edit Mode
              </button>
            </div>
          )}

          <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
            <div className="flex justify-between items-center mb-2">
              <h3 className="text-[10px] text-slate-500 uppercase tracking-widest">Budget Reconciliation</h3>
              <button 
                onClick={() => setIsEditMode(!isEditMode)}
                className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full ${
                  isEditMode 
                    ? 'bg-blue-600 text-white shadow-lg' 
                    : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700 border border-slate-700'
                }`}
              >
                {isEditMode ? (
                  <><CheckCircle2 size={12} /> Done</>
                ) : (
                  <><Edit3 size={12} /> Manual Update</>
                )}
              </button>
            </div>

            <div className="space-y-3">
              {[
                { id: 'acc-cap-checking', label: 'Capital One Checking', key: 'capOne' },
                { id: 'acc-ds-6521', label: 'Discover Checking', key: 'dsChecking' },
                { id: 'acc-ds-8193', label: 'Discover Credit', key: 'dsCredit' },
                { id: 'acc-visa-4914', label: 'Chase Credit', key: 'visaCredit' }
              ].map(item => (
                <div key={item.id} className="flex justify-between items-center h-8">
                  <span>{item.label}</span>
                  {isEditMode ? (
                    <input 
                      type="number" 
                      step="0.01"
                      value={state.accounts.find(a => a.id === item.id)?.balance || 0}
                      onChange={(e) => setAccountBalance(item.id, parseFloat(e.target.value) || 0)}
                      className="w-24 px-2 py-0.5 bg-slate-800 border border-slate-700 rounded text-right text-[10px] text-white focus:ring-1 focus:ring-blue-500 focus:outline-none"
                    />
                  ) : (
                    <span className={reconciliation[item.key as keyof typeof reconciliation] < 0 ? 'text-red-400' : 'text-white'}>
                      {formatCurrency(reconciliation[item.key as keyof typeof reconciliation] as number)}
                    </span>
                  )}
                </div>
              ))}

              <div className="pt-2 border-t border-slate-800 flex justify-between text-blue-400">
                <span>Debit Balance</span>
                <span>{formatCurrency(reconciliation.debitBalance)}</span>
              </div>

              <div className="flex justify-between text-red-400">
                <span>Credit Balance</span>
                <span>{formatCurrency(reconciliation.creditBalance)}</span>
              </div>

              <div className="pt-2 border-t border-slate-800 flex justify-between text-white text-sm font-black">
                <span>Net</span>
                <span>{formatCurrency(reconciliation.net)}</span>
              </div>

              <div className="flex justify-between text-slate-500">
                <span>Allocated (Total Budget)</span>
                <span>{formatCurrency(-reconciliation.totalAllocated)}</span>
              </div>

              <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                <div>
                  <span className="text-[9px] text-slate-500 block mb-1">Difference (Update Budget)</span>
                  <span className={`text-2xl font-black ${Math.abs(reconciliation.difference) < 0.01 ? 'text-green-400' : 'text-blue-500'}`}>
                    {formatCurrency(reconciliation.difference)}
                  </span>
                </div>
                <AlertCircle size={28} className={Math.abs(reconciliation.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
              </div>

              <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                <span className="text-[11px] font-black text-white uppercase tracking-widest">Total Savings</span>
                <span className="text-sm font-black text-emerald-400">{formatCurrency(reconciliation.totalSavings)}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Savings from './components/Savings';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction}
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'savings':
        return (
          <Savings 
            state={state}
            addTransaction={addTransaction}
            executeTransfer={executeTransfer}
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'acc-ledgers':
        return (
          <AccountLedgers 
            state={state} 
            onToggleCleared={toggleCleared} 
            onDeleteTransaction={deleteTransaction}
          />
        );
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return <NetWorth state={state} onAddSnapshot={addInvestmentSnapshot} />;
      default:
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction} 
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, parseLocalDate } from '../utils';
import { AlertCircle, PiggyBank, History, Edit3, CheckCircle2 } from 'lucide-react';
import TransactionPanel from './TransactionPanel';

interface SavingsProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  executeTransfer: (transfer: any) => void;
  setCategoryBalance: (catId: string, balance: number) => void;
  setAccountBalance: (accId: string, balance: number) => void;
}

const Savings: React.FC<SavingsProps> = ({ 
  state, 
  addTransaction, 
  executeTransfer,
  setCategoryBalance,
  setAccountBalance
}) => {
  const [isEditMode, setIsEditMode] = useState(false);

  const savingsCategories = useMemo(() => 
    state.categories.filter(c => c.classificationId === 'class-savings' && !c.deleted), 
    [state.categories]
  );

  const savingsAccounts = useMemo(() => 
    state.accounts.filter(a => a.type === 'Savings'), 
    [state.accounts]
  );

  const reconciliation = useMemo(() => {
    const totalBankBalance = savingsAccounts.reduce((sum, acc) => sum + acc.balance, 0);
    const totalAllocated = savingsCategories.reduce((sum, cat) => sum + cat.balance, 0);
    return {
      accounts: savingsAccounts,
      totalBank: totalBankBalance,
      totalAllocated: totalAllocated,
      difference: totalBankBalance - totalAllocated
    };
  }, [savingsAccounts, savingsCategories]);

  // Historical Summary Logic
  const months = useMemo(() => {
    const res = [];
    const startDate = new Date(2025, 11, 1);
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number, net: number }>> = {};
    savingsCategories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent, net: added + spent };
      });
    });
    return data;
  }, [savingsCategories, state.transactions, months]);

  const renderHistoricalTable = (title: string, field: 'added' | 'spent', bgColor: string) => (
    <div className={`bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-6`}>
      <div className={`px-6 py-4 ${bgColor} border-b border-slate-200 flex justify-between items-center`}>
        <h4 className="font-bold text-slate-700 uppercase text-[10px] tracking-widest">{title}</h4>
      </div>
      <div className="overflow-x-auto custom-scrollbar">
        <table className="w-full text-left text-[10px] uppercase border-collapse">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-3 text-slate-500 font-bold sticky left-0 bg-slate-50 z-10 border-r border-slate-200">Category</th>
              {months.map(m => (
                <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right border-r border-slate-100 last:border-r-0">
                  {parseLocalDate(m + "-01").toLocaleDateString('en-US', { month: 'short', year: '2-digit' })}
                </th>
              ))}
              <th className="px-6 py-3 text-slate-900 font-bold text-right bg-slate-100 border-l border-slate-200">Total</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {savingsCategories.map(cat => {
              let rowTotal = 0;
              return (
                <tr key={cat.id} className="hover:bg-slate-50/50 group h-8">
                  <td className="px-6 py-2 text-slate-600 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{cat.name}</td>
                  {months.map(m => {
                    const val = calculations[cat.id]?.[m]?.[field] || 0;
                    rowTotal += val;
                    return (
                      <td key={m} className={`px-3 py-2 text-right border-r border-slate-50 last:border-r-0 ${val === 0 ? 'text-slate-200' : val < 0 ? 'text-red-500' : 'text-slate-700'}`}>
                        {val === 0 ? '-' : formatCurrency(val, true)}
                      </td>
                    );
                  })}
                  <td className="px-6 py-2 text-right font-bold bg-slate-50 text-slate-900 border-l border-slate-200">
                    {formatCurrency(rowTotal, true)}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="px-6 py-4 bg-emerald-50 border-b border-emerald-100 flex justify-between items-center">
              <h3 className="font-bold text-emerald-800 uppercase text-xs tracking-widest flex items-center gap-2">
                <PiggyBank size={16} /> Savings Fund Balances
              </h3>
              <button 
                onClick={() => setIsEditMode(!isEditMode)} 
                className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest transition-all px-4 py-1.5 rounded-full ${
                  isEditMode 
                    ? 'bg-emerald-600 text-white shadow-lg' 
                    : 'text-emerald-700 hover:text-emerald-900 hover:bg-emerald-100'
                }`}
              >
                {isEditMode ? (
                  <><CheckCircle2 size={12} /> Done</>
                ) : (
                  <><Edit3 size={12} /> Manual Update</>
                )}
              </button>
            </div>
            <table className="w-full text-left text-sm">
              <thead className="bg-white border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Category</th>
                  <th className="px-6 py-4 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider w-40">Balance</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {savingsCategories.map(cat => (
                  <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-emerald-400">
                    <td className="px-6 py-3 text-slate-600 font-medium">{cat.name}</td>
                    <td className="px-6 py-3 text-right font-bold">
                      {isEditMode ? (
                        <input 
                          type="number" 
                          step="0.01"
                          value={cat.balance}
                          onChange={(e) => setCategoryBalance(cat.id, parseFloat(e.target.value) || 0)}
                          className="w-full px-2 py-1 bg-emerald-50 border border-emerald-200 rounded text-right text-xs focus:ring-1 focus:ring-emerald-500 focus:outline-none"
                        />
                      ) : (
                        <span className={cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}>
                          {formatCurrency(cat.balance)}
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-emerald-900 text-white">
                <tr>
                  <td className="px-6 py-4 font-bold uppercase text-[10px] tracking-widest">Total Allocated Savings</td>
                  <td className="px-6 py-4 text-right text-lg font-black">{formatCurrency(reconciliation.totalAllocated)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        <div className="lg:block">
          <div className="sticky top-8 space-y-6">
            {!isEditMode ? (
              <TransactionPanel 
                state={state} 
                onAddTransaction={addTransaction} 
                onExecuteTransfer={executeTransfer} 
                allowedModes={['expense', 'allocation', 'transfer']}
                filterClassificationId="class-savings"
              />
            ) : (
              <div className="bg-white rounded-xl border-2 border-dashed border-emerald-100 p-8 text-center space-y-3 animate-in fade-in duration-300">
                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-emerald-50 text-emerald-500 mb-2">
                  <Edit3 size={24} />
                </div>
                <h4 className="text-xs font-black text-slate-800 uppercase tracking-widest">Edit Mode Active</h4>
                <p className="text-[10px] text-slate-400 leading-relaxed uppercase font-bold">
