                </p>
                <button 
                  onClick={() => setIsEditMode(false)}
                  className="mt-4 px-6 py-2 bg-emerald-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg hover:bg-emerald-700 transition-all"
                >
                  Exit Edit Mode
                </button>
              </div>
            )}

            <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
              <div className="flex justify-between items-center mb-2">
                <h3 className="text-[10px] text-slate-500 uppercase tracking-widest">Savings Reconciliation</h3>
                <button 
                  onClick={() => setIsEditMode(!isEditMode)}
                  className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full ${
                    isEditMode 
                      ? 'bg-emerald-600 text-white shadow-lg' 
                      : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700 border border-slate-700'
                  }`}
                >
                  {isEditMode ? (
                    <><CheckCircle2 size={12} /> Done</>
                  ) : (
                    <><Edit3 size={12} /> Manual Update</>
                  )}
                </button>
              </div>
              <div className="space-y-3">
                {reconciliation.accounts.map(acc => (
                  <div key={acc.id} className="flex justify-between items-center h-8">
                    <span>{acc.name}</span>
                    {isEditMode ? (
                      <input 
                        type="number" 
                        step="0.01"
                        value={acc.balance}
                        onChange={(e) => setAccountBalance(acc.id, parseFloat(e.target.value) || 0)}
                        className="w-24 px-2 py-0.5 bg-slate-800 border border-slate-700 rounded text-right text-[10px] text-white focus:ring-1 focus:ring-emerald-500 focus:outline-none"
                      />
                    ) : (
                      <span className="text-white">{formatCurrency(acc.balance)}</span>
                    )}
                  </div>
                ))}

                <div className="pt-2 border-t border-slate-800 flex justify-between text-emerald-400">
                  <span>Total Liquid Savings</span>
                  <span>{formatCurrency(reconciliation.totalBank)}</span>
                </div>

                <div className="flex justify-between text-slate-500">
                  <span>Total Allocated</span>
                  <span>{formatCurrency(-reconciliation.totalAllocated)}</span>
                </div>

                <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                  <div>
                    <span className="text-[9px] text-slate-500 block mb-1">Difference (Update Budget)</span>
                    <span className={`text-2xl font-black ${Math.abs(reconciliation.difference) < 0.01 ? 'text-green-400' : 'text-blue-500'}`}>
                      {formatCurrency(reconciliation.difference)}
                    </span>
                  </div>
                  <AlertCircle size={28} className={Math.abs(reconciliation.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex items-center gap-3 border-b border-slate-200 pb-2">
           <History size={18} className="text-slate-400" />
           <h3 className="font-black text-slate-800 uppercase tracking-[0.2em] text-xs">Historical Performance</h3>
        </div>

        {renderHistoricalTable("Savings Additions (Monthly Inflow)", 'added', 'bg-emerald-50/50')}
        {renderHistoricalTable("Savings Expenses (Monthly Outflow)", 'spent', 'bg-red-50/30')}

        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-900 text-white border-b border-slate-300 flex items-center justify-between">
            <h4 className="font-bold uppercase text-[10px] tracking-widest">Ending Savings Balance History</h4>
          </div>
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left text-[10px] uppercase border-collapse">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 text-slate-500 font-bold sticky left-0 bg-slate-50 z-20 border-r border-slate-200">Category</th>
                  {months.map(m => (
                    <th key={m} className="px-3 py-3 text-slate-500 font-bold text-right border-r border-slate-100 last:border-r-0">
                      {parseLocalDate(m + "-01").toLocaleDateString('en-US', { month: 'short', year: '2-digit' })}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {savingsCategories.map(cat => {
                  return (
                    <tr key={cat.id} className="hover:bg-slate-50/50 group h-8">
                      <td className="px-6 py-2 text-slate-600 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{cat.name}</td>
                      {months.map(m => {
                        const limit = parseLocalDate(m + "-01");
                        limit.setMonth(limit.getMonth() + 1);
                        const sumAfter = state.transactions
                          .filter(t => t.categoryId === cat.id && parseLocalDate(t.date) >= limit)
                          .reduce((s, t) => s + t.amount, 0);
                        const balanceAtEnd = cat.balance - sumAfter;
                        return (
                          <td key={m} className={`px-3 py-2 text-right border-r border-slate-50 last:border-r-0 ${balanceAtEnd < 0 ? 'text-red-500' : 'text-slate-700'}`}>
                            {formatCurrency(balanceAtEnd, true)}
                          </td>
                        );
                      })}
                    </tr>
                  );
                })}
              </tbody>
              <tfoot className="bg-emerald-900 text-white font-black h-10">
                <tr>
                  <td className="px-6 py-2 uppercase tracking-widest text-[9px] sticky left-0 bg-emerald-900 z-20">Portfolio Value</td>
                  {months.map(m => {
                    const totalAtEnd = savingsCategories.reduce((acc, cat) => {
                      const limit = parseLocalDate(m + "-01");
                      limit.setMonth(limit.getMonth() + 1);
                      const sumAfter = state.transactions
                        .filter(t => t.categoryId === cat.id && parseLocalDate(t.date) >= limit)
                        .reduce((s, t) => s + t.amount, 0);
                      return acc + (cat.balance - sumAfter);
                    }, 0);
                    return <td key={m} className="px-3 py-2 text-right border-r border-emerald-800 last:border-r-0">{formatCurrency(totalAtEnd, true)}</td>;
                  })}
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

