                      onChange={(e) => setAccountBalance(item.id, parseFloat(e.target.value) || 0)}
                      className="w-24 px-2 py-0.5 bg-slate-800 border border-slate-700 rounded text-right text-[10px] text-white focus:ring-1 focus:ring-blue-500 focus:outline-none"
                    />
                  ) : (
                    <span className={reconciliation[item.key as keyof typeof reconciliation] < 0 ? 'text-red-400' : 'text-white'}>
                      {formatCurrency(reconciliation[item.key as keyof typeof reconciliation] as number)}
                    </span>
                  )}
