import React, { useMemo } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, parseLocalDate } from '../utils';

interface SummaryProps {
  state: AppState;
}

const Summary: React.FC<SummaryProps> = ({ state }) => {
  // Range: Dec 2025 to Dec 2026 (13 months)
  const months = useMemo(() => {
    const res = [];
    const startDate = new Date(2025, 11, 1); // December 2025
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const calculations = useMemo(() => {
    const data: Record<string, Record<string, { added: number, spent: number, net: number }>> = {};
    state.categories.forEach(cat => {
      data[cat.id] = {};
      months.forEach(m => {
        const txs = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === m);
        const added = txs.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = txs.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        data[cat.id][m] = { added, spent, net: added + spent };
      });
    });
    return data;
  }, [state.categories, state.transactions, months]);

  // Filter out redundant categories like Credit Payment to avoid double counting
  // AND filter out deleted categories that have no data in the summary range
  const categoriesToCalculate = useMemo(() => {
    return state.categories.filter(c => {
      if (c.id === 'cat-credit-payment' || c.name === 'Credit Payment') return false;

      if (c.deleted) {
        // Only keep if there's activity in the summary range
        const hasActivity = months.some(m => {
          const stats = calculations[c.id]?.[m];
          return stats && (stats.added !== 0 || stats.spent !== 0);
        });
        return hasActivity;
      }
      return true;
    });
  }, [state.categories, months, calculations]);

  const renderSection = (title: string, catList: any[], field: 'added' | 'spent' | 'net', colorClass: string, showCheckingTotal = false) => {
    // Group categories in catList by classification
    const groupedData = state.classifications
      .map(cls => ({
        classification: cls,
        categories: catList.filter(c => c.classificationId === cls.id)
      }))
      .filter(group => group.categories.length > 0);

    return (
      <div className="bg-white rounded border border-slate-300 shadow-sm overflow-hidden mb-8">
        <div className={`px-4 py-2 ${colorClass} border-b border-slate-300 flex items-center justify-between`}>
          <h3 className="font-bold text-slate-800 uppercase text-[11px] tracking-widest">{title}</h3>
          <span className="text-[10px] font-bold text-slate-400">DEC '25 - DEC '26</span>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase border-collapse border border-slate-300">
            <thead className="bg-slate-50 border-b border-slate-300">
              <tr>
                <th className="px-4 py-2 text-slate-500 font-bold border-r border-slate-300 sticky left-0 bg-slate-50 z-20">Category</th>
                {months.map((m, i) => {
                  const d = parseLocalDate(m + "-01");
                  const label = d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
                  return (
                    <th key={i} className="px-2 py-2 text-slate-500 font-bold text-right border-r border-slate-300 last:border-r-0">
                      {label}
                    </th>
                  );
                })}
                <th className="px-4 py-2 text-slate-900 font-bold text-right bg-slate-100 border-l border-slate-300">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-300">
              {groupedData.map(({ classification, categories }) => {
                // If it's the Income Summary section and the classification is "Income", 
                // skip the header row to avoid redundancy as requested.
                const isRedundantIncome = title === "Income Summary" && classification.name.toUpperCase() === "INCOME";

                return (
                  <React.Fragment key={classification.id}>
                    {/* Classification Group Header */}
                    {!isRedundantIncome && (
                      <tr className={`${classification.color} font-black h-7 border-y border-slate-300`}>
                        <td colSpan={months.length + 2} className="px-4 py-1 text-[9px] uppercase tracking-[0.15em] text-slate-700 bg-inherit sticky left-0 z-10 border-r border-slate-300 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">
                          {classification.name}
                        </td>
                      </tr>
                    )}
                    {/* Category Rows */}
                    {categories.map(cat => {
                      let rowTotal = 0;
                      return (
                        <tr key={cat.id} className="hover:bg-slate-50 group h-7">
                          <td className="px-4 py-1 text-slate-700 font-medium sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-300 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">
                            {cat.name}
                            {cat.deleted && <span className="ml-1 opacity-40 lowercase">(arc)</span>}
                          </td>
                          {months.map(m => {
                            const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0, net: 0 };
                            let val = 0;
                            if (field === 'added') val = stats.added;
                            else if (field === 'spent') val = stats.spent;
                            else val = stats.net;

                            rowTotal += val;

                            return (
                              <td key={m} className={`px-2 py-1 text-right border-r border-slate-300 last:border-r-0 ${val === 0 ? 'text-slate-200' : val < 0 ? 'text-red-500' : 'text-slate-700'}`}>
                                {val === 0 ? '-' : formatCurrency(val, true)}
                              </td>
                            );
                          })}
                          <td className="px-4 py-1 text-right font-bold bg-slate-50 text-slate-900 border-l border-slate-300">
                            {formatCurrency(rowTotal, true)}
                          </td>
                        </tr>
                      );
                    })}
                  </React.Fragment>
                );
              })}
            </tbody>
            <tfoot className="bg-slate-900 text-white font-bold h-8 border-t border-slate-300">
              <tr>
                <td className="px-4 py-1 uppercase tracking-widest text-[9px] sticky left-0 bg-slate-900 border-r border-slate-700">{showCheckingTotal ? "Checking Total" : "Total"}</td>
                {months.map(m => {
                  let monthTotal = 0;
                  catList.forEach(cat => {
                    const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0, net: 0 };
                    if (field === 'added') monthTotal += stats.added;
                    else if (field === 'spent') monthTotal += stats.spent;
                    else monthTotal += stats.net;
                  });
                  return <td key={m} className="px-2 py-1 text-right border-r border-slate-700 last:border-r-0">{formatCurrency(monthTotal, true)}</td>;
                })}
                <td className="px-4 py-1 text-right bg-slate-800 border-l border-slate-700">
                  {formatCurrency(catList.reduce((acc, cat) => {
                    let catSum = 0;
                    months.forEach(m => {
                      const stats = calculations[cat.id]?.[m] || { added: 0, spent: 0, net: 0 };
                      if (field === 'added') catSum += stats.added;
                      else if (field === 'spent') catSum += stats.spent;
                      else catSum += stats.net;
                    });
                    return acc + catSum;
                  }, 0), true)}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    );
  };

  const incomeCategories = categoriesToCalculate.filter(c => c.classificationId === 'class-income');
  const expenseCategories = categoriesToCalculate.filter(c => !['class-income', 'class-savings', 'class-transfers'].includes(c.classificationId));

  const resourceTotals = months.map(m => incomeCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.added || 0), 0));
  const expenseTotalFlow = months.map(m => expenseCategories.reduce((sum, cat) => sum + (calculations[cat.id]?.[m]?.spent || 0), 0));

  return (
    <div className="space-y-6 pb-24">
      {/* 1. Income Summary */}
      {renderSection("Income Summary", incomeCategories, 'added', 'bg-cyan-50')}

      {/* 2. Expenses Summary */}
      {renderSection("Expenses Summary", expenseCategories, 'spent', 'bg-red-50')}

      {/* 3. Resources vs Expenses Analysis */}
      <div className="bg-slate-900 rounded border border-slate-700 shadow-2xl overflow-hidden mb-8">
        <div className="px-4 py-3 bg-slate-800 border-b border-slate-700 flex items-center justify-between">
          <h3 className="font-black text-white uppercase text-[12px] tracking-widest">Resources vs Expenses Analysis</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] uppercase tracking-tighter text-slate-300 border-collapse border border-slate-800">
            <thead className="border-b border-slate-800 bg-slate-800/50">
              <tr>
                <th className="px-6 py-3 font-bold sticky left-0 bg-slate-800 z-10 border-r border-slate-700">Metric</th>
                {months.map((m, i) => {
                   const d = parseLocalDate(m + "-01");
                   return <th key={i} className="px-3 py-3 text-right border-r border-slate-700 last:border-r-0">{d.toLocaleDateString('en-US', {month: 'short', year:'2-digit'})}</th>;
                })}
                <th className="px-6 py-3 text-right bg-slate-800 border-l border-slate-700">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 font-bold">
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-cyan-400 border-r border-slate-800">Resources (Income)</td>
                {resourceTotals.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">{formatCurrency(val, true)}</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-cyan-400 border-l border-slate-700">{formatCurrency(resourceTotals.reduce((a,b)=>a+b, 0), true)}</td>
              </tr>
              <tr className="h-10">
                <td className="px-6 py-2 sticky left-0 bg-slate-900 z-10 text-red-400 border-r border-slate-800">Expenses (Total Spend)</td>
                {expenseTotalFlow.map((val, i) => <td key={i} className="px-3 py-2 text-right border-r border-slate-800 last:border-r-0">{formatCurrency(val, true)}</td>)}
                <td className="px-6 py-2 text-right bg-slate-800 text-red-400 border-l border-slate-700">{formatCurrency(expenseTotalFlow.reduce((a,b)=>a+b, 0), true)}</td>
              </tr>
              <tr className="bg-slate-950 text-white text-sm h-14">
                <td className="px-6 py-4 sticky left-0 bg-slate-950 z-10 uppercase tracking-widest border-r border-slate-800 shadow-[4px_0_10px_rgba(0,0,0,0.2)]">Net Cash Flow</td>
                {months.map((m, i) => {
                  const net = resourceTotals[i] + expenseTotalFlow[i];
                  return <td key={i} className={`px-3 py-4 text-right border-r border-slate-800 last:border-r-0 ${net < 0 ? 'text-red-500 font-black' : 'text-green-400 font-black'}`}>{formatCurrency(net, true)}</td>
                })}
                <td className="px-6 py-4 text-right font-black bg-blue-600 shadow-[-4px_0_10px_rgba(0,0,0,0.2)] border-l border-blue-700">
                  {formatCurrency(resourceTotals.reduce((a,b)=>a+b, 0) + expenseTotalFlow.reduce((a,b)=>a+b, 0), true)}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* 4. Money Added Summary */}
      {renderSection("Money Added Summary", expenseCategories, 'added', 'bg-blue-50', true)}

      {/* 5. Activity Summary */}
      {renderSection("Summary Activity (Net)", expenseCategories, 'net', 'bg-slate-50')}
    </div>
  );
};

