import { useState, useCallback } from 'react';
import { AppState, Transaction, Category, InvestmentSnapshot, Classification } from '../types';
import { INITIAL_DATA } from '../constants';
import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(() => {
    const base = JSON.parse(JSON.stringify(INITIAL_DATA)) as AppState;
    base.transactions.forEach(tx => {
      const cat = base.categories.find(c => c.id === tx.categoryId);
      if (cat) cat.balance += tx.amount;
      if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
        const acc = base.accounts.find(a => a.id === tx.accountId);
        if (acc) acc.balance += tx.amount;
      }
    });
    return base;
  });

  const setCategoryBalance = useCallback((catId: string, balance: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, balance } : c)
    }));
  }, []);

  const setAccountBalance = useCallback((accId: string, balance: number) => {
    setState(prev => ({
      ...prev,
      accounts: prev.accounts.map(a => a.id === accId ? { ...a, balance } : a)
    }));
  }, []);

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id, cleared: false };
        newTransactions.push(tx);

        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({ ...txData, accountId: 'internal' });
      } else {
        processSingle(txData);
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        if (txData.type === 'Income' || (selectedCat?.classificationId === 'class-income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const deleteTransaction = useCallback((txId: string) => {
    setState(prev => {
      const txToDelete = prev.transactions.find(t => t.id === txId);
      if (!txToDelete) return prev;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === txToDelete.categoryId) {
          return { ...cat, balance: cat.balance - txToDelete.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === txToDelete.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - txToDelete.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const undoLastTransaction = useCallback(() => {
    setState(prev => {
      if (prev.transactions.length === 0) return prev;
      const lastTx = prev.transactions[prev.transactions.length - 1];
      const txId = lastTx.id;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === lastTx.categoryId) {
          return { ...cat, balance: cat.balance - lastTx.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === lastTx.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - lastTx.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const deleteCategory = useCallback((catId: string) => {
    setState(prev => {
      const hasTransactions = prev.transactions.some(t => t.categoryId === catId);
      if (hasTransactions) {
        return {
          ...prev,
          categories: prev.categories.map(c => c.id === catId ? { ...c, deleted: true } : c),
        };
      } else {
        return {
          ...prev,
          categories: prev.categories.filter(c => c.id !== catId),
        };
      }
    });
  }, []);

  const toggleCleared = useCallback((txId: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === txId ? { ...t, cleared: !t.cleared } : t)
    }));
  }, []);

  const updateBudget = useCallback((catId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, monthlyBudget: amount } : c)
    }));
  }, []);

  const setEstIncome = useCallback((amount: number) => {
    setState(prev => ({ ...prev, estimatedMonthlyIncome: amount }));
  }, []);

  const addInvestmentSnapshot = useCallback((snapshot: InvestmentSnapshot) => {
    setState(prev => {
      const filtered = prev.investmentSnapshots.filter(s => !(s.monthKey === snapshot.monthKey && s.accountId === snapshot.accountId));
      return {
        ...prev,
        investmentSnapshots: [...filtered, snapshot]
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string, txType: any = 'Standard') => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: txType,
          cleared: false,
          fromAccountId,
          toAccountId,
          fromCategoryId,
          toCategoryId
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && !accId.startsWith('internal') && accId !== 'none') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      switch (type) {
        case 'Category Transfer':
          recordTx(fromAccountId, fromCategoryId, -amount, description, 'Category Transfer');
          recordTx(toAccountId, toCategoryId, amount, description, 'Category Transfer');
          break;
        case 'Transfer to Savings':
          recordTx(undefined, toCategoryId, amount, description, 'Transfer to Savings');
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer to Savings');
          break;
        case 'Transfer to Checking':
          recordTx(toAccountId, toCategoryId, amount, description, 'Transfer to Checking');
          recordTx(undefined, fromCategoryId, -amount, description, 'Transfer to Checking');
          break;
        case 'Credit Payment':
          recordTx(fromAccountId, undefined, -amount, description, 'Credit Payment');
          recordTx(toAccountId, undefined, amount, description, 'Credit Payment');
          break;
        case 'Transfer between Checking':
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer between Checking');
          recordTx(toAccountId, undefined, amount, description, 'Transfer between Checking');
          break;
        case 'Update Budget (Allocation)':
          recordTx(undefined, toCategoryId, amount, description, 'Update Budget (Allocation)');
          break;
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];
      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({ id: classId, name: classificationName, color: color || 'bg-slate-100' });
      }
      const newCategory: Category = { id: `cat-${generateId()}`, name, classificationId: classId, balance: 0, monthlyBudget: 0 };
      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  // --- Layout Editing Actions ---

  const moveClassification = useCallback((id: string, direction: 'up' | 'down') => {
    setState(prev => {
      const idx = prev.classifications.findIndex(c => c.id === id);
      if (idx === -1) return prev;
      if (direction === 'up' && idx === 0) return prev;
      if (direction === 'down' && idx === prev.classifications.length - 1) return prev;

      const newClasses = [...prev.classifications];
      const offset = direction === 'up' ? -1 : 1;
      const [moved] = newClasses.splice(idx, 1);
      newClasses.splice(idx + offset, 0, moved);
      return { ...prev, classifications: newClasses };
    });
  }, []);

  const moveCategory = useCallback((id: string, direction: 'up' | 'down') => {
    setState(prev => {
      const cat = prev.categories.find(c => c.id === id);
      if (!cat) return prev;
      const classId = cat.classificationId;

      const classCategories = prev.categories.filter(c => c.classificationId === classId);
      const catIdx = classCategories.findIndex(c => c.id === id);

      if (direction === 'up' && catIdx === 0) return prev;
      if (direction === 'down' && catIdx === classCategories.length - 1) return prev;

      const newCategories = [...prev.categories];
      const offset = direction === 'up' ? -1 : 1;

      const globalIdx = newCategories.findIndex(c => c.id === id);
      const targetCatId = classCategories[catIdx + offset].id;
      const targetGlobalIdx = newCategories.findIndex(c => c.id === targetCatId);

      const [moved] = newCategories.splice(globalIdx, 1);
      newCategories.splice(targetGlobalIdx, 0, moved);

      return { ...prev, categories: newCategories };
    });
  }, []);

  const updateCategoryMetadata = useCallback((id: string, updates: Partial<Category>) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === id ? { ...c, ...updates } : c)
    }));
  }, []);

  const updateClassificationMetadata = useCallback((id: string, updates: Partial<Classification>) => {
    setState(prev => ({
      ...prev,
      classifications: prev.classifications.map(c => c.id === id ? { ...c, ...updates } : c)
    }));
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance,
    // Layout helpers
    moveClassification,
    moveCategory,
    updateCategoryMetadata,
    updateClassificationMetadata
  };
};

import React, { useState } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import { Target, TrendingUp, TrendingDown, Plus, Trash2, X, Wallet, Settings2, GripVertical, ChevronUp, ChevronDown, CheckCircle2, Palette } from 'lucide-react';

interface BudgetManagerProps {
  state: AppState;
  onUpdateBudget: (id: string, val: number) => void;
  onUpdateEstIncome: (val: number) => void;
  onAddCategory: (name: string, className: string, color: string) => void;
  onDeleteCategory: (id: string) => void;
  // Layout Editing Props
  moveClassification?: (id: string, direction: 'up' | 'down') => void;
  moveCategory?: (id: string, direction: 'up' | 'down') => void;
  updateCategoryMetadata?: (id: string, updates: any) => void;
  updateClassificationMetadata?: (id: string, updates: any) => void;
}

const COLOR_OPTIONS = [
  { name: 'Sky', value: 'bg-sky-100' },
  { name: 'Emerald', value: 'bg-emerald-100' },
  { name: 'Green', value: 'bg-green-100' },
  { name: 'Amber', value: 'bg-amber-100' },
  { name: 'Yellow', value: 'bg-yellow-100' },
  { name: 'Cyan', value: 'bg-cyan-100' },
  { name: 'Blue', value: 'bg-blue-100' },
  { name: 'Slate', value: 'bg-slate-100' },
  { name: 'Rose', value: 'bg-rose-100' },
  { name: 'Indigo', value: 'bg-indigo-100' },
];

const BudgetManager: React.FC<BudgetManagerProps> = ({ 
  state, 
  onUpdateBudget, 
  onUpdateEstIncome, 
  onAddCategory, 
  onDeleteCategory,
  moveClassification,
  moveCategory,
  updateCategoryMetadata,
  updateClassificationMetadata
}) => {
  const currentMonth = getMonthYearKey(new Date());
  const [showAddCat, setShowAddCat] = useState(false);
  const [isEditLayoutMode, setIsEditLayoutMode] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const [deleteConfirm, setDeleteConfirm] = useState<{ id: string, name: string } | null>(null);

  const budgetStats = state.categories
    .filter(cat => !cat.deleted && cat.id !== 'cat-credit-payment' && cat.name !== 'Credit Payment')
    .map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, added, spent };
    });

  const incomeCategories = budgetStats.filter(c => c.classificationId === 'class-income');
  const expenseCategories = budgetStats.filter(c => !['class-income', 'class-transfers'].includes(c.classificationId));
  const filteredClassifications = state.classifications.filter(cls => !['class-transfers'].includes(cls.id));

  const totalTargetIncome = incomeCategories.reduce((sum, c) => sum + c.monthlyBudget, 0);
  const totalBudgetedExpenses = expenseCategories.reduce((sum, c) => sum + c.monthlyBudget, 0);

  React.useEffect(() => {
    if (totalTargetIncome !== state.estimatedMonthlyIncome) {
      onUpdateEstIncome(totalTargetIncome);
    }
  }, [totalTargetIncome, state.estimatedMonthlyIncome, onUpdateEstIncome]);

  const diff = totalTargetIncome - totalBudgetedExpenses;

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      onAddCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const confirmDelete = () => {
    if (deleteConfirm) {
      onDeleteCategory(deleteConfirm.id);
      setDeleteConfirm(null);
    }
  };

  const renderSortButtons = (id: string, idx: number, max: number, type: 'class' | 'cat') => {
    if (!isEditLayoutMode) return null;
    return (
      <div className="flex flex-col gap-0.5 ml-2">
        <button 
          onClick={() => type === 'class' ? moveClassification?.(id, 'up') : moveCategory?.(id, 'up')}
          disabled={idx === 0}
          className={`p-0.5 rounded hover:bg-slate-200 transition-colors ${idx === 0 ? 'opacity-20 cursor-not-allowed' : 'text-slate-500'}`}
        >
          <ChevronUp size={12} />
        </button>
        <button 
          onClick={() => type === 'class' ? moveClassification?.(id, 'down') : moveCategory?.(id, 'down')}
          disabled={idx === max}
          className={`p-0.5 rounded hover:bg-slate-200 transition-colors ${idx === max ? 'opacity-20 cursor-not-allowed' : 'text-slate-500'}`}
        >
          <ChevronDown size={12} />
        </button>
      </div>
    );
  };

  return (
    <div className="space-y-8 pb-32">
      {/* 0. Top Controls */}
      <div className="flex flex-wrap gap-4 items-center justify-between border-b border-slate-200 pb-6">
        <div className="flex gap-3">
          <button 
            onClick={() => setShowAddCat(true)} 
            className="flex items-center gap-2 bg-slate-900 text-white px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
          >
            <Plus size={14} /> Add Category
          </button>
          <button 
            onClick={() => setIsEditLayoutMode(!isEditLayoutMode)} 
            className={`flex items-center gap-2 px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
              isEditLayoutMode 
                ? 'bg-blue-600 text-white shadow-lg' 
                : 'bg-white text-slate-500 border border-slate-200 hover:border-slate-400'
            }`}
          >
            {isEditLayoutMode ? <><CheckCircle2 size={14} /> Save Layout</> : <><Settings2 size={14} /> Edit Layout</>}
          </button>
        </div>
        {isEditLayoutMode && (
          <p className="text-[10px] font-bold text-blue-500 uppercase tracking-[0.2em] animate-pulse">
            Edit Mode Active: Reorder, Rename, or Re-group Categories
          </p>
        )}
      </div>

      {/* 1. Summary Boxes */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-100 text-blue-600 rounded-lg"><Target size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Est. Monthly Income</p>
            <p className="text-xl font-bold text-slate-800">{formatCurrency(totalTargetIncome, true)}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-green-100 text-green-600 rounded-lg"><TrendingUp size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total Budgeted Expenses</p>
            <p className="text-xl font-bold text-slate-800">{formatCurrency(totalBudgetedExpenses, true)}</p>
          </div>
        </div>
        <div className={`bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4 border-l-4 ${diff < 0 ? 'border-l-red-500' : 'border-l-green-500'}`}>
          <div className={`p-3 rounded-lg ${diff < 0 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}><TrendingDown size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Remaining to Allocate</p>
            <p className={`text-xl font-bold ${diff < 0 ? 'text-red-500' : 'text-slate-800'}`}>{formatCurrency(diff, true)}</p>
          </div>
        </div>
      </div>

      {/* 2. Unified Grouped List (Dynamic based on order) */}
      <div className="space-y-8">
        {filteredClassifications.map((cls, clsIdx) => {
          const catsInClass = (cls.id === 'class-income' ? incomeCategories : expenseCategories.filter(c => c.classificationId === cls.id));
          const isIncome = cls.id === 'class-income';

          return (
            <div key={cls.id} className={`bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300 delay-${clsIdx * 50}`}>
              <div className={`px-6 py-4 ${isIncome ? 'bg-cyan-50' : cls.color} border-b border-slate-200 flex justify-between items-center`}>
                <div className="flex items-center gap-2">
                  {isEditLayoutMode && <GripVertical size={16} className="text-slate-400 cursor-grab active:cursor-grabbing" />}
                  {isEditLayoutMode ? (
                    <input 
                      type="text" 
                      value={cls.name} 
                      onChange={e => updateClassificationMetadata?.(cls.id, { name: e.target.value })}
                      className="bg-transparent border-b border-slate-300 text-xs font-black uppercase tracking-widest focus:outline-none focus:border-blue-500 text-slate-800 w-48"
                    />
                  ) : (
                    <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest flex items-center gap-2">
                      {isIncome && <Wallet size={16} />} {cls.name}
                    </h3>
                  )}
                  {renderSortButtons(cls.id, clsIdx, filteredClassifications.length - 1, 'class')}
                </div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  {isIncome ? 'Cash Flow' : 'Target Allocation'}
                </p>
              </div>
              <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest">
                      {isEditLayoutMode ? 'Category Metadata' : 'Category'}
                    </th>
                    <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Target Amount</th>
                    <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Added (CM)</th>
                    {!isIncome && <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Spent (CM)</th>}
                    <th className="px-4 py-4"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {catsInClass.map((cat, catIdx) => (
                    <tr key={cat.id} className="hover:bg-slate-50/50 group">
                      <td className="px-6 py-3 font-medium text-slate-700">
                        {isEditLayoutMode ? (
                          <div className="flex items-center gap-4">
                            <GripVertical size={14} className="text-slate-300" />
                            <div className="space-y-2">
                              <input 
                                type="text" 
                                value={cat.name} 
                                onChange={e => updateCategoryMetadata?.(cat.id, { name: e.target.value })}
                                className="bg-white border border-slate-200 px-3 py-1.5 rounded-lg text-xs font-bold text-slate-700 focus:outline-none focus:ring-1 focus:ring-blue-500"
                              />
                              <select 
                                value={cat.classificationId} 
                                onChange={e => updateCategoryMetadata?.(cat.id, { classificationId: e.target.value })}
                                className="block w-full text-[9px] font-black uppercase tracking-widest text-slate-400 bg-transparent border-none focus:ring-0 cursor-pointer hover:text-blue-500"
                              >
                                {state.classifications.map(c => (
                                  <option key={c.id} value={c.id}>{c.name}</option>
                                ))}
                              </select>
                            </div>
                            {renderSortButtons(cat.id, catIdx, catsInClass.length - 1, 'cat')}
                          </div>
                        ) : (
                          cat.name
                        )}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <input 
                          type="number" 
                          disabled={isEditLayoutMode}
                          className={`w-24 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-right font-bold text-slate-900 focus:outline-none focus:ring-1 ${isIncome ? 'focus:ring-cyan-500' : 'focus:ring-blue-500'} ${isEditLayoutMode ? 'opacity-50' : ''}`}
                          value={cat.monthlyBudget}
                          onChange={e => onUpdateBudget(cat.id, parseFloat(e.target.value) || 0)}
                        />
                      </td>
                      <td className={`px-4 py-3 text-right font-bold ${isIncome ? 'text-cyan-600' : 'text-blue-500'}`}>
                        {formatCurrency(cat.added, true)}
                      </td>
                      {!isIncome && (
                        <td className={`px-4 py-3 text-right font-bold ${cat.spent < 0 ? 'text-red-500' : 'text-slate-500'}`}>
                          {cat.spent === 0 ? '-' : formatCurrency(cat.spent, true)}
                        </td>
                      )}
                      <td className="px-4 py-3 text-right">
                        <button 
                          onClick={() => setDeleteConfirm({ id: cat.id, name: cat.name })}
                          className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-red-50"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {catsInClass.length === 0 && (
                    <tr>
                      <td colSpan={5} className="px-6 py-8 text-center text-slate-300 italic text-[10px] uppercase tracking-widest">
                        Empty Classification
                      </td>
                    </tr>
                  )}
                </tbody>
                <tfoot className={`font-bold ${isIncome ? 'bg-cyan-900' : 'bg-slate-900'} text-white`}>
                  <tr>
                    <td className="px-6 py-4 uppercase tracking-widest text-xs">Subtotal: {cls.name}</td>
                    <td className="px-4 py-4 text-right text-lg">
                      {formatCurrency(catsInClass.reduce((sum, c) => sum + c.monthlyBudget, 0), true)}
                    </td>
                    <td className="px-4 py-4 text-right">
                      {formatCurrency(catsInClass.reduce((sum, c) => sum + (c.added || 0), 0), true)}
                    </td>
                    {!isIncome && (
                      <td className="px-4 py-4 text-right">
                        {formatCurrency(catsInClass.reduce((sum, c) => sum + (c.spent || 0), 0), true)}
                      </td>
                    )}
                    <td></td>
                  </tr>
                </tfoot>
              </table>
            </div>
          );
        })}
      </div>

      {/* Modals */}
      {showAddCat && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-6 transform transition-all scale-100 border border-slate-200">
            <h4 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
              <Plus size={20} className="text-blue-500" /> Define New Category
            </h4>
            <form onSubmit={handleAddCat} className="space-y-6">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Category Name</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none font-medium" 
                  value={newCat.name} 
                  onChange={e => setNewCat({...newCat, name: e.target.value})} 
                  placeholder="e.g. Vacation Fund" 
                  autoFocus
                  required 
                />
              </div>

              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Group / Classification</label>
                <select 
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none" 
                  value={newCat.className} 
                  onChange={e => setNewCat({...newCat, className: e.target.value})} 
                  required
                >
                  <option value="">Select Group...</option>
                  {state.classifications.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                  <option value="NEW">+ Create New Group</option>
                </select>
                {newCat.className === 'NEW' && (
                  <input 
                    type="text" 
                    className="w-full px-4 py-2.5 mt-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-1 focus:ring-blue-300" 
                    placeholder="New Group Name" 
                    onChange={e => setNewCat({...newCat, className: e.target.value})} 
                  />
                )}
              </div>

              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                  <Palette size={12} /> Branding Color
                </label>
                <div className="grid grid-cols-5 gap-3">
                  {COLOR_OPTIONS.map(opt => (
                    <button
                      key={opt.value}
                      type="button"
                      onClick={() => setNewCat({...newCat, color: opt.value})}
                      className={`h-10 rounded-lg transition-all border-2 ${opt.value} ${newCat.color === opt.value ? 'border-slate-900 scale-110 shadow-md' : 'border-transparent hover:border-slate-300'}`}
                      title={opt.name}
                    />
                  ))}
                </div>
              </div>

              <div className="flex gap-2 justify-end pt-6 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setShowAddCat(false)} 
                  className="px-6 py-2.5 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="px-10 py-2.5 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
                >
                  Create Category
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {deleteConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <Trash2 size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight">
                Are you sure you want to delete <span className="text-red-600 font-black">"{deleteConfirm.name}"</span>?
              </h4>
              <p className="text-[11px] text-slate-500 uppercase tracking-widest font-bold leading-relaxed">
                If data exists, it will be hidden but kept for history. If no data exists, it will be removed permanently.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  No, Keep it
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BudgetManager;

import React, { useState, useMemo, useEffect } from 'react';
import { AppState, Transaction, Classification } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';

interface LedgersProps {
  state: AppState;
}

const Ledgers: React.FC<LedgersProps> = ({ state }) => {
  // Prioritize Income class at the front
  const sortedClassifications = useMemo(() => {
    const classes = [...state.classifications];
    const incomeIdx = classes.findIndex(c => c.id === 'class-income');
    if (incomeIdx > -1) {
      const [income] = classes.splice(incomeIdx, 1);
      classes.unshift(income);
    }
    return classes;
  }, [state.classifications]);

  const [activeClassId, setActiveClassId] = useState(sortedClassifications[0]?.id);
  const [activeCategoryId, setActiveCategoryId] = useState<string | null>(null);

  const activeClass = useMemo(() => {
    return state.classifications.find(c => c.id === activeClassId);
  }, [state.classifications, activeClassId]);

  const categoriesInClass = useMemo(() => {
    return state.categories.filter(c => c.classificationId === activeClassId && !c.deleted);
  }, [state.categories, activeClassId]);

  useEffect(() => {
    if (categoriesInClass.length > 0) {
      setActiveCategoryId(categoriesInClass[0].id);
    } else {
      setActiveCategoryId(null);
    }
  }, [categoriesInClass]);

  const activeCategory = useMemo(() => {
    return state.categories.find(c => c.id === activeCategoryId);
  }, [state.categories, activeCategoryId]);

  const filteredTransactions = useMemo(() => {
    if (!activeCategoryId) return [];
    return state.transactions
      .filter(tx => tx.categoryId === activeCategoryId)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [state.transactions, activeCategoryId]);

  return (
    <div className="space-y-6">
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar no-scrollbar border-b border-slate-200">
        {sortedClassifications.map(cls => (
          <button
            key={cls.id}
            onClick={() => setActiveClassId(cls.id)}
            className={`px-6 py-2 rounded-t-lg text-[11px] font-bold transition-all whitespace-nowrap uppercase tracking-widest border-t border-l border-r ${
              activeClassId === cls.id 
                ? `${cls.color} text-slate-800 border-slate-300 -mb-[1px]` 
                : 'bg-slate-50 text-slate-400 border-transparent hover:bg-slate-100'
            }`}
          >
            {cls.name}
          </button>
        ))}
      </div>

      {categoriesInClass.length > 0 && (
        <div className="flex flex-wrap gap-3 py-2">
          {categoriesInClass.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveCategoryId(cat.id)}
              className={`px-5 py-1.5 rounded-md text-[11px] font-black transition-all uppercase tracking-wider border-2 ${
                activeCategoryId === cat.id
                  ? `${activeClass?.color || 'bg-blue-50'} border-slate-400 text-slate-900 shadow-sm`
                  : 'bg-white border-slate-200 text-slate-400 hover:border-slate-300 hover:text-slate-600'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>
      )}

      {activeCategory ? (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className={`px-6 py-4 ${activeClass?.color || 'bg-slate-50'} border-b border-slate-200 flex justify-between items-center`}>
            <div className="flex items-center gap-3">
              <div className="w-2.5 h-2.5 rounded-full bg-slate-800 shadow-sm opacity-50"></div>
              <h3 className="font-black text-slate-800 tracking-tight uppercase text-xs">
                {activeCategory.name}
              </h3>
            </div>
            <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
              Current Balance: <span className={`text-sm ml-2 ${activeCategory.balance < 0 ? 'text-red-600 font-black' : 'text-slate-900 font-black'}`}>
                {formatCurrency(activeCategory.balance)}
              </span>
            </div>
          </div>

          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left text-xs border-collapse">
              <thead className="bg-white border-b border-slate-100">
                <tr>
                  <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-tighter w-32">Date</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-tighter w-48">Account</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-tighter text-right w-32">Amount</th>
                  <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-tighter">Description</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredTransactions.length > 0 ? (
                  filteredTransactions.map(tx => {
                    const account = state.accounts.find(a => a.id === tx.accountId);
                    return (
                      <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                        <td className="px-6 py-3.5 text-slate-500 font-medium">
                          {formatDisplayDate(tx.date)}
                        </td>
                        <td className="px-4 py-3.5 text-slate-600 font-semibold uppercase text-[10px] tracking-tight">
                          {account?.name || (tx.accountId === 'internal' ? 'Internal Allocation' : 'N/A')}
                        </td>
                        <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                          {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                        </td>
                        <td className="px-6 py-3.5 text-slate-600 group-hover:text-slate-900 transition-colors">
                          {tx.description}
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={4} className="px-6 py-16 text-center text-slate-300 italic text-[11px] uppercase tracking-widest">
                      No transactions found for {activeCategory.name}.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-xl border-2 border-dashed border-slate-200 p-12 text-center">
          <p className="text-slate-400 uppercase text-[10px] font-bold tracking-widest italic">Select a category to view ledger</p>
        </div>
      )}
    </div>
  );
};

export default Ledgers;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Savings from './components/Savings';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance,
    // Layout Actions
    moveClassification,
    moveCategory,
    updateCategoryMetadata,
    updateClassificationMetadata
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction}
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'savings':
        return (
          <Savings 
            state={state}
            addTransaction={addTransaction}
            executeTransfer={executeTransfer}
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'acc-ledgers':
        return (
          <AccountLedgers 
            state={state} 
            onToggleCleared={toggleCleared} 
            onDeleteTransaction={deleteTransaction}
          />
        );
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            moveClassification={moveClassification}
            moveCategory={moveCategory}
            updateCategoryMetadata={updateCategoryMetadata}
            updateClassificationMetadata={updateClassificationMetadata}
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return <NetWorth state={state} onAddSnapshot={addInvestmentSnapshot} />;
      default:
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction} 
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey } from '../utils';
import { Target, TrendingUp, TrendingDown, Plus, Trash2, X, Wallet, Settings2, GripVertical, ChevronUp, ChevronDown, CheckCircle2, Palette } from 'lucide-react';

interface BudgetManagerProps {
  state: AppState;
  onUpdateBudget: (id: string, val: number) => void;
  onUpdateEstIncome: (val: number) => void;
  onAddCategory: (name: string, className: string, color: string) => void;
  onDeleteCategory: (id: string) => void;
  // Layout Editing Props
  moveClassification?: (id: string, direction: 'up' | 'down') => void;
  moveCategory?: (id: string, direction: 'up' | 'down') => void;
  updateCategoryMetadata?: (id: string, updates: any) => void;
  updateClassificationMetadata?: (id: string, updates: any) => void;
}

const COLOR_OPTIONS = [
  { name: 'Sky', value: 'bg-sky-100' },
  { name: 'Emerald', value: 'bg-emerald-100' },
  { name: 'Green', value: 'bg-green-100' },
  { name: 'Amber', value: 'bg-amber-100' },
  { name: 'Yellow', value: 'bg-yellow-100' },
  { name: 'Cyan', value: 'bg-cyan-100' },
  { name: 'Blue', value: 'bg-blue-100' },
  { name: 'Slate', value: 'bg-slate-100' },
  { name: 'Rose', value: 'bg-rose-100' },
  { name: 'Indigo', value: 'bg-indigo-100' },
];

const BudgetManager: React.FC<BudgetManagerProps> = ({ 
  state, 
  onUpdateBudget, 
  onUpdateEstIncome, 
  onAddCategory, 
  onDeleteCategory,
  moveClassification,
  moveCategory,
  updateCategoryMetadata,
  updateClassificationMetadata
}) => {
  const currentMonth = getMonthYearKey(new Date());
  const [showAddCat, setShowAddCat] = useState(false);
  const [isEditLayoutMode, setIsEditLayoutMode] = useState(false);
  const [newCat, setNewCat] = useState({ name: '', className: '', color: 'bg-slate-100' });
  const [deleteConfirm, setDeleteConfirm] = useState<{ id: string, name: string } | null>(null);

  const budgetStats = state.categories
    .filter(cat => !cat.deleted && cat.id !== 'cat-credit-payment' && cat.name !== 'Credit Payment')
    .map(cat => {
      const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
      const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
      const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
      return { ...cat, added, spent };
    });

  const incomeCategories = budgetStats.filter(c => c.classificationId === 'class-income');
  const expenseCategories = budgetStats.filter(c => !['class-income', 'class-transfers'].includes(c.classificationId));

  // Split classifications into Income and Others
  const incomeClass = state.classifications.find(cls => cls.id === 'class-income');
  const otherClassifications = state.classifications.filter(cls => !['class-transfers', 'class-income'].includes(cls.id));

  const totalTargetIncome = incomeCategories.reduce((sum, c) => sum + c.monthlyBudget, 0);
  const totalBudgetedExpenses = expenseCategories.reduce((sum, c) => sum + c.monthlyBudget, 0);

  React.useEffect(() => {
    if (totalTargetIncome !== state.estimatedMonthlyIncome) {
      onUpdateEstIncome(totalTargetIncome);
    }
  }, [totalTargetIncome, state.estimatedMonthlyIncome, onUpdateEstIncome]);

  const diff = totalTargetIncome - totalBudgetedExpenses;

  const handleAddCat = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.name && newCat.className) {
      onAddCategory(newCat.name, newCat.className, newCat.color);
      setNewCat({ name: '', className: '', color: 'bg-slate-100' });
      setShowAddCat(false);
    }
  };

  const confirmDelete = () => {
    if (deleteConfirm) {
      onDeleteCategory(deleteConfirm.id);
      setDeleteConfirm(null);
    }
  };

  const renderSortButtons = (id: string, idx: number, max: number, type: 'class' | 'cat') => {
    if (!isEditLayoutMode) return null;
    return (
      <div className="flex flex-col gap-0.5 ml-2">
        <button 
          onClick={() => type === 'class' ? moveClassification?.(id, 'up') : moveCategory?.(id, 'up')}
          disabled={idx === 0}
          className={`p-0.5 rounded hover:bg-slate-200 transition-colors ${idx === 0 ? 'opacity-20 cursor-not-allowed' : 'text-slate-500'}`}
        >
          <ChevronUp size={12} />
        </button>
        <button 
          onClick={() => type === 'class' ? moveClassification?.(id, 'down') : moveCategory?.(id, 'down')}
          disabled={idx === max}
          className={`p-0.5 rounded hover:bg-slate-200 transition-colors ${idx === max ? 'opacity-20 cursor-not-allowed' : 'text-slate-500'}`}
        >
          <ChevronDown size={12} />
        </button>
      </div>
    );
  };

  const renderClassificationTable = (cls: any, cats: any[], idx: number, maxIdx: number) => {
    const isIncome = cls.id === 'class-income';
    return (
      <div key={cls.id} className={`bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300`}>
        <div className={`px-6 py-4 ${isIncome ? 'bg-cyan-50' : cls.color} border-b border-slate-200 flex justify-between items-center`}>
          <div className="flex items-center gap-2">
            {isEditLayoutMode && <GripVertical size={16} className="text-slate-400 cursor-grab active:cursor-grabbing" />}
            {isEditLayoutMode ? (
              <input 
                type="text" 
                value={cls.name} 
                onChange={e => updateClassificationMetadata?.(cls.id, { name: e.target.value })}
                className="bg-transparent border-b border-slate-300 text-xs font-black uppercase tracking-widest focus:outline-none focus:border-blue-500 text-slate-800 w-48"
              />
            ) : (
              <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest flex items-center gap-2">
                {isIncome && <Wallet size={16} />} {cls.name}
              </h3>
            )}
            {renderSortButtons(cls.id, idx, maxIdx, 'class')}
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
            {isIncome ? 'Expected Monthly Cash Inflow' : 'Target Allocation'}
          </p>
        </div>
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest">
                {isEditLayoutMode ? 'Category Metadata' : isIncome ? 'Income Source' : 'Category'}
              </th>
              <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Target Amount</th>
              <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Actual Added (CM)</th>
              {!isIncome && <th className="px-4 py-4 font-bold text-slate-500 uppercase text-[10px] tracking-widest text-right">Spent (CM)</th>}
              <th className="px-4 py-4"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {cats.map((cat, catIdx) => (
              <tr key={cat.id} className="hover:bg-slate-50/50 group">
                <td className="px-6 py-3 font-medium text-slate-700">
                  {isEditLayoutMode ? (
                    <div className="flex items-center gap-4">
                      <GripVertical size={14} className="text-slate-300" />
                      <div className="space-y-2">
                        <input 
                          type="text" 
                          value={cat.name} 
                          onChange={e => updateCategoryMetadata?.(cat.id, { name: e.target.value })}
                          className="bg-white border border-slate-200 px-3 py-1.5 rounded-lg text-xs font-bold text-slate-700 focus:outline-none focus:ring-1 focus:ring-blue-500"
                        />
                        <select 
                          value={cat.classificationId} 
                          onChange={e => updateCategoryMetadata?.(cat.id, { classificationId: e.target.value })}
                          className="block w-full text-[9px] font-black uppercase tracking-widest text-slate-400 bg-transparent border-none focus:ring-0 cursor-pointer hover:text-blue-500"
                        >
                          {state.classifications.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                          ))}
                        </select>
                      </div>
                      {renderSortButtons(cat.id, catIdx, cats.length - 1, 'cat')}
                    </div>
                  ) : (
                    cat.name
                  )}
                </td>
                <td className="px-4 py-3 text-right">
                  <input 
                    type="number" 
                    disabled={isEditLayoutMode}
                    className={`w-24 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-right font-bold text-slate-900 focus:outline-none focus:ring-1 ${isIncome ? 'focus:ring-cyan-500' : 'focus:ring-blue-500'} ${isEditLayoutMode ? 'opacity-50' : ''}`}
                    value={cat.monthlyBudget}
                    onChange={e => onUpdateBudget(cat.id, parseFloat(e.target.value) || 0)}
                  />
                </td>
                <td className={`px-4 py-3 text-right font-bold ${isIncome ? 'text-cyan-600' : 'text-blue-500'}`}>
                  {formatCurrency(cat.added, true)}
                </td>
                {!isIncome && (
                  <td className={`px-4 py-3 text-right font-bold ${cat.spent < 0 ? 'text-red-500' : 'text-slate-500'}`}>
                    {cat.spent === 0 ? '-' : formatCurrency(cat.spent, true)}
                  </td>
                )}
                <td className="px-4 py-3 text-right">
                  <button 
                    onClick={() => setDeleteConfirm({ id: cat.id, name: cat.name })}
                    className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-red-50"
                  >
                    <Trash2 size={14} />
                  </button>
                </td>
              </tr>
            ))}
            {cats.length === 0 && (
              <tr>
                <td colSpan={5} className="px-6 py-8 text-center text-slate-300 italic text-[10px] uppercase tracking-widest">
                  Empty Classification
                </td>
              </tr>
            )}
          </tbody>
          <tfoot className={`font-bold ${isIncome ? 'bg-cyan-900' : 'bg-slate-900'} text-white`}>
            <tr>
              <td className="px-6 py-4 uppercase tracking-widest text-xs">Subtotal: {cls.name}</td>
              <td className="px-4 py-4 text-right text-lg">
                {formatCurrency(cats.reduce((sum, c) => sum + c.monthlyBudget, 0), true)}
              </td>
              <td className="px-4 py-4 text-right">
                {formatCurrency(cats.reduce((sum, c) => sum + (c.added || 0), 0), true)}
              </td>
              {!isIncome && (
                <td className="px-4 py-4 text-right">
                  {formatCurrency(cats.reduce((sum, c) => sum + (c.spent || 0), 0), true)}
                </td>
              )}
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>
    );
  };

  return (
    <div className="space-y-8 pb-32">
      {/* 0. Top Controls */}
      <div className="flex flex-wrap gap-4 items-center justify-between border-b border-slate-200 pb-6">
        <div className="flex gap-3">
          <button 
            onClick={() => setShowAddCat(true)} 
            className="flex items-center gap-2 bg-slate-900 text-white px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
          >
            <Plus size={14} /> Add Category
          </button>
          <button 
            onClick={() => setIsEditLayoutMode(!isEditLayoutMode)} 
            className={`flex items-center gap-2 px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
              isEditLayoutMode 
                ? 'bg-blue-600 text-white shadow-lg' 
                : 'bg-white text-slate-500 border border-slate-200 hover:border-slate-400'
            }`}
          >
            {isEditLayoutMode ? <><CheckCircle2 size={14} /> Save Layout</> : <><Settings2 size={14} /> Edit Layout</>}
          </button>
        </div>
        {isEditLayoutMode && (
          <p className="text-[10px] font-bold text-blue-500 uppercase tracking-[0.2em] animate-pulse">
            Edit Mode Active: Reorder, Rename, or Re-group Categories
          </p>
        )}
      </div>

      {/* 1. Income Table (Forced at Top) */}
      {incomeClass && renderClassificationTable(incomeClass, incomeCategories, 0, 0)}

      {/* 2. Summary Boxes (Now in the Middle) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 py-4">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-100 text-blue-600 rounded-lg"><Target size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Est. Monthly Income</p>
            <p className="text-xl font-bold text-slate-800">{formatCurrency(totalTargetIncome, true)}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-green-100 text-green-600 rounded-lg"><TrendingUp size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total Budgeted Expenses</p>
            <p className="text-xl font-bold text-slate-800">{formatCurrency(totalBudgetedExpenses, true)}</p>
          </div>
        </div>
        <div className={`bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4 border-l-4 ${diff < 0 ? 'border-l-red-500' : 'border-l-green-500'}`}>
          <div className={`p-3 rounded-lg ${diff < 0 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}><TrendingDown size={24} /></div>
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Remaining to Allocate</p>
            <p className={`text-xl font-bold ${diff < 0 ? 'text-red-500' : 'text-slate-800'}`}>{formatCurrency(diff, true)}</p>
          </div>
        </div>
      </div>

      {/* 3. Expense Tables (Loop through the rest) */}
      <div className="space-y-8">
        {otherClassifications.map((cls, clsIdx) => (
          renderClassificationTable(
            cls, 
            expenseCategories.filter(c => c.classificationId === cls.id), 
            clsIdx, 
            otherClassifications.length - 1
          )
        ))}
      </div>

      {/* Modals */}
      {showAddCat && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-6 transform transition-all scale-100 border border-slate-200">
            <h4 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
              <Plus size={20} className="text-blue-500" /> Define New Category
            </h4>
            <form onSubmit={handleAddCat} className="space-y-6">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Category Name</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none font-medium" 
                  value={newCat.name} 
                  onChange={e => setNewCat({...newCat, name: e.target.value})} 
                  placeholder="e.g. Vacation Fund" 
                  autoFocus
                  required 
                />
              </div>

              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Group / Classification</label>
                <select 
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none" 
                  value={newCat.className} 
                  onChange={e => setNewCat({...newCat, className: e.target.value})} 
                  required
                >
                  <option value="">Select Group...</option>
                  {state.classifications.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                  <option value="NEW">+ Create New Group</option>
                </select>
                {newCat.className === 'NEW' && (
                  <input 
                    type="text" 
                    className="w-full px-4 py-2.5 mt-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-1 focus:ring-blue-300" 
                    placeholder="New Group Name" 
                    onChange={e => setNewCat({...newCat, className: e.target.value})} 
                  />
                )}
              </div>

              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                  <Palette size={12} /> Branding Color
                </label>
                <div className="grid grid-cols-5 gap-3">
                  {COLOR_OPTIONS.map(opt => (
                    <button
                      key={opt.value}
                      type="button"
                      onClick={() => setNewCat({...newCat, color: opt.value})}
                      className={`h-10 rounded-lg transition-all border-2 ${opt.value} ${newCat.color === opt.value ? 'border-slate-900 scale-110 shadow-md' : 'border-transparent hover:border-slate-300'}`}
                      title={opt.name}
                    />
                  ))}
                </div>
              </div>

              <div className="flex gap-2 justify-end pt-6 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setShowAddCat(false)} 
                  className="px-6 py-2.5 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="px-10 py-2.5 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
                >
                  Create Category
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {deleteConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <Trash2 size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight">
                Are you sure you want to delete <span className="text-red-600 font-black">"{deleteConfirm.name}"</span>?
              </h4>
              <p className="text-[11px] text-slate-500 uppercase tracking-widest font-bold leading-relaxed">
                If data exists, it will be hidden but kept for history. If no data exists, it will be removed permanently.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  No, Keep it
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BudgetManager;

import { useState, useCallback } from 'react';
import { AppState, Transaction, Category, InvestmentSnapshot, Classification, Account, AccountType } from '../types';
import { INITIAL_DATA } from '../constants';
import { generateId } from '../utils';

export const useFinance = () => {
  const [state, setState] = useState<AppState>(() => {
    const base = JSON.parse(JSON.stringify(INITIAL_DATA)) as AppState;
    base.transactions.forEach(tx => {
      const cat = base.categories.find(c => c.id === tx.categoryId);
      if (cat) cat.balance += tx.amount;
      if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
        const acc = base.accounts.find(a => a.id === tx.accountId);
        if (acc) acc.balance += tx.amount;
      }
    });
    return base;
  });

  const setCategoryBalance = useCallback((catId: string, balance: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, balance } : c)
    }));
  }, []);

  const setAccountBalance = useCallback((accId: string, balance: number) => {
    setState(prev => ({
      ...prev,
      accounts: prev.accounts.map(a => a.id === accId ? { ...a, balance } : a)
    }));
  }, []);

  const addTransaction = useCallback((txData: Omit<Transaction, 'id'>) => {
    setState(prev => {
      const newTransactions: Transaction[] = [];
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];

      const processSingle = (data: Omit<Transaction, 'id'>) => {
        const id = generateId();
        const tx = { ...data, id, cleared: false };
        newTransactions.push(tx);

        updatedCategories = updatedCategories.map(cat => {
          if (cat.id === tx.categoryId) {
            return { ...cat, balance: cat.balance + tx.amount };
          }
          return cat;
        });

        if (tx.accountId && !tx.accountId.startsWith('internal') && tx.accountId !== 'none') {
          updatedAccounts = updatedAccounts.map(acc => {
            if (acc.id === tx.accountId) {
              return { ...acc, balance: acc.balance + tx.amount };
            }
            return acc;
          });
        }
      };

      if (txData.type === 'Update Budget (Allocation)' as any) {
        processSingle({ ...txData, accountId: 'internal' });
      } else {
        processSingle(txData);
        const selectedCat = prev.categories.find(c => c.id === txData.categoryId);
        if (txData.type === 'Income' || (selectedCat?.classificationId === 'class-income' && txData.amount > 0)) {
          const tithingCategory = prev.categories.find(c => c.name === 'Tithing');
          if (tithingCategory) {
            processSingle({
              ...txData,
              categoryId: tithingCategory.id,
              amount: txData.amount * 0.1,
              description: `Tithing from: ${txData.description}`,
              type: 'Standard'
            });
          }
        }
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts,
      };
    });
  }, []);

  const deleteTransaction = useCallback((txId: string) => {
    setState(prev => {
      const txToDelete = prev.transactions.find(t => t.id === txId);
      if (!txToDelete) return prev;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === txToDelete.categoryId) {
          return { ...cat, balance: cat.balance - txToDelete.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === txToDelete.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - txToDelete.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const undoLastTransaction = useCallback(() => {
    setState(prev => {
      if (prev.transactions.length === 0) return prev;
      const lastTx = prev.transactions[prev.transactions.length - 1];
      const txId = lastTx.id;

      const updatedTransactions = prev.transactions.filter(t => t.id !== txId);
      const updatedCategories = prev.categories.map(cat => {
        if (cat.id === lastTx.categoryId) {
          return { ...cat, balance: cat.balance - lastTx.amount };
        }
        return cat;
      });

      const updatedAccounts = prev.accounts.map(acc => {
        if (acc.id === lastTx.accountId && !acc.id.startsWith('internal')) {
          return { ...acc, balance: acc.balance - lastTx.amount };
        }
        return acc;
      });

      return {
        ...prev,
        transactions: updatedTransactions,
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const deleteCategory = useCallback((catId: string) => {
    setState(prev => {
      const hasTransactions = prev.transactions.some(t => t.categoryId === catId);
      if (hasTransactions) {
        return {
          ...prev,
          categories: prev.categories.map(c => c.id === catId ? { ...c, deleted: true } : c),
        };
      } else {
        return {
          ...prev,
          categories: prev.categories.filter(c => c.id !== catId),
        };
      }
    });
  }, []);

  const toggleCleared = useCallback((txId: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === txId ? { ...t, cleared: !t.cleared } : t)
    }));
  }, []);

  const updateBudget = useCallback((catId: string, amount: number) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === catId ? { ...c, monthlyBudget: amount } : c)
    }));
  }, []);

  const setEstIncome = useCallback((amount: number) => {
    setState(prev => ({ ...prev, estimatedMonthlyIncome: amount }));
  }, []);

  const addInvestmentSnapshot = useCallback((snapshot: InvestmentSnapshot) => {
    setState(prev => {
      const filtered = prev.investmentSnapshots.filter(s => !(s.monthKey === snapshot.monthKey && s.accountId === snapshot.accountId));
      return {
        ...prev,
        investmentSnapshots: [...filtered, snapshot]
      };
    });
  }, []);

  const executeTransfer = useCallback((params: {
    type: string;
    date: string;
    amount: number;
    description: string;
    fromAccountId?: string;
    toAccountId?: string;
    fromCategoryId?: string;
    toCategoryId?: string;
  }) => {
    const { type, date, amount, description, fromAccountId, toAccountId, fromCategoryId, toCategoryId } = params;

    setState(prev => {
      let updatedCategories = [...prev.categories];
      let updatedAccounts = [...prev.accounts];
      const newTransactions: Transaction[] = [];

      const recordTx = (accId: string | undefined, catId: string | undefined, val: number, desc: string, txType: any = 'Standard') => {
        if (!accId && !catId) return;
        const tx: Transaction = {
          id: generateId(),
          date,
          amount: val,
          description: desc,
          accountId: accId || 'internal',
          categoryId: catId || 'none',
          type: txType,
          cleared: false,
          fromAccountId,
          toAccountId,
          fromCategoryId,
          toCategoryId
        };
        newTransactions.push(tx);

        if (catId && catId !== 'none') {
          updatedCategories = updatedCategories.map(c => c.id === catId ? { ...c, balance: c.balance + val } : c);
        }
        if (accId && !accId.startsWith('internal') && accId !== 'none') {
          updatedAccounts = updatedAccounts.map(a => a.id === accId ? { ...a, balance: a.balance + val } : a);
        }
      };

      switch (type) {
        case 'Category Transfer':
          recordTx(fromAccountId, fromCategoryId, -amount, description, 'Category Transfer');
          recordTx(toAccountId, toCategoryId, amount, description, 'Category Transfer');
          break;
        case 'Transfer to Savings':
          recordTx(undefined, toCategoryId, amount, description, 'Transfer to Savings');
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer to Savings');
          break;
        case 'Transfer to Checking':
          recordTx(toAccountId, toCategoryId, amount, description, 'Transfer to Checking');
          recordTx(undefined, fromCategoryId, -amount, description, 'Transfer to Checking');
          break;
        case 'Credit Payment':
          recordTx(fromAccountId, undefined, -amount, description, 'Credit Payment');
          recordTx(toAccountId, undefined, amount, description, 'Credit Payment');
          break;
        case 'Transfer between Checking':
          recordTx(fromAccountId, undefined, -amount, description, 'Transfer between Checking');
          recordTx(toAccountId, undefined, amount, description, 'Transfer between Checking');
          break;
        case 'Update Budget (Allocation)':
          recordTx(undefined, toCategoryId, amount, description, 'Update Budget (Allocation)');
          break;
      }

      return {
        ...prev,
        transactions: [...prev.transactions, ...newTransactions],
        categories: updatedCategories,
        accounts: updatedAccounts
      };
    });
  }, []);

  const addCategory = useCallback((name: string, classificationName: string, color: string) => {
    setState(prev => {
      let classId = prev.classifications.find(c => c.name === classificationName)?.id;
      let newClassifications = [...prev.classifications];
      if (!classId) {
        classId = `class-${generateId()}`;
        newClassifications.push({ id: classId, name: classificationName, color: color || 'bg-slate-100' });
      }
      const newCategory: Category = { id: `cat-${generateId()}`, name, classificationId: classId, balance: 0, monthlyBudget: 0 };
      return { ...prev, classifications: newClassifications, categories: [...prev.categories, newCategory] };
    });
  }, []);

  // --- Layout & Account Editing Actions ---

  const moveClassification = useCallback((id: string, direction: 'up' | 'down') => {
    setState(prev => {
      const idx = prev.classifications.findIndex(c => c.id === id);
      if (idx === -1) return prev;
      if (direction === 'up' && idx === 0) return prev;
      if (direction === 'down' && idx === prev.classifications.length - 1) return prev;

      const newClasses = [...prev.classifications];
      const offset = direction === 'up' ? -1 : 1;
      const [moved] = newClasses.splice(idx, 1);
      newClasses.splice(idx + offset, 0, moved);
      return { ...prev, classifications: newClasses };
    });
  }, []);

  const moveCategory = useCallback((id: string, direction: 'up' | 'down') => {
    setState(prev => {
      const cat = prev.categories.find(c => c.id === id);
      if (!cat) return prev;
      const classId = cat.classificationId;

      const classCategories = prev.categories.filter(c => c.classificationId === classId);
      const catIdx = classCategories.findIndex(c => c.id === id);

      if (direction === 'up' && catIdx === 0) return prev;
      if (direction === 'down' && catIdx === classCategories.length - 1) return prev;

      const newCategories = [...prev.categories];
      const offset = direction === 'up' ? -1 : 1;

      const globalIdx = newCategories.findIndex(c => c.id === id);
      const targetCatId = classCategories[catIdx + offset].id;
      const targetGlobalIdx = newCategories.findIndex(c => c.id === targetCatId);

      const [moved] = newCategories.splice(globalIdx, 1);
      newCategories.splice(targetGlobalIdx, 0, moved);

      return { ...prev, categories: newCategories };
    });
  }, []);

  const updateCategoryMetadata = useCallback((id: string, updates: Partial<Category>) => {
    setState(prev => ({
      ...prev,
      categories: prev.categories.map(c => c.id === id ? { ...c, ...updates } : c)
    }));
  }, []);

  const updateClassificationMetadata = useCallback((id: string, updates: Partial<Classification>) => {
    setState(prev => ({
      ...prev,
      classifications: prev.classifications.map(c => c.id === id ? { ...c, ...updates } : c)
    }));
  }, []);

  const addAccount = useCallback((name: string, type: AccountType) => {
    setState(prev => {
      const newAccount: Account = {
        id: `acc-${generateId()}`,
        name,
        type,
        balance: 0
      };
      return { ...prev, accounts: [...prev.accounts, newAccount] };
    });
  }, []);

  const moveAccount = useCallback((id: string, direction: 'up' | 'down') => {
    setState(prev => {
      const idx = prev.accounts.findIndex(a => a.id === id);
      if (idx === -1) return prev;
      if (direction === 'up' && idx === 0) return prev;
      if (direction === 'down' && idx === prev.accounts.length - 1) return prev;

      const newAccounts = [...prev.accounts];
      const offset = direction === 'up' ? -1 : 1;
      const [moved] = newAccounts.splice(idx, 1);
      newAccounts.splice(idx + offset, 0, moved);
      return { ...prev, accounts: newAccounts };
    });
  }, []);

  const updateAccountMetadata = useCallback((id: string, updates: Partial<Account>) => {
    setState(prev => ({
      ...prev,
      accounts: prev.accounts.map(a => a.id === id ? { ...a, ...updates } : a)
    }));
  }, []);

  return {
    state,
    addTransaction,
    executeTransfer,
    addCategory,
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared,
    updateBudget,
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance,
    // Layout helpers
    moveClassification,
    moveCategory,
    updateCategoryMetadata,
    updateClassificationMetadata,
    // Account helpers
    addAccount,
    moveAccount,
    updateAccountMetadata
  };
};

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Savings from './components/Savings';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance,
    // Layout Actions
    moveClassification,
    moveCategory,
    updateCategoryMetadata,
    updateClassificationMetadata,
    // Account Actions
    addAccount,
    moveAccount,
    updateAccountMetadata
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction}
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'savings':
        return (
          <Savings 
            state={state}
            addTransaction={addTransaction}
            executeTransfer={executeTransfer}
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'acc-ledgers':
        return (
          <AccountLedgers 
            state={state} 
            onToggleCleared={toggleCleared} 
            onDeleteTransaction={deleteTransaction}
            onAddAccount={addAccount}
            onMoveAccount={moveAccount}
            onUpdateAccount={updateAccountMetadata}
          />
        );
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            moveClassification={moveClassification}
            moveCategory={moveCategory}
            updateCategoryMetadata={updateCategoryMetadata}
            updateClassificationMetadata={updateClassificationMetadata}
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return <NetWorth state={state} onAddSnapshot={addInvestmentSnapshot} />;
      default:
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction} 
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState, Transaction, Account, AccountType } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { CheckCircle, Circle, Trash2, X, AlertTriangle, Layers, ArrowRight, Plus, Edit3, Settings2, GripVertical, ChevronUp, ChevronDown, CheckCircle2 } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
  onAddAccount: (name: string, type: AccountType) => void;
  onMoveAccount: (id: string, direction: 'up' | 'down') => void;
  onUpdateAccount: (id: string, updates: Partial<Account>) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ 
  state, 
  onToggleCleared, 
  onDeleteTransaction,
  onAddAccount,
  onMoveAccount,
  onUpdateAccount
}) => {
  const [activeAccId, setActiveAccId] = useState('all'); 
  const [deleteTxConfirm, setDeleteTxConfirm] = useState<Transaction | null>(null);
  const [showAddAcc, setShowAddAcc] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [newAcc, setNewAcc] = useState({ name: '', type: 'Checking' as AccountType });

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'all': { name: 'All Activity' },
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal') || activeAccId === 'all';
  const isAllActivity = activeAccId === 'all';
  const isTransferView = activeAccId === 'internal-transfers';

  const activeAccount = virtualAccountMap[activeAccId] 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  // Cleared column logic: Only for individual Credit accounts.
  const showClearedColumn = !isVirtual && !isTransferView && activeAccount?.type === 'Credit';

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'all') return true;
      if (activeAccId === 'internal') return t.type === 'Update Budget (Allocation)';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const confirmDelete = () => {
    if (deleteTxConfirm) {
      onDeleteTransaction(deleteTxConfirm.id);
      setDeleteTxConfirm(null);
    }
  };

  const getAccountName = (id?: string) => {
    if (!id) return '-';
    if (id === 'internal') return 'Internal';
    if (id === 'none') return '-';
    return state.accounts.find(a => a.id === id)?.name || id;
  };

  const getCategoryName = (id?: string) => {
    if (!id) return '-';
    if (id === 'none') return '-';
    return state.categories.find(c => c.id === id)?.name || id;
  };

  const handleAddAccount = (e: React.FormEvent) => {
    e.preventDefault();
    if (newAcc.name && newAcc.type) {
      onAddAccount(newAcc.name, newAcc.type);
      setNewAcc({ name: '', type: 'Checking' });
      setShowAddAcc(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation Header matching screenshot style */}
      <div className="bg-white p-3 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar py-1">
          {/* All Activity Tab */}
          <button
            onClick={() => setActiveAccId('all')}
            className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest flex items-center gap-2 shrink-0 ${
              activeAccId === 'all' 
                ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/20' 
                : 'bg-white text-slate-400 hover:text-slate-600'
            }`}
          >
            <Layers size={14} />
            All Activity
          </button>

          <div className="w-[1px] h-6 bg-slate-200 mx-1" />

          {/* Dynamic Account Tabs */}
          {state.accounts.map((acc, idx) => (
            <div key={acc.id} className="flex items-center gap-1 shrink-0">
              {isEditMode && (
                <div className="flex flex-col gap-0.5 px-1">
                  <button disabled={idx === 0} onClick={() => onMoveAccount(acc.id, 'up')} className={`p-0.5 rounded ${idx === 0 ? 'opacity-20' : 'text-slate-400 hover:bg-slate-100'}`}><ChevronUp size={10} /></button>
                  <button disabled={idx === state.accounts.length - 1} onClick={() => onMoveAccount(acc.id, 'down')} className={`p-0.5 rounded ${idx === state.accounts.length - 1 ? 'opacity-20' : 'text-slate-400 hover:bg-slate-100'}`}><ChevronDown size={10} /></button>
                </div>
              )}
              <button
                onClick={() => setActiveAccId(acc.id)}
                className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest border border-transparent ${
                  activeAccId === acc.id 
                    ? 'bg-slate-900 text-white shadow-xl shadow-slate-900/20' 
                    : 'bg-white text-slate-400 hover:border-slate-200 hover:text-slate-600'
                }`}
              >
                {isEditMode ? (
                  <input 
                    type="text" 
                    className="bg-transparent border-b border-white/20 focus:outline-none w-24"
                    value={acc.name}
                    onChange={(e) => onUpdateAccount(acc.id, { name: e.target.value })}
                  />
                ) : (
                  acc.name
                )}
              </button>
            </div>
          ))}

          {/* Add Account Button */}
          <button 
            onClick={() => setShowAddAcc(true)}
            className="w-10 h-10 rounded-xl bg-slate-50 text-slate-400 flex items-center justify-center hover:bg-slate-100 transition-colors shrink-0"
          >
            <Plus size={18} />
          </button>
        </div>

        {/* Right Side Virtual Tabs */}
        <div className="flex gap-2 items-center ml-4 shrink-0">
          <button
            onClick={() => setActiveAccId('internal')}
            className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeAccId === 'internal' 
                ? 'bg-slate-900 text-white shadow-xl' 
                : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Allocation
          </button>
          <button
            onClick={() => setActiveAccId('internal-transfers')}
            className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeAccId === 'internal-transfers' 
                ? 'bg-slate-900 text-white shadow-xl' 
                : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Transfers
          </button>
          <div className="w-[1px] h-6 bg-slate-200 mx-2" />
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2.5 rounded-xl transition-all ${isEditMode ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}
          >
            {isEditMode ? <CheckCircle2 size={18} /> : <Settings2 size={18} />}
          </button>
        </div>
      </div>

      {/* Main Ledger Display */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {activeAccId === 'all' ? 'Full Composite Ledger' : isVirtual ? `Internal Budget ${activeAccount?.name} Activity` : `${activeAccount?.name} Activity`}
          </h3>
          {(!isVirtual && activeAccId !== 'all') && (
            <div className="text-[10px] font-black uppercase tracking-widest text-slate-500">
              Account Balance: <span className={`text-sm ml-2 ${activeAccount?.balance < 0 ? 'text-red-500' : 'text-slate-900 font-black'}`}>
                {formatCurrency(activeAccount?.balance || 0)}
              </span>
            </div>
          )}
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-xs border-collapse">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                {isTransferView ? (
                  <>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] w-24">Date</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Category From</th>
                    <th className="px-2 py-4 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Category To</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account From</th>
                    <th className="px-2 py-4 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account To</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                  </>
                ) : (
                  <>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Category</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] w-24">Date</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Description</th>
                    {showClearedColumn && <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-center">Cleared</th>}
                  </>
                )}
                <th className="px-4 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map((tx) => {
                  const cat = state.categories.find(c => c.id === tx.categoryId);
                  const acc = state.accounts.find(a => a.id === tx.accountId);
                  const accName = acc ? acc.name : (tx.accountId === 'internal' ? 'Allocation' : tx.accountId);
                  const isCredit = acc?.type === 'Credit';
                  const isTxVirtual = tx.accountId.startsWith('internal');

                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      {isTransferView ? (
                        <>
                          <td className="px-6 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3.5 text-slate-600 font-medium">{getCategoryName(tx.fromCategoryId)}</td>
                          <td className="px-2 py-3.5 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3.5 text-slate-600 font-medium">{getCategoryName(tx.toCategoryId)}</td>
                          <td className="px-4 py-3.5">
                            <span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.fromAccountId)}</span>
                          </td>
                          <td className="px-2 py-3.5 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3.5">
                            <span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.toAccountId)}</span>
                          </td>
                          <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {formatCurrency(tx.amount)}
                          </td>
                        </>
                      ) : (
                        <>
                          <td className="px-6 py-3.5 text-slate-600 font-medium">
                            {cat?.name || 'Uncategorized'}
                            {cat?.deleted && <span className="ml-2 text-[8px] bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded uppercase font-black">Archived</span>}
                          </td>
                          <td className="px-4 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3.5">
                            <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase tracking-tight ${
                              isTxVirtual ? 'bg-slate-100 text-slate-400' : 
                              acc?.type === 'Credit' ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'
                            }`}>
                              {accName}
                            </span>
                          </td>
                          <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                          </td>
                          <td className="px-6 py-3.5 text-slate-600 truncate max-w-[200px]">{tx.description}</td>
                          {showClearedColumn && (
                            <td className="px-6 py-3.5 text-center">
                              <button 
                                onClick={() => onToggleCleared(tx.id)}
                                disabled={!isCredit || isTxVirtual}
                                className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                                  (!isCredit || isTxVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                                  tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                                }`}
                              >
                                {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                              </button>
                            </td>
                          )}
                        </>
                      )}
                      <td className="px-4 py-3.5 text-right">
                        {isAllActivity && (
                          <button 
                            onClick={() => setDeleteTxConfirm(tx)}
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                          >
                            <Trash2 size={14} />
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={isTransferView ? 9 : (showClearedColumn ? 7 : 6)} className="px-6 py-24 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-black">No transactions recorded in this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Account Modal */}
      {showAddAcc && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-[110] p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-8 transform transition-all scale-100 border border-slate-200">
            <h4 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-3">
              <Plus size={24} className="text-blue-500" /> New Account / Card
            </h4>
            <form onSubmit={handleAddAccount} className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Account Name</label>
                <input 
                  type="text" 
                  className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none font-bold text-sm" 
                  value={newAcc.name} 
                  onChange={e => setNewAcc({...newAcc, name: e.target.value})} 
                  placeholder="e.g. AMEX Gold" 
                  autoFocus
                  required 
                />
              </div>

              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Account Type</label>
                <div className="grid grid-cols-3 gap-2">
                  {(['Checking', 'Savings', 'Credit'] as AccountType[]).map(type => (
                    <button
                      key={type}
                      type="button"
                      onClick={() => setNewAcc({...newAcc, type})}
                      className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${
                        newAcc.type === type 
                          ? 'border-blue-500 bg-blue-50 text-blue-600' 
                          : 'border-slate-100 bg-slate-50 text-slate-400 hover:border-slate-200'
                      }`}
                    >
                      {type}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 justify-end pt-6 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setShowAddAcc(false)} 
                  className="flex-1 px-6 py-3 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-1 px-10 py-3 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
                >
                  Create
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteTxConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <AlertTriangle size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight uppercase tracking-tight">
                Delete Transaction?
              </h4>
              <div className="p-4 bg-slate-50 rounded-xl space-y-2 text-left">
                <div className="flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase">
                  <span>{formatDisplayDate(deleteTxConfirm.date)}</span>
                  <span className={deleteTxConfirm.amount < 0 ? 'text-red-500' : 'text-blue-600'}>
                    {formatCurrency(deleteTxConfirm.amount)}
                  </span>
                </div>
                <p className="text-xs font-black text-slate-700 truncate uppercase tracking-tight">{deleteTxConfirm.description || 'No description'}</p>
                <div className="flex justify-between items-center border-t border-slate-200 pt-2 mt-2">
                  <p className="text-[9px] text-slate-400 uppercase font-black tracking-widest">
                    Cat: {state.categories.find(c => c.id === deleteTxConfirm.categoryId)?.name || 'N/A'}
                  </p>
                  <p className="text-[9px] text-slate-400 uppercase font-black tracking-widest">
                    Acc: {state.accounts.find(a => a.id === deleteTxConfirm.accountId)?.name || 'Allocation'}
                  </p>
                </div>
              </div>
              <p className="text-[11px] text-slate-400 uppercase tracking-widest font-black leading-relaxed">
                Reversing this action will update all category and account balances.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteTxConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
            <button 
              onClick={() => setDeleteTxConfirm(null)}
              className="absolute top-4 right-4 p-1 text-slate-300 hover:text-slate-600 transition-colors"
            >
              <X size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountLedgers;

import React, { useState } from 'react';
import { AppState, Transaction, Account, AccountType } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { CheckCircle, Circle, Trash2, X, AlertTriangle, Layers, ArrowRight, Plus, Settings2, ChevronUp, ChevronDown, CheckCircle2, Landmark, CreditCard, PiggyBank } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
  onAddAccount: (name: string, type: AccountType) => void;
  onMoveAccount: (id: string, direction: 'up' | 'down') => void;
  onUpdateAccount: (id: string, updates: Partial<Account>) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ 
  state, 
  onToggleCleared, 
  onDeleteTransaction,
  onAddAccount,
  onMoveAccount,
  onUpdateAccount
}) => {
  const [activeAccId, setActiveAccId] = useState('all'); 
  const [deleteTxConfirm, setDeleteTxConfirm] = useState<Transaction | null>(null);
  const [showAddAcc, setShowAddAcc] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [newAcc, setNewAcc] = useState({ name: '', type: 'Checking' as AccountType });

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'all': { name: 'All Activity' },
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal') || activeAccId === 'all';
  const isAllActivity = activeAccId === 'all';
  const isTransferView = activeAccId === 'internal-transfers';

  const activeAccount = virtualAccountMap[activeAccId] 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  // Cleared column logic: Only for individual Credit accounts.
  const showClearedColumn = !isVirtual && !isTransferView && activeAccount?.type === 'Credit';

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'all') return true;
      if (activeAccId === 'internal') return t.type === 'Update Budget (Allocation)';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const confirmDelete = () => {
    if (deleteTxConfirm) {
      onDeleteTransaction(deleteTxConfirm.id);
      setDeleteTxConfirm(null);
    }
  };

  const getAccountName = (id?: string) => {
    if (!id) return '-';
    if (id === 'internal') return 'Internal';
    if (id === 'none') return '-';
    return state.accounts.find(a => a.id === id)?.name || id;
  };

  const getCategoryName = (id?: string) => {
    if (!id) return '-';
    if (id === 'none') return '-';
    return state.categories.find(c => c.id === id)?.name || id;
  };

  const handleAddAccount = (e: React.FormEvent) => {
    e.preventDefault();
    if (newAcc.name && newAcc.type) {
      onAddAccount(newAcc.name, newAcc.type);
      setNewAcc({ name: '', type: 'Checking' });
      setShowAddAcc(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation Header matching screenshot style */}
      <div className="bg-white p-2 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar py-1 px-1">
          {/* All Activity Tab */}
          <button
            onClick={() => setActiveAccId('all')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest flex items-center gap-2 shrink-0 ${
              activeAccId === 'all' 
                ? 'bg-slate-900 text-white shadow-xl' 
                : 'bg-white text-slate-400 hover:text-slate-600'
            }`}
          >
            <Layers size={14} />
            All Activity
          </button>

          <div className="w-[1px] h-6 bg-slate-200 mx-1 shrink-0" />

          {/* Dynamic Account Tabs */}
          {state.accounts.map((acc, idx) => (
            <div key={acc.id} className="flex items-center gap-1 shrink-0">
              <button
                onClick={() => setActiveAccId(acc.id)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest border border-slate-100 ${
                  activeAccId === acc.id 
                    ? 'bg-slate-900 text-white shadow-xl' 
                    : 'bg-white text-slate-400 hover:border-slate-300 hover:text-slate-600'
                } flex items-center gap-2`}
              >
                {isEditMode ? (
                  <div className="flex items-center gap-2">
                    <input 
                      type="text" 
                      className="bg-slate-700/50 text-white border-none rounded px-2 py-0.5 w-24 focus:ring-0"
                      value={acc.name}
                      autoFocus={activeAccId === acc.id}
                      onClick={(e) => e.stopPropagation()}
                      onChange={(e) => onUpdateAccount(acc.id, { name: e.target.value })}
                    />
                    <select
                      className="bg-slate-700/50 text-white border-none rounded text-[8px] p-0.5 focus:ring-0"
                      value={acc.type}
                      onClick={(e) => e.stopPropagation()}
                      onChange={(e) => onUpdateAccount(acc.id, { type: e.target.value as AccountType })}
                    >
                      <option value="Checking">CHK</option>
                      <option value="Savings">SAV</option>
                      <option value="Credit">CRD</option>
                      <option value="Investment">INV</option>
                    </select>
                    <div className="flex flex-col gap-0.5 ml-1">
                      <button disabled={idx === 0} onClick={(e) => { e.stopPropagation(); onMoveAccount(acc.id, 'up'); }} className="p-0.5 hover:bg-slate-700 rounded"><ChevronUp size={10} /></button>
                      <button disabled={idx === state.accounts.length - 1} onClick={(e) => { e.stopPropagation(); onMoveAccount(acc.id, 'down'); }} className="p-0.5 hover:bg-slate-700 rounded"><ChevronDown size={10} /></button>
                    </div>
                  </div>
                ) : (
                  acc.name
                )}
              </button>
            </div>
          ))}

          {/* Add Account Button */}
          <button 
            onClick={() => setShowAddAcc(true)}
            className="w-10 h-10 rounded-xl bg-slate-50 text-slate-400 flex items-center justify-center hover:bg-slate-100 transition-colors shrink-0"
          >
            <Plus size={18} />
          </button>
        </div>

        {/* Right Side Virtual Tabs */}
        <div className="flex gap-2 items-center ml-4 shrink-0 px-2">
          <button
            onClick={() => setActiveAccId('internal')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeAccId === 'internal' 
                ? 'bg-slate-100 text-slate-900' 
                : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Allocation
          </button>
          <button
            onClick={() => setActiveAccId('internal-transfers')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeAccId === 'internal-transfers' 
                ? 'bg-slate-100 text-slate-900' 
                : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Transfers
          </button>
          <div className="w-[1px] h-6 bg-slate-200 mx-1" />
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-xl transition-all ${isEditMode ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}
          >
            {isEditMode ? <CheckCircle2 size={20} /> : <Settings2 size={20} />}
          </button>
        </div>
      </div>

      {/* Main Ledger Display */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {activeAccId === 'all' ? 'All Ledger Activity' : isVirtual ? `Internal ${activeAccount?.name} View` : `${activeAccount?.name} Ledger`}
          </h3>
          {(!isVirtual && activeAccId !== 'all') && (
            <div className="text-[10px] font-black uppercase tracking-widest text-slate-500">
              Current Balance: <span className={`text-sm ml-2 ${activeAccount?.balance < 0 ? 'text-red-500' : 'text-slate-900 font-black'}`}>
                {formatCurrency(activeAccount?.balance || 0)}
              </span>
            </div>
          )}
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-xs border-collapse">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                {isTransferView ? (
                  <>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] w-24">Date</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">From Cat</th>
                    <th className="px-2 py-4 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">To Cat</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">From Acc</th>
                    <th className="px-2 py-4 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">To Acc</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                  </>
                ) : (
                  <>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Date</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Description</th>
                    {showClearedColumn && <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-center">Cleared</th>}
                  </>
                )}
                <th className="px-4 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map((tx) => {
                  const acc = state.accounts.find(a => a.id === tx.accountId);
                  const accName = acc ? acc.name : (tx.accountId === 'internal' ? 'Allocation' : tx.accountId);
                  const isCredit = acc?.type === 'Credit';
                  const isTxVirtual = tx.accountId.startsWith('internal');

                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      {isTransferView ? (
                        <>
                          <td className="px-6 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3.5 text-slate-600 font-medium">{getCategoryName(tx.fromCategoryId)}</td>
                          <td className="px-2 py-3.5 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3.5 text-slate-600 font-medium">{getCategoryName(tx.toCategoryId)}</td>
                          <td className="px-4 py-3.5"><span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.fromAccountId)}</span></td>
                          <td className="px-2 py-3.5 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3.5"><span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.toAccountId)}</span></td>
                          <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {formatCurrency(tx.amount)}
                          </td>
                        </>
                      ) : (
                        <>
                          <td className="px-6 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3.5">
                            <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase tracking-tight ${
                              isTxVirtual ? 'bg-slate-100 text-slate-400' : 
                              acc?.type === 'Credit' ? 'bg-red-50 text-red-600' : acc?.type === 'Savings' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
                            }`}>
                              {accName}
                            </span>
                          </td>
                          <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                          </td>
                          <td className="px-6 py-3.5 text-slate-600 truncate max-w-[200px]">{tx.description}</td>
                          {showClearedColumn && (
                            <td className="px-6 py-3.5 text-center">
                              <button 
                                onClick={() => onToggleCleared(tx.id)}
                                disabled={!isCredit || isTxVirtual}
                                className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                                  (!isCredit || isTxVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                                  tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                                }`}
                              >
                                {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                              </button>
                            </td>
                          )}
                        </>
                      )}
                      <td className="px-4 py-3.5 text-right">
                        {isAllActivity && (
                          <button 
                            onClick={() => setDeleteTxConfirm(tx)}
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                          >
                            <Trash2 size={14} />
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={10} className="px-6 py-24 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-black">No transactions recorded in this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Account Modal */}
      {showAddAcc && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-[110] p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-8 transform transition-all scale-100 border border-slate-200">
            <h4 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-3 uppercase tracking-tighter">
              <Plus size={24} className="text-blue-500" /> Define New Account
            </h4>
            <form onSubmit={handleAddAccount} className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Display Name</label>
                <input 
                  type="text" 
                  className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none font-bold text-sm" 
                  value={newAcc.name} 
                  onChange={e => setNewAcc({...newAcc, name: e.target.value})} 
                  placeholder="e.g. AMEX Gold Card" 
                  autoFocus
                  required 
                />
              </div>

              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Account Type</label>
                <div className="grid grid-cols-2 gap-3">
                  {[
                    { type: 'Checking', icon: Landmark },
                    { type: 'Savings', icon: PiggyBank },
                    { type: 'Credit', icon: CreditCard },
                    { type: 'Investment', icon: Layers }
                  ].map(({ type, icon: Icon }) => (
                    <button
                      key={type}
                      type="button"
                      onClick={() => setNewAcc({...newAcc, type: type as AccountType})}
                      className={`flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${
                        newAcc.type === type 
                          ? 'border-blue-500 bg-blue-50 text-blue-600' 
                          : 'border-slate-100 bg-slate-50 text-slate-400 hover:border-slate-200'
                      }`}
                    >
                      <Icon size={16} />
                      {type}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 justify-end pt-6 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setShowAddAcc(false)} 
                  className="flex-1 px-6 py-3 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-1 px-10 py-3 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
                >
                  Add Account
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteTxConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <AlertTriangle size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight uppercase tracking-tight">
                Permanently Delete?
              </h4>
              <p className="text-[11px] text-slate-400 uppercase tracking-widest font-black leading-relaxed">
                Reversing this action will update both category and account balances.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteTxConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountLedgers;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Savings from './components/Savings';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance,
    // Layout Actions
    moveClassification,
    moveCategory,
    updateCategoryMetadata,
    updateClassificationMetadata,
    // Account Actions
    addAccount,
    moveAccount,
    updateAccountMetadata
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction}
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'savings':
        return (
          <Savings 
            state={state}
            addTransaction={addTransaction}
            executeTransfer={executeTransfer}
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'acc-ledgers':
        return (
          <AccountLedgers 
            state={state} 
            onToggleCleared={toggleCleared} 
            onDeleteTransaction={deleteTransaction}
            onAddAccount={addAccount}
            onMoveAccount={moveAccount}
            onUpdateAccount={updateAccountMetadata}
          />
        );
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            moveClassification={moveClassification}
            moveCategory={moveCategory}
            updateCategoryMetadata={updateCategoryMetadata}
            updateClassificationMetadata={updateClassificationMetadata}
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return (
          <NetWorth 
            state={state} 
            onAddSnapshot={addInvestmentSnapshot} 
            onAddAccount={addAccount}
          />
        );
      default:
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction} 
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState, Transaction, Account, AccountType } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { CheckCircle, Circle, Trash2, X, AlertTriangle, Layers, ArrowRight, Plus, Settings2, ChevronUp, ChevronDown, CheckCircle2, Landmark, CreditCard, PiggyBank } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
  onAddAccount: (name: string, type: AccountType) => void;
  onMoveAccount: (id: string, direction: 'up' | 'down') => void;
  onUpdateAccount: (id: string, updates: Partial<Account>) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ 
  state, 
  onToggleCleared, 
  onDeleteTransaction,
  onAddAccount,
  onMoveAccount,
  onUpdateAccount
}) => {
  const [activeAccId, setActiveAccId] = useState('all'); 
  const [deleteTxConfirm, setDeleteTxConfirm] = useState<Transaction | null>(null);
  const [showAddAcc, setShowAddAcc] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [newAcc, setNewAcc] = useState({ name: '', type: 'Checking' as AccountType });

  const virtualAccountMap: Record<string, { name: string, types?: string[] }> = {
    'all': { name: 'All Activity' },
    'internal': { name: 'Allocation', types: ['Update Budget (Allocation)'] },
    'internal-transfers': { 
      name: 'Transfers', 
      types: ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'] 
    },
  };

  const isVirtual = activeAccId.startsWith('internal') || activeAccId === 'all';
  const isAllActivity = activeAccId === 'all';
  const isTransferView = activeAccId === 'internal-transfers';

  const activeAccount = virtualAccountMap[activeAccId] 
    ? { name: virtualAccountMap[activeAccId].name, id: activeAccId, type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  // Filter out investment accounts for the ledgers page
  const displayAccounts = state.accounts.filter(a => a.type !== 'Investment');

  // Cleared column logic: Only for individual Credit accounts.
  const showClearedColumn = !isVirtual && !isTransferView && activeAccount?.type === 'Credit';

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'all') return true;
      if (activeAccId === 'internal') return t.type === 'Update Budget (Allocation)';
      if (activeAccId === 'internal-transfers') return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking'].includes(t.type);
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const confirmDelete = () => {
    if (deleteTxConfirm) {
      onDeleteTransaction(deleteTxConfirm.id);
      setDeleteTxConfirm(null);
    }
  };

  const getAccountName = (id?: string) => {
    if (!id) return '-';
    if (id === 'internal') return 'Internal';
    if (id === 'none') return '-';
    return state.accounts.find(a => a.id === id)?.name || id;
  };

  const getCategoryName = (id?: string) => {
    if (!id) return '-';
    if (id === 'none') return '-';
    return state.categories.find(c => c.id === id)?.name || id;
  };

  const handleAddAccount = (e: React.FormEvent) => {
    e.preventDefault();
    if (newAcc.name && newAcc.type) {
      onAddAccount(newAcc.name, newAcc.type);
      setNewAcc({ name: '', type: 'Checking' });
      setShowAddAcc(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation Header matching screenshot style */}
      <div className="bg-white p-2 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar py-1 px-1">
          {/* All Activity Tab */}
          <button
            onClick={() => setActiveAccId('all')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest flex items-center gap-2 shrink-0 ${
              activeAccId === 'all' 
                ? 'bg-slate-900 text-white shadow-xl' 
                : 'bg-white text-slate-400 hover:text-slate-600'
            }`}
          >
            <Layers size={14} />
            All Activity
          </button>

          <div className="w-[1px] h-6 bg-slate-200 mx-1 shrink-0" />

          {/* Dynamic Account Tabs (Checking, Savings, Credit Only) */}
          {displayAccounts.map((acc, idx) => (
            <div key={acc.id} className="flex items-center gap-1 shrink-0">
              <button
                onClick={() => setActiveAccId(acc.id)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest border border-slate-100 ${
                  activeAccId === acc.id 
                    ? 'bg-slate-900 text-white shadow-xl' 
                    : 'bg-white text-slate-400 hover:border-slate-300 hover:text-slate-600'
                } flex items-center gap-2`}
              >
                {isEditMode ? (
                  <div className="flex items-center gap-2">
                    <input 
                      type="text" 
                      className="bg-slate-700/50 text-white border-none rounded px-2 py-0.5 w-24 focus:ring-0"
                      value={acc.name}
                      autoFocus={activeAccId === acc.id}
                      onClick={(e) => e.stopPropagation()}
                      onChange={(e) => onUpdateAccount(acc.id, { name: e.target.value })}
                    />
                    <select
                      className="bg-slate-700/50 text-white border-none rounded text-[8px] p-0.5 focus:ring-0"
                      value={acc.type}
                      onClick={(e) => e.stopPropagation()}
                      onChange={(e) => onUpdateAccount(acc.id, { type: e.target.value as AccountType })}
                    >
                      <option value="Checking">CHK</option>
                      <option value="Savings">SAV</option>
                      <option value="Credit">CRD</option>
                    </select>
                    <div className="flex flex-col gap-0.5 ml-1">
                      <button disabled={idx === 0} onClick={(e) => { e.stopPropagation(); onMoveAccount(acc.id, 'up'); }} className="p-0.5 hover:bg-slate-700 rounded"><ChevronUp size={10} /></button>
                      <button disabled={idx === displayAccounts.length - 1} onClick={(e) => { e.stopPropagation(); onMoveAccount(acc.id, 'down'); }} className="p-0.5 hover:bg-slate-700 rounded"><ChevronDown size={10} /></button>
                    </div>
                  </div>
                ) : (
                  acc.name
                )}
              </button>
            </div>
          ))}

          {/* Add Account Button */}
          <button 
            onClick={() => setShowAddAcc(true)}
            className="w-10 h-10 rounded-xl bg-slate-50 text-slate-400 flex items-center justify-center hover:bg-slate-100 transition-colors shrink-0"
          >
            <Plus size={18} />
          </button>
        </div>

        {/* Right Side Virtual Tabs */}
        <div className="flex gap-2 items-center ml-4 shrink-0 px-2">
          <button
            onClick={() => setActiveAccId('internal')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeAccId === 'internal' 
                ? 'bg-slate-100 text-slate-900' 
                : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Allocation
          </button>
          <button
            onClick={() => setActiveAccId('internal-transfers')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeAccId === 'internal-transfers' 
                ? 'bg-slate-100 text-slate-900' 
                : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
            }`}
          >
            Transfers
          </button>
          <div className="w-[1px] h-6 bg-slate-200 mx-1" />
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-xl transition-all ${isEditMode ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}
          >
            {isEditMode ? <CheckCircle2 size={20} /> : <Settings2 size={20} />}
          </button>
        </div>
      </div>

      {/* Main Ledger Display */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {activeAccId === 'all' ? 'All Ledger Activity' : isVirtual ? `Internal ${activeAccount?.name} View` : `${activeAccount?.name} Ledger`}
          </h3>
          {(!isVirtual && activeAccId !== 'all') && (
            <div className="text-[10px] font-black uppercase tracking-widest text-slate-500">
              Current Balance: <span className={`text-sm ml-2 ${activeAccount?.balance < 0 ? 'text-red-500' : 'text-slate-900 font-black'}`}>
                {formatCurrency(activeAccount?.balance || 0)}
              </span>
            </div>
          )}
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-xs border-collapse">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                {isTransferView ? (
                  <>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] w-24">Date</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">From Cat</th>
                    <th className="px-2 py-4 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">To Cat</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">From Acc</th>
                    <th className="px-2 py-4 font-bold text-slate-400 text-center w-8"></th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">To Acc</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                  </>
                ) : (
                  <>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Date</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account</th>
                    <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                    <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Description</th>
                    {showClearedColumn && <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-center">Cleared</th>}
                  </>
                )}
                <th className="px-4 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map((tx) => {
                  const acc = state.accounts.find(a => a.id === tx.accountId);
                  const accName = acc ? acc.name : (tx.accountId === 'internal' ? 'Allocation' : tx.accountId);
                  const isCredit = acc?.type === 'Credit';
                  const isTxVirtual = tx.accountId.startsWith('internal');

                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      {isTransferView ? (
                        <>
                          <td className="px-6 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3.5 text-slate-600 font-medium">{getCategoryName(tx.fromCategoryId)}</td>
                          <td className="px-2 py-3.5 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3.5 text-slate-600 font-medium">{getCategoryName(tx.toCategoryId)}</td>
                          <td className="px-4 py-3.5"><span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.fromAccountId)}</span></td>
                          <td className="px-2 py-3.5 text-center text-slate-300"><ArrowRight size={14} /></td>
                          <td className="px-4 py-3.5"><span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.toAccountId)}</span></td>
                          <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {formatCurrency(tx.amount)}
                          </td>
                        </>
                      ) : (
                        <>
                          <td className="px-6 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                          <td className="px-4 py-3.5">
                            <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase tracking-tight ${
                              isTxVirtual ? 'bg-slate-100 text-slate-400' : 
                              acc?.type === 'Credit' ? 'bg-red-50 text-red-600' : acc?.type === 'Savings' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
                            }`}>
                              {accName}
                            </span>
                          </td>
                          <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                            {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                          </td>
                          <td className="px-6 py-3.5 text-slate-600 truncate max-w-[200px]">{tx.description}</td>
                          {showClearedColumn && (
                            <td className="px-6 py-3.5 text-center">
                              <button 
                                onClick={() => onToggleCleared(tx.id)}
                                disabled={!isCredit || isTxVirtual}
                                className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                                  (!isCredit || isTxVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                                  tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                                }`}
                              >
                                {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                              </button>
                            </td>
                          )}
                        </>
                      )}
                      <td className="px-4 py-3.5 text-right">
                        {isAllActivity && (
                          <button 
                            onClick={() => setDeleteTxConfirm(tx)}
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                          >
                            <Trash2 size={14} />
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={10} className="px-6 py-24 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-black">No transactions recorded in this ledger.</td>
