import React, { useMemo, useState } from 'react';
import { AppState, Account, InvestmentSnapshot, AccountType } from '../types';
import { formatCurrency, getMonthLabel, getMonthYearKey } from '../utils';
import { CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, XAxis, YAxis } from 'recharts';
import { Plus, BarChart3, TrendingUp, Layers } from 'lucide-react';

interface NetWorthProps {
  state: AppState;
  onAddSnapshot: (s: InvestmentSnapshot) => void;
  onAddAccount: (name: string, type: AccountType) => void;
}

const NetWorth: React.FC<NetWorthProps> = ({ state, onAddSnapshot, onAddAccount }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>(getMonthYearKey(new Date()));
  const [editValues, setEditValues] = useState<Record<string, string>>({});
  const [showAddInv, setShowAddInv] = useState(false);
  const [newInvName, setNewInvName] = useState('');

  // Range: Dec 2025 to Dec 2026
  const monthsOfYear = useMemo<string[]>(() => {
    const res: string[] = [];
    const startDate = new Date(2025, 11, 1);
    for (let i = 0; i <= 12; i++) {
      const d = new Date(startDate.getFullYear(), startDate.getMonth() + i, 1);
      res.push(getMonthYearKey(d));
    }
    return res;
  }, []);

  const getAccountBalanceForMonth = (acc: Account, monthKey: string) => {
    if (acc.type === 'Investment') {
      const snapshot = state.investmentSnapshots.find(s => s.monthKey === monthKey && s.accountId === acc.id);
      return snapshot ? snapshot.balance : acc.balance; // Fallback to current if no snapshot
    }
    return acc.balance;
  };

  const historyData = useMemo(() => {
    return monthsOfYear.map(m => {
      const total = state.accounts.reduce((sum, acc) => sum + getAccountBalanceForMonth(acc, m), 0);
      return { monthKey: m, label: getMonthLabel(m + "-01"), value: total };
    });
  }, [state.accounts, state.investmentSnapshots, monthsOfYear]);

  const handleSaveSnapshot = (e: React.FormEvent) => {
    e.preventDefault();
    (Object.entries(editValues) as [string, string][]).forEach(([accId, val]) => {
      if (val) onAddSnapshot({ monthKey: selectedMonth, accountId: accId, balance: parseFloat(val) });
    });
    setEditValues({});
  };

  const handleAddInvestment = (e: React.FormEvent) => {
    e.preventDefault();
    if (newInvName.trim()) {
      onAddAccount(newInvName.trim(), 'Investment');
      setNewInvName('');
      setShowAddInv(false);
    }
  };

  const investmentAccounts = state.accounts.filter(a => a.type === 'Investment');

  const groups = [
    { label: 'Checking', type: 'Checking' },
    { label: 'Credit cards', type: 'Credit' },
    { label: 'Savings', type: 'Savings' },
    { label: 'Investments', type: 'Investment' }
  ];

  return (
    <div className="space-y-8 pb-24">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <TrendingUp size={14} className="text-blue-500" />
              Net Worth Growth Trajectory
            </h3>
            <button 
              onClick={() => setShowAddInv(true)}
              className="px-4 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-blue-600 transition-all shadow-lg active:scale-95"
            >
              <Plus size={14} /> Add Investment
            </button>
          </div>
          <div className="h-64 w-full flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={historyData}>
                <defs>
                  <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.15}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                  formatter={(value: number) => [formatCurrency(value, true), 'Net Worth']}
                />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorNet)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-900 rounded-xl p-6 text-white shadow-xl h-fit">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-blue-500 rounded-lg"><BarChart3 size={20} /></div>
            <h4 className="text-[10px] font-black text-slate-200 uppercase tracking-[0.2em]">Manual Month-End Entry</h4>
          </div>

          <form onSubmit={handleSaveSnapshot} className="space-y-4">
            <div>
              <label className="text-[9px] text-slate-500 uppercase font-black mb-1.5 block tracking-widest">Recording Period</label>
              <select 
                value={selectedMonth} 
                onChange={e => setSelectedMonth(e.target.value)}
                className="w-full bg-slate-800 border-none text-xs font-bold rounded-lg p-3 focus:ring-1 focus:ring-blue-500 appearance-none text-white shadow-inner"
              >
                {monthsOfYear.map(m => <option key={m} value={m}>{getMonthLabel(m + "-01")}</option>)}
              </select>
            </div>

            <div className="space-y-4 max-h-72 overflow-y-auto custom-scrollbar pr-3">
              {investmentAccounts.length > 0 ? (
                investmentAccounts.map(acc => (
                  <div key={acc.id} className="space-y-1.5 animate-in fade-in duration-300">
                    <label className="text-[9px] text-slate-400 uppercase font-black tracking-tight">{acc.name}</label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 text-xs font-bold">$</span>
                      <input 
                        type="number" 
                        step="0.01" 
                        className="w-full bg-slate-800/50 border border-slate-700/50 rounded-lg p-2.5 pl-7 text-xs font-bold text-white placeholder:text-slate-600 focus:border-blue-500/50 focus:outline-none transition-all"
                        placeholder={acc.balance.toFixed(2)}
                        value={editValues[acc.id] || ''}
                        onChange={e => setEditValues({...editValues, [acc.id]: e.target.value})}
                      />
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-8 text-center border-2 border-dashed border-slate-800 rounded-xl">
                  <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">No Investment Accounts</p>
                  <button type="button" onClick={() => setShowAddInv(true)} className="mt-2 text-[9px] text-blue-400 hover:text-blue-300 transition-colors uppercase font-bold">+ Add Now</button>
                </div>
              )}
            </div>

            <button type="submit" className="w-full bg-blue-600 py-3.5 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] hover:bg-blue-500 transition-all shadow-xl active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed mt-4" disabled={investmentAccounts.length === 0}>
              Commit Snapshots
            </button>
          </form>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-[10px] uppercase border-collapse">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-black text-slate-400 tracking-widest sticky left-0 bg-slate-50 z-30 border-r border-slate-200">Account Asset Class</th>
                {monthsOfYear.map(m => <th key={m} className="px-4 py-4 text-slate-400 text-right font-bold border-r border-slate-100 last:border-r-0 whitespace-nowrap">{getMonthLabel(m + "-01")}</th>)}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 font-bold">
              {groups.map(group => {
                const accountsInGroup = state.accounts.filter(a => a.type === group.type);
                if (accountsInGroup.length === 0) return null;

                return (
                  <React.Fragment key={group.label}>
                    {/* Individual Accounts */}
                    {accountsInGroup.map(acc => (
                      <tr key={acc.id} className="hover:bg-slate-50/50 group transition-colors">
                        <td className="px-6 py-2.5 text-slate-500 font-black sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.02)] lowercase tracking-tighter">
                          {acc.name}
                        </td>
                        {monthsOfYear.map(m => {
                          const bal = getAccountBalanceForMonth(acc, m);
                          return (
                            <td key={m} className={`px-4 py-2.5 text-right border-r border-slate-50 last:border-r-0 ${bal < 0 ? 'text-red-400' : 'text-slate-400'}`}>
                              {formatCurrency(bal, true)}
                            </td>
                          );
                        })}
                      </tr>
                    ))}

                    {/* Subtotal for the Group */}
                    <tr className="bg-slate-50/80 font-black border-t-2 border-slate-200">
                      <td className="px-6 py-3 text-slate-900 sticky left-0 bg-slate-50 z-20 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.05)] uppercase tracking-widest">
                        {group.label}
                      </td>
                      {monthsOfYear.map(m => {
                        const subtotal = accountsInGroup.reduce((sum, a) => sum + getAccountBalanceForMonth(a, m), 0);
                        return (
                          <td key={m} className={`px-4 py-3 text-right border-r border-slate-100 last:border-r-0 ${subtotal < 0 ? 'text-red-600' : 'text-slate-900'}`}>
                            {formatCurrency(subtotal, true)}
                          </td>
                        );
                      })}
                    </tr>
                  </React.Fragment>
                );
              })}

              {/* Grand Total Row */}
              <tr className="bg-slate-900 text-white border-t-4 border-white shadow-[0_-4px_10px_rgba(0,0,0,0.2)]">
                <td className="px-6 py-7 font-black tracking-[0.3em] text-[11px] sticky left-0 bg-slate-900 z-40 border-r border-slate-800 uppercase">
                  Consolidated Net Worth
                </td>
                {historyData.map(d => (
                  <td key={d.monthKey} className="px-4 py-7 text-right font-black text-xs border-r border-slate-800 last:border-r-0">
                    {formatCurrency(d.value, true)}
                  </td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Investment Modal */}
      {showAddInv && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-[110] p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-8 transform transition-all scale-100 border border-slate-200">
            <h4 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-3 uppercase tracking-tighter">
              <Layers size={24} className="text-blue-500" /> New Investment Asset
            </h4>
            <form onSubmit={handleAddInvestment} className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Asset Name / Institution</label>
                <input 
                  type="text" 
                  className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none font-bold text-sm" 
                  value={newInvName} 
                  onChange={e => setNewInvName(e.target.value)} 
                  placeholder="e.g. Fidelity 401k" 
                  autoFocus
                  required 
                />
              </div>

              <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                <p className="text-[10px] text-blue-700 font-bold uppercase tracking-widest leading-tight">
                  This asset will be tracked exclusively through the Net Worth manual snapshots.
                </p>
              </div>

              <div className="flex gap-3 justify-end pt-6 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setShowAddInv(false)} 
                  className="flex-1 px-6 py-3 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-1 px-10 py-3 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
                >
                  Create Asset
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default NetWorth;

