import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Savings from './components/Savings';
import Ledgers from './components/Ledgers';
import AccountLedgers from './components/AccountLedgers';
import TransfersPage from './components/TransfersPage';
import BudgetManager from './components/BudgetManager';
import Summary from './components/Summary';
import NetWorth from './components/NetWorth';
import { useFinance } from './hooks/useFinance';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const { 
    state, 
    addTransaction, 
    executeTransfer, 
    addCategory, 
    deleteCategory,
    deleteTransaction,
    undoLastTransaction,
    toggleCleared, 
    updateBudget, 
    setEstIncome,
    addInvestmentSnapshot,
    setCategoryBalance,
    setAccountBalance,
    // Layout Actions
    moveClassification,
    moveCategory,
    updateCategoryMetadata,
    updateClassificationMetadata,
    // Account Actions
    addAccount,
    moveAccount,
    updateAccountMetadata
  } = useFinance();

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction}
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'savings':
        return (
          <Savings 
            state={state}
            addTransaction={addTransaction}
            executeTransfer={executeTransfer}
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
      case 'acc-ledgers':
        return (
          <AccountLedgers 
            state={state} 
            onToggleCleared={toggleCleared} 
            onDeleteTransaction={deleteTransaction}
            onAddAccount={addAccount}
            onMoveAccount={moveAccount}
            onUpdateAccount={updateAccountMetadata}
          />
        );
      case 'transfers':
        return (
          <TransfersPage 
            state={state}
            onAddTransaction={addTransaction}
            onExecuteTransfer={executeTransfer}
            onDeleteTransaction={deleteTransaction}
          />
        );
      case 'ledgers':
        return <Ledgers state={state} />;
      case 'budget':
        return (
          <BudgetManager 
            state={state} 
            onUpdateBudget={updateBudget} 
            onUpdateEstIncome={setEstIncome} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            moveClassification={moveClassification}
            moveCategory={moveCategory}
            updateCategoryMetadata={updateCategoryMetadata}
            updateClassificationMetadata={updateClassificationMetadata}
          />
        );
      case 'summary':
        return <Summary state={state} />;
      case 'networth':
        return (
          <NetWorth 
            state={state} 
            onAddSnapshot={addInvestmentSnapshot} 
            onAddAccount={addAccount}
          />
        );
      default:
        return (
          <Dashboard 
            state={state} 
            addTransaction={addTransaction} 
            undoLastTransaction={undoLastTransaction} 
            executeTransfer={executeTransfer} 
            setCategoryBalance={setCategoryBalance}
            setAccountBalance={setAccountBalance}
          />
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {children ? children : renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState, Transaction, Account, AccountType } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { CheckCircle, Circle, Trash2, X, AlertTriangle, Layers, ArrowRight, Plus, Settings2, ChevronUp, ChevronDown, CheckCircle2, Landmark, CreditCard, PiggyBank } from 'lucide-react';

interface AccountLedgersProps {
  state: AppState;
  onToggleCleared: (id: string) => void;
  onDeleteTransaction: (id: string) => void;
  onAddAccount: (name: string, type: AccountType) => void;
  onMoveAccount: (id: string, direction: 'up' | 'down') => void;
  onUpdateAccount: (id: string, updates: Partial<Account>) => void;
}

const AccountLedgers: React.FC<AccountLedgersProps> = ({ 
  state, 
  onToggleCleared, 
  onDeleteTransaction,
  onAddAccount,
  onMoveAccount,
  onUpdateAccount
}) => {
  const [activeAccId, setActiveAccId] = useState('all'); 
  const [deleteTxConfirm, setDeleteTxConfirm] = useState<Transaction | null>(null);
  const [showAddAcc, setShowAddAcc] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [newAcc, setNewAcc] = useState({ name: '', type: 'Checking' as AccountType });

  const isAllActivity = activeAccId === 'all';
  const activeAccount = activeAccId === 'all' 
    ? { name: 'All Activity', id: 'all', type: 'Virtual', balance: 0 } 
    : state.accounts.find(a => a.id === activeAccId);

  // Filter out investment accounts for the ledgers page
  const displayAccounts = state.accounts.filter(a => a.type !== 'Investment');

  // Cleared column logic: Only for individual Credit accounts.
  const showClearedColumn = !isAllActivity && activeAccount?.type === 'Credit';

  const transactions = state.transactions
    .filter(t => {
      if (activeAccId === 'all') return true;
      return t.accountId === activeAccId;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const confirmDelete = () => {
    if (deleteTxConfirm) {
      onDeleteTransaction(deleteTxConfirm.id);
      setDeleteTxConfirm(null);
    }
  };

  const handleAddAccount = (e: React.FormEvent) => {
    e.preventDefault();
    if (newAcc.name && newAcc.type) {
      onAddAccount(newAcc.name, newAcc.type);
      setNewAcc({ name: '', type: 'Checking' });
      setShowAddAcc(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation Header matching screenshot style */}
      <div className="bg-white p-2 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar py-1 px-1">
          {/* All Activity Tab */}
          <button
            onClick={() => setActiveAccId('all')}
            className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest flex items-center gap-2 shrink-0 ${
              activeAccId === 'all' 
                ? 'bg-slate-900 text-white shadow-xl' 
                : 'bg-white text-slate-400 hover:text-slate-600'
            }`}
          >
            <Layers size={14} />
            All Activity
          </button>

          <div className="w-[1px] h-6 bg-slate-200 mx-1 shrink-0" />

          {/* Dynamic Account Tabs (Checking, Savings, Credit Only) */}
          {displayAccounts.map((acc, idx) => (
            <div key={acc.id} className="flex items-center gap-1 shrink-0">
              <button
                onClick={() => setActiveAccId(acc.id)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest border border-slate-100 ${
                  activeAccId === acc.id 
                    ? 'bg-slate-900 text-white shadow-xl' 
                    : 'bg-white text-slate-400 hover:border-slate-300 hover:text-slate-600'
                } flex items-center gap-2`}
              >
                {isEditMode ? (
                  <div className="flex items-center gap-2">
                    <input 
                      type="text" 
                      className="bg-slate-700/50 text-white border-none rounded px-2 py-0.5 w-24 focus:ring-0"
                      value={acc.name}
                      autoFocus={activeAccId === acc.id}
                      onClick={(e) => e.stopPropagation()}
                      onChange={(e) => onUpdateAccount(acc.id, { name: e.target.value })}
                    />
                    <select
                      className="bg-slate-700/50 text-white border-none rounded text-[8px] p-0.5 focus:ring-0"
                      value={acc.type}
                      onClick={(e) => e.stopPropagation()}
                      onChange={(e) => onUpdateAccount(acc.id, { type: e.target.value as AccountType })}
                    >
                      <option value="Checking">CHK</option>
                      <option value="Savings">SAV</option>
                      <option value="Credit">CRD</option>
                    </select>
                    <div className="flex flex-col gap-0.5 ml-1">
                      <button disabled={idx === 0} onClick={(e) => { e.stopPropagation(); onMoveAccount(acc.id, 'up'); }} className="p-0.5 hover:bg-slate-700 rounded"><ChevronUp size={10} /></button>
                      <button disabled={idx === displayAccounts.length - 1} onClick={(e) => { e.stopPropagation(); onMoveAccount(acc.id, 'down'); }} className="p-0.5 hover:bg-slate-700 rounded"><ChevronDown size={10} /></button>
                    </div>
                  </div>
                ) : (
                  acc.name
                )}
              </button>
            </div>
          ))}

          {/* Add Account Button */}
          <button 
            onClick={() => setShowAddAcc(true)}
            className="w-10 h-10 rounded-xl bg-slate-50 text-slate-400 flex items-center justify-center hover:bg-slate-100 transition-colors shrink-0"
          >
            <Plus size={18} />
          </button>
        </div>

        {/* Right Side Tools */}
        <div className="flex gap-2 items-center ml-4 shrink-0 px-2">
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`p-2 rounded-xl transition-all ${isEditMode ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}
          >
            {isEditMode ? <CheckCircle2 size={20} /> : <Settings2 size={20} />}
          </button>
        </div>
      </div>

      {/* Main Ledger Display */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
          <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
            {activeAccId === 'all' ? 'All Ledger Activity' : `${activeAccount?.name} Ledger`}
          </h3>
          {(!isAllActivity) && (
            <div className="text-[10px] font-black uppercase tracking-widest text-slate-500">
              Current Balance: <span className={`text-sm ml-2 ${activeAccount?.balance < 0 ? 'text-red-500' : 'text-slate-900 font-black'}`}>
                {formatCurrency(activeAccount?.balance || 0)}
              </span>
            </div>
          )}
        </div>
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left text-xs border-collapse">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Date</th>
                <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account</th>
                <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Description</th>
                {showClearedColumn && <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-center">Cleared</th>}
                <th className="px-4 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {transactions.length > 0 ? (
                transactions.map((tx) => {
                  const acc = state.accounts.find(a => a.id === tx.accountId);
                  const accName = acc ? acc.name : (tx.accountId === 'internal' ? 'Allocation' : tx.accountId);
                  const isCredit = acc?.type === 'Credit';
                  const isTxVirtual = tx.accountId.startsWith('internal');

                  return (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-6 py-3.5 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>
                      <td className="px-4 py-3.5">
                        <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase tracking-tight ${
                          isTxVirtual ? 'bg-slate-100 text-slate-400' : 
                          acc?.type === 'Credit' ? 'bg-red-50 text-red-600' : acc?.type === 'Savings' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
                        }`}>
                          {accName}
                        </span>
                      </td>
                      <td className={`px-4 py-3.5 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                        {tx.amount < 0 ? `(${formatCurrency(Math.abs(tx.amount))})` : formatCurrency(tx.amount)}
                      </td>
                      <td className="px-6 py-3.5 text-slate-600 truncate max-w-[200px]">{tx.description}</td>
                      {showClearedColumn && (
                        <td className="px-6 py-3.5 text-center">
                          <button 
                            onClick={() => onToggleCleared(tx.id)}
                            disabled={!isCredit || isTxVirtual}
                            className={`inline-flex items-center justify-center p-1 rounded-full transition-colors ${
                              (!isCredit || isTxVirtual) ? 'opacity-20 cursor-not-allowed text-slate-200' :
                              tx.cleared ? 'text-green-500 hover:text-green-600' : 'text-slate-200 hover:text-slate-300'
                            }`}
                          >
                            {tx.cleared ? <CheckCircle size={18} /> : <Circle size={18} />}
                          </button>
                        </td>
                      )}
                      <td className="px-4 py-3.5 text-right">
                        {isAllActivity && (
                          <button 
                            onClick={() => setDeleteTxConfirm(tx)}
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                          >
                            <Trash2 size={14} />
                          </button>
                        )}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={10} className="px-6 py-24 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-black">No transactions recorded in this ledger.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Account Modal */}
      {showAddAcc && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-[110] p-4 animate-in fade-in duration-300">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-8 transform transition-all scale-100 border border-slate-200">
            <h4 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-3 uppercase tracking-tighter">
              <Plus size={24} className="text-blue-500" /> Define New Account
            </h4>
            <form onSubmit={handleAddAccount} className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Display Name</label>
                <input 
                  type="text" 
                  className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500/20 focus:outline-none font-bold text-sm" 
                  value={newAcc.name} 
                  onChange={e => setNewAcc({...newAcc, name: e.target.value})} 
                  placeholder="e.g. Chase Freedom" 
                  autoFocus
                  required 
                />
              </div>

              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Account Type</label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { type: 'Checking', icon: Landmark },
                    { type: 'Savings', icon: PiggyBank },
                    { type: 'Credit', icon: CreditCard }
                  ].map(({ type, icon: Icon }) => (
                    <button
                      key={type}
                      type="button"
                      onClick={() => setNewAcc({...newAcc, type: type as AccountType})}
                      className={`flex flex-col items-center justify-center gap-2 px-4 py-4 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${
                        newAcc.type === type 
                          ? 'border-blue-500 bg-blue-50 text-blue-600' 
                          : 'border-slate-100 bg-slate-50 text-slate-400 hover:border-slate-200'
                      }`}
                    >
                      <Icon size={20} />
                      {type}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 justify-end pt-6 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setShowAddAcc(false)} 
                  className="flex-1 px-6 py-3 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-1 px-10 py-3 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-blue-600 transition-all active:scale-95"
                >
                  Add Account
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteTxConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <AlertTriangle size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight uppercase tracking-tight">
                Permanently Delete?
              </h4>
              <p className="text-[11px] text-slate-400 uppercase tracking-widest font-black leading-relaxed">
                Reversing this action will update both category and account balances.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteTxConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountLedgers;

import React, { useState } from 'react';
import { AppState, Transaction } from '../types';
import { formatCurrency, formatDisplayDate } from '../utils';
import { Layers, ArrowRight, ArrowRightLeft, Target, PiggyBank, Landmark, CreditCard, Trash2, AlertTriangle, X } from 'lucide-react';
import TransactionPanel from './TransactionPanel';

interface TransfersPageProps {
  state: AppState;
  onAddTransaction: (tx: any) => void;
  onExecuteTransfer: (transfer: any) => void;
  onDeleteTransaction: (id: string) => void;
}

const TransfersPage: React.FC<TransfersPageProps> = ({ 
  state, 
  onAddTransaction, 
  onExecuteTransfer,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState('all');
  const [deleteConfirm, setDeleteConfirm] = useState<Transaction | null>(null);

  const tabs = [
    { id: 'all', label: 'All Movements', icon: Layers },
    { id: 'allocation', label: 'Allocations', icon: Target, types: ['Update Budget (Allocation)'] },
    { id: 'cat-transfer', label: 'Cat Transfers', icon: ArrowRightLeft, types: ['Category Transfer'] },
    { id: 'savings', label: 'To Savings', icon: PiggyBank, types: ['Transfer to Savings'] },
    { id: 'checking', label: 'To Checking', icon: Landmark, types: ['Transfer to Checking', 'Transfer between Checking'] },
    { id: 'credit', label: 'Credit Payments', icon: CreditCard, types: ['Credit Payment'] },
  ];

  const currentTab = tabs.find(t => t.id === activeTab);

  const movements = state.transactions
    .filter(t => {
      if (activeTab === 'all') {
        return ['Category Transfer', 'Transfer to Savings', 'Transfer to Checking', 'Credit Payment', 'Transfer between Checking', 'Update Budget (Allocation)'].includes(t.type);
      }
      return currentTab?.types?.includes(t.type);
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const confirmDelete = () => {
    if (deleteConfirm) {
      onDeleteTransaction(deleteConfirm.id);
      setDeleteConfirm(null);
    }
  };

  const getAccountName = (id?: string) => {
    if (!id || id === 'none') return '-';
    if (id === 'internal') return 'Internal';
    return state.accounts.find(a => a.id === id)?.name || id;
  };

  const getCategoryName = (id?: string) => {
    if (!id || id === 'none') return '-';
    return state.categories.find(c => c.id === id)?.name || id;
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        {/* Horizontal Navigation Pills */}
        <div className="bg-white p-2 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-2 overflow-x-auto no-scrollbar">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-5 py-2.5 rounded-xl text-[10px] font-black transition-all whitespace-nowrap uppercase tracking-widest flex items-center gap-2 shrink-0 ${
                activeTab === tab.id 
                  ? 'bg-slate-900 text-white shadow-xl' 
                  : 'bg-white text-slate-400 hover:text-slate-600'
              }`}
            >
              <tab.icon size={14} />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Ledger Table */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-widest">
              {currentTab?.label} Ledger
            </h3>
            <div className="text-[10px] font-black uppercase tracking-widest text-slate-400">
              {movements.length} Record{movements.length !== 1 ? 's' : ''} Found
            </div>
          </div>

          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left text-xs border-collapse">
              <thead className="bg-white border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] w-24">Date</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Category Flow</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px]">Account Flow</th>
                  <th className="px-4 py-4 font-bold text-slate-400 uppercase tracking-widest text-[10px] text-right">Amount</th>
                  <th className="px-4 py-4"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {movements.length > 0 ? (
                  movements.map((tx) => (
                    <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-6 py-4 text-slate-400 whitespace-nowrap">{formatDisplayDate(tx.date)}</td>

                      <td className="px-4 py-4">
                        {tx.type === 'Update Budget (Allocation)' ? (
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-tighter">Budget -></span>
                            <span className="text-slate-700 font-bold">{getCategoryName(tx.categoryId)}</span>
                          </div>
                        ) : (
                          <div className="flex items-center gap-2">
                            <span className="text-slate-500 font-medium">{getCategoryName(tx.fromCategoryId)}</span>
                            <ArrowRight size={12} className="text-slate-300" />
                            <span className="text-slate-800 font-black">{getCategoryName(tx.toCategoryId || tx.categoryId)}</span>
                          </div>
                        )}
                        <div className="text-[9px] text-slate-400 uppercase font-black tracking-widest mt-0.5">{tx.description || tx.type}</div>
                      </td>

                      <td className="px-4 py-4">
                        {tx.type === 'Update Budget (Allocation)' ? (
                          <span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-400 rounded uppercase">Internal</span>
                        ) : (
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-bold px-2 py-1 bg-slate-50 text-slate-500 rounded uppercase">{getAccountName(tx.fromAccountId || tx.accountId)}</span>
                            <ArrowRight size={12} className="text-slate-300" />
                            <span className="text-[10px] font-bold px-2 py-1 bg-blue-50 text-blue-600 rounded uppercase">{getAccountName(tx.toAccountId || tx.accountId)}</span>
                          </div>
                        )}
                      </td>

                      <td className={`px-4 py-4 text-right font-black text-sm ${tx.amount < 0 ? 'text-red-500' : 'text-blue-600'}`}>
                        {formatCurrency(Math.abs(tx.amount))}
                      </td>

                      <td className="px-4 py-4 text-right">
                        <button 
                          onClick={() => setDeleteConfirm(tx)}
                          className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-red-50"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={5} className="px-6 py-24 text-center text-slate-300 italic uppercase text-[10px] tracking-widest font-black">
                      No matching records found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="lg:block">
        <div className="sticky top-8 space-y-6">
          <TransactionPanel 
            state={state} 
            onAddTransaction={onAddTransaction} 
            onExecuteTransfer={onExecuteTransfer} 
            allowedModes={['allocation', 'transfer']} 
          />

          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Audit Notice</h4>
            <p className="text-[11px] text-slate-500 leading-relaxed font-medium">
              Transfers and allocations are internal movements that do not reflect external income or standard spending. Ensure all "Allocation" entries are cleared by corresponding "Expense" entries on the Balance Statement to maintain reconciliation.
            </p>
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {deleteConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <AlertTriangle size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight uppercase tracking-tight">
                Reversing Movement?
              </h4>
              <div className="p-4 bg-slate-50 rounded-xl space-y-2 text-left">
                <div className="flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase">
                  <span>{formatDisplayDate(deleteConfirm.date)}</span>
                  <span className="text-slate-900 font-black">{formatCurrency(Math.abs(deleteConfirm.amount))}</span>
                </div>
                <p className="text-xs font-black text-slate-700 truncate uppercase tracking-tight">{deleteConfirm.type}</p>
              </div>
              <p className="text-[11px] text-slate-400 uppercase tracking-widest font-black leading-relaxed">
                Deleting this record will restore balances to their previous state.
              </p>
