      {/* Delete Confirmation Modal */}
      {deleteTxConfirm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-red-50 text-red-500 mb-2">
                <AlertTriangle size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight uppercase tracking-tight">
                Permanently Delete?
              </h4>
              <p className="text-[11px] text-slate-400 uppercase tracking-widest font-black leading-relaxed">
                Reversing this action will update both category and account balances.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setDeleteTxConfirm(null)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmDelete}
