import React, { useMemo, useState } from 'react';
import { AlertCircle, Undo2, Edit3, CheckCircle2, X, AlertTriangle, RotateCcw } from 'lucide-react';
import { AppState } from '../types';
import { formatCurrency, getMonthYearKey, formatDisplayDate } from '../utils';
import TransactionPanel from './TransactionPanel';

interface DashboardProps {
  state: AppState;
  addTransaction: (tx: any) => void;
  undoLastTransaction: () => void;
  executeTransfer: (transfer: any) => void;
  setCategoryBalance: (catId: string, balance: number) => void;
  setAccountBalance: (accId: string, balance: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  state, 
  addTransaction, 
  undoLastTransaction, 
  executeTransfer,
  setCategoryBalance,
  setAccountBalance
}) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [showUndoConfirm, setShowUndoConfirm] = useState(false);
  const currentMonth = getMonthYearKey(new Date());

  const lastTransaction = useMemo(() => {
    return state.transactions.length > 0 ? state.transactions[state.transactions.length - 1] : null;
  }, [state.transactions]);

  const categoryCalculations = useMemo(() => {
    return state.categories
      .filter(cat => !cat.deleted)
      .map(cat => {
        const monthlyTx = state.transactions.filter(t => t.categoryId === cat.id && getMonthYearKey(t.date) === currentMonth);
        const added = monthlyTx.filter(t => t.amount > 0).reduce((sum, t) => sum + t.amount, 0);
        const spent = monthlyTx.filter(t => t.amount < 0).reduce((sum, t) => sum + t.amount, 0);
        return { ...cat, monthlyAdded: added, monthlySpent: spent };
      });
  }, [state.categories, state.transactions, currentMonth]);

  const groupedCategories = useMemo(() => {
    const groups: Record<string, typeof categoryCalculations> = {};
    state.classifications.forEach(cls => {
      groups[cls.id] = categoryCalculations.filter(cat => cat.classificationId === cls.id);
    });
    return groups;
  }, [state.classifications, categoryCalculations]);

  const reconciliation = useMemo(() => {
    const capOne = state.accounts.find(a => a.id === 'acc-cap-checking')?.balance || 0;
    const dsChecking = state.accounts.find(a => a.id === 'acc-ds-6521')?.balance || 0;
    const dsCredit = state.accounts.find(a => a.id === 'acc-ds-8193')?.balance || 0;
    const visaCredit = state.accounts.find(a => a.id === 'acc-visa-4914')?.balance || 0;

    const debitBalance = capOne + dsChecking;
    const creditBalance = dsCredit + visaCredit;
    const net = debitBalance + creditBalance;

    const budgetCategories = state.categories.filter(c => !['class-income', 'class-savings', 'class-transfers'].includes(c.classificationId));
    const totalAllocated = budgetCategories.reduce((sum, cat) => sum + cat.balance, 0);

    return {
      capOne,
      dsChecking,
      dsCredit,
      visaCredit,
      debitBalance,
      creditBalance,
      net,
      totalAllocated,
      difference: net - totalAllocated
    };
  }, [state.accounts, state.categories]);

  const dashboardClasses = state.classifications.filter(c => !['class-income', 'class-savings', 'class-transfers'].includes(c.id));

  const handleConfirmUndo = () => {
    undoLastTransaction();
    setShowUndoConfirm(false);
  };

  const getAccountName = (id: string) => {
    if (id === 'internal') return 'Internal Budget';
    return state.accounts.find(a => a.id === id)?.name || id;
  };

  const getCategoryName = (id: string) => {
    return state.categories.find(c => c.id === id)?.name || 'N/A';
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-slate-700 uppercase text-xs tracking-wider">Balance Statement</h3>
            <div className="flex items-center gap-2">
               <button 
                  onClick={() => setIsEditMode(!isEditMode)} 
                  className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest transition-all px-4 py-1.5 rounded-full ${
                    isEditMode 
                      ? 'bg-blue-600 text-white shadow-lg' 
                      : 'text-slate-400 hover:text-slate-900 hover:bg-slate-100'
                  }`}
                >
                  {isEditMode ? (
                    <><CheckCircle2 size={12} /> Done</>
                  ) : (
                    <><Edit3 size={12} /> Manual Update</>
                  )}
                </button>
               {!isEditMode && lastTransaction && (
                 <button 
                    onClick={() => setShowUndoConfirm(true)} 
                    className="flex items-center gap-1.5 text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full hover:bg-slate-100"
                  >
                    <Undo2 size={12} /> Undo Last
                  </button>
               )}
            </div>
          </div>
          <table className="w-full text-left text-sm">
            <thead className="bg-white border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-semibold text-slate-600 text-[10px] uppercase tracking-wider">Classification / Category</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider w-32">Balance</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Budget</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Added</th>
                <th className="px-4 py-3 font-semibold text-slate-600 text-right text-[10px] uppercase tracking-wider">Spent</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {dashboardClasses.map(cls => {
                const cats = groupedCategories[cls.id] || [];
                if (cats.length === 0) return null;
                return (
                  <React.Fragment key={cls.id}>
                    <tr className={`${cls.color} font-bold text-slate-800`}><td colSpan={5} className="px-6 py-2 uppercase tracking-wide text-[10px]">{cls.name}</td></tr>
                    {cats.map(cat => (
                      <tr key={cat.id} className="hover:bg-slate-50/50 transition-colors border-l-2 border-transparent hover:border-blue-400">
                        <td className="px-6 py-2 text-slate-600 font-medium">{cat.name}</td>
                        <td className="px-4 py-2 text-right font-bold">
                          {isEditMode ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={cat.balance}
                              onChange={(e) => setCategoryBalance(cat.id, parseFloat(e.target.value) || 0)}
                              className="w-full px-2 py-1 bg-blue-50 border border-blue-200 rounded text-right text-xs focus:ring-1 focus:ring-blue-500 focus:outline-none"
                            />
                          ) : (
                            <span className={cat.balance < 0 ? 'text-red-500' : 'text-slate-900'}>
                              {formatCurrency(cat.balance)}
                            </span>
                          )}
                        </td>
                        <td className="px-4 py-2 text-right text-slate-400">{cat.monthlyBudget > 0 ? formatCurrency(cat.monthlyBudget) : '-'}</td>
                        <td className="px-4 py-2 text-right text-blue-500 font-medium">{cat.monthlyAdded > 0 ? formatCurrency(cat.monthlyAdded) : '-'}</td>
                        <td className="px-4 py-2 text-right text-red-400">{cat.monthlySpent < 0 ? formatCurrency(cat.monthlySpent) : '-'}</td>
                      </tr>
                    ))}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="lg:block">
        <div className="sticky top-8 space-y-6">
          {!isEditMode ? (
            <TransactionPanel state={state} onAddTransaction={addTransaction} onExecuteTransfer={executeTransfer} />
          ) : (
            <div className="bg-white rounded-xl border-2 border-dashed border-blue-100 p-8 text-center space-y-3 animate-in fade-in duration-300">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-blue-50 text-blue-500 mb-2">
                <Edit3 size={24} />
              </div>
              <h4 className="text-xs font-black text-slate-800 uppercase tracking-widest">Edit Mode Active</h4>
              <p className="text-[10px] text-slate-400 leading-relaxed uppercase font-bold">
                You are manually adjusting balances. Transactions are disabled until you click "Done".
              </p>
              <button 
                onClick={() => setIsEditMode(false)}
                className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg hover:bg-blue-700 transition-all"
              >
                Exit Edit Mode
              </button>
            </div>
          )}

          <div className="bg-[#0f172a] rounded-xl shadow-2xl p-6 text-slate-300 font-bold text-[11px] uppercase tracking-wider space-y-4 border border-slate-800">
            <div className="flex justify-between items-center mb-2">
              <h3 className="text-[10px] text-slate-500 uppercase tracking-widest">Budget Reconciliation</h3>
              <button 
                onClick={() => setIsEditMode(!isEditMode)}
                className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest transition-all px-3 py-1.5 rounded-full ${
                  isEditMode 
                    ? 'bg-blue-600 text-white shadow-lg' 
                    : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700 border border-slate-700'
                }`}
              >
                {isEditMode ? (
                  <><CheckCircle2 size={12} /> Done</>
                ) : (
                  <><Edit3 size={12} /> Manual Update</>
                )}
              </button>
            </div>

            <div className="space-y-3">
              {[
                { id: 'acc-cap-checking', label: 'Capital One Checking', key: 'capOne' },
                { id: 'acc-ds-6521', label: 'Discover Checking', key: 'dsChecking' },
                { id: 'acc-ds-8193', label: 'Discover Credit', key: 'dsCredit' },
                { id: 'acc-visa-4914', label: 'Chase Credit', key: 'visaCredit' }
              ].map(item => (
                <div key={item.id} className="flex justify-between items-center h-8">
                  <span>{item.label}</span>
                  {isEditMode ? (
                    <input 
                      type="number" 
                      step="0.01"
                      value={state.accounts.find(a => a.id === item.id)?.balance || 0}
                      onChange={(e) => setAccountBalance(item.id, parseFloat(e.target.value) || 0)}
                      className="w-24 px-2 py-0.5 bg-slate-800 border border-slate-700 rounded text-right text-[10px] text-white focus:ring-1 focus:ring-blue-500 focus:outline-none"
                    />
                  ) : (
                    <span className={reconciliation[item.key as keyof typeof reconciliation] < 0 ? 'text-red-400' : 'text-white'}>
                      {formatCurrency(reconciliation[item.key as keyof typeof reconciliation] as number)}
                    </span>
                  )}
                </div>
              ))}

              <div className="pt-2 border-t border-slate-800 flex justify-between text-blue-400">
                <span>Debit Balance</span>
                <span>{formatCurrency(reconciliation.debitBalance)}</span>
              </div>

              <div className="flex justify-between text-red-400">
                <span>Credit Balance</span>
                <span>{formatCurrency(reconciliation.creditBalance)}</span>
              </div>

              <div className="pt-2 border-t border-slate-800 flex justify-between text-white text-sm font-black">
                <span>Net</span>
                <span>{formatCurrency(reconciliation.net)}</span>
              </div>

              <div className="flex justify-between text-slate-500">
                <span>Allocated (Total Budget)</span>
                <span>{formatCurrency(-reconciliation.totalAllocated)}</span>
              </div>

              <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                <div>
                  <span className="text-[9px] text-slate-500 block mb-1">Difference (Update Budget)</span>
                  <span className={`text-2xl font-black ${Math.abs(reconciliation.difference) < 0.01 ? 'text-green-400' : 'text-blue-500'}`}>
                    {formatCurrency(reconciliation.difference)}
                  </span>
                </div>
                <AlertCircle size={28} className={Math.abs(reconciliation.difference) < 0.01 ? 'text-green-900' : 'text-blue-900'} />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Undo Last Confirmation Modal */}
      {showUndoConfirm && lastTransaction && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in zoom-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden relative border border-slate-200">
            <div className="p-8 text-center space-y-6">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-blue-50 text-blue-600 mb-2">
                <RotateCcw size={24} />
              </div>
              <h4 className="text-base font-bold text-slate-800 leading-tight uppercase tracking-tight">
                Undo Last Transaction?
              </h4>
              <div className="p-5 bg-slate-50 rounded-2xl text-left space-y-3">
                <div className="flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  <span>{formatDisplayDate(lastTransaction.date)}</span>
                  <span className={lastTransaction.amount < 0 ? 'text-red-500' : 'text-blue-600'}>
                    {formatCurrency(lastTransaction.amount)}
                  </span>
                </div>
                <div className="space-y-1">
                  <p className="text-[11px] font-black text-slate-800 uppercase tracking-tight truncate">
                    {lastTransaction.description || lastTransaction.type}
                  </p>
                  <div className="flex items-center gap-2 text-[9px] font-bold text-slate-400 uppercase">
                    <span className="bg-white px-2 py-0.5 rounded border border-slate-200">{getAccountName(lastTransaction.accountId)}</span>
                    <span className="text-slate-300">→</span>
                    <span className="bg-white px-2 py-0.5 rounded border border-slate-200">{getCategoryName(lastTransaction.categoryId)}</span>
                  </div>
                </div>
              </div>
              <p className="text-[11px] text-slate-400 uppercase tracking-widest font-black leading-relaxed">
                Confirming this will permanently remove the record and revert all balances.
              </p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setShowUndoConfirm(false)}
                  className="flex-1 px-4 py-3 rounded-xl border-2 border-slate-100 text-[11px] font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleConfirmUndo}
                  className="flex-1 px-4 py-3 rounded-xl bg-slate-900 text-white text-[11px] font-black uppercase tracking-widest hover:bg-blue-600 transition-all shadow-lg"
                >
                  Confirm Undo
                </button>
              </div>
            </div>
            <button 
              onClick={() => setShowUndoConfirm(false)}
              className="absolute top-4 right-4 p-1 text-slate-300 hover:text-slate-600 transition-colors"
            >
              <X size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

